// Captures PayPal Express Checkout return params synchronously at module load,
// BEFORE React renders or any effect can rewrite the URL (e.g. BillingContainer's
// history.replaceState on tab change). Authorize.Net redirects the buyer back to
// our page with ?paypal_return=1&PayerID=... (or ?paypal_cancel=1 on cancel).

const params = new URLSearchParams(window.location.search);

const captured = {
  isReturn: params.get('paypal_return') === '1',
  isCancel: params.get('paypal_cancel') === '1',
  // Authorize.Net appends "PayerID"; accept a couple of casings defensively.
  payerId: params.get('PayerID') || params.get('payerID') || params.get('payerId') || null,
};

let consumed = false;

/**
 * Returns the captured PayPal return snapshot exactly once, then null on any
 * subsequent call. Also strips the PayPal params from the URL so a manual
 * refresh can't re-trigger the completion.
 *
 * @returns {{isReturn: boolean, isCancel: boolean, payerId: (string|null)}|null}
 */
export function consumePayPalReturn() {
  if (consumed) {
    return null;
  }
  consumed = true;

  if (!captured.isReturn && !captured.isCancel) {
    return null;
  }

  // Clean the PayPal params out of the URL (keep any other query/hash).
  try {
    const url = new URL(window.location.href);
    ['paypal_return', 'paypal_cancel', 'PayerID', 'payerID', 'payerId'].forEach((k) =>
      url.searchParams.delete(k)
    );
    window.history.replaceState(null, '', url.pathname + url.search + url.hash);
  } catch (e) {
    // Non-fatal — worst case the params linger in the URL.
  }

  return { ...captured };
}
