import React, { useState, useContext, useEffect } from 'react';
import {
  Button,
  Tooltip,
  useToast
} from '@chakra-ui/react';
import { Heart } from 'lucide-react';
import { ConfigContext } from '../config/Config';
import { useDataCache } from '../services/DataCache';
import { useTranslation } from 'react-i18next';

const FavoriteButton = ({ itemId, initialIsFollowing = false, onFavoriteChange, displayMode = 'full' }) => {
  const { t } = useTranslation();
  const [isFollowing, setIsFollowing] = useState(initialIsFollowing);
  const [isLoading, setIsLoading] = useState(false);
  const [isMobile, setIsMobile] = useState(false);
  const config = useContext(ConfigContext);
  const { patchItemsBs } = useDataCache();
  const toast = useToast();

  // Detect mobile screen size
  useEffect(() => {
    const checkMobile = () => {
      setIsMobile(window.innerWidth < 768);
    };

    checkMobile();
    window.addEventListener('resize', checkMobile);

    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  const handleToggleFavorite = async () => {
    if (!config.accessToken) {
      toast({
        title: t('myFavorites.loginRequired'),
        status: 'warning',
        duration: 3000,
        isClosable: true,
      });
      return;
    }

    setIsLoading(true);
    try {
      // Toggle favorite using DataCache
      await patchItemsBs(
        itemId,
        { favorite: !isFollowing },
        config.backendUrl,
        config.accessToken
      );

      setIsFollowing(!isFollowing);

      if (onFavoriteChange) {
        onFavoriteChange(!isFollowing);
      }

      toast({
        title: isFollowing ?
            t('myFavorites.removeSuccess') :
            t('myFavorites.addSuccess'),
        status: 'success',
        duration: 3000,
        isClosable: true,
      });
    } catch (error) {
      toast({
        title: isFollowing ?
            t('myFavorites.errorRemoving') :
            t('myFavorites.errorAdding'),
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
    } finally {
      setIsLoading(false);
    }
  };

  const buttonText = isFollowing ?
    t('myFavorites.following') :
    t('myFavorites.followThisLot');

  const tooltipText = isFollowing ?
    t('myFavorites.removeTooltip') :
    t('myFavorites.addTooltip');

  // Determine if we should show icon only
  // iconOnly: mobile (any mode) OR desktop grid mode
  // full: desktop teaser/full mode
  const shouldShowIconOnly = isMobile || displayMode === 'grid';

  return (
    <Tooltip
      label={tooltipText}
      hasArrow
    >
      <Button
        variant="link"
        className="follow-lot"
        onClick={handleToggleFavorite}
        isLoading={isLoading}
        leftIcon={<Heart size={20} fill={isFollowing ? "currentColor" : "none"} />}
      >
        {!shouldShowIconOnly && buttonText}
      </Button>
    </Tooltip>
  );
};

export default FavoriteButton;