// common/domain/liveSale/pusherEvents.js
//
// Pure decoding of pusher payloads for the live sale page — a React
// implementation of the Elm bidder live-auction page.
//
// SOURCE OF TRUTH (Elm, circuit-bid/client/src/elm):
//   - Pusher/Model.elm    -> event names / PusherEventData variants
//   - Pusher/Decoder.elm  -> decodePusherEvent (bidder-relevant branches)
//
// WIRE NOTE: the Elm app's JS bridge JSON.parses the outer payload before
// handing it to the decoder, and raw pusher-js does the same automatically
// when the payload is JSON. `normalizePayload` re-parses defensively in case
// a payload arrives as a string. The decoded object corresponds to Elm's
// `data` field — e.g. Elm's `requiredAt ["data","uuid"]` is `payload.uuid`
// here.
//
// This module is pure: no network, no React, no i18n.

import { normalizeBid, normalizeCalculatedItem } from './items';
import { normalizeMessage } from './messages';
import { normalizeSaleUpdate } from './saleModel';

/** Every event the live sale page binds (Pusher/Model.elm eventNames, minus
 * the clerk/auctioneer-only `control_list__statement_updated`). Live internet
 * bids now arrive as `lot_tick`; the older bid__/item__/message__create
 * names stay bound for mixed deploys. */
export const LIVE_SALE_EVENTS = [
  'bid__delete',
  'bid__update',
  'bidder_info__update',
  'credit_request__create',
  'credit_request__update',
  'item__update',
  'item__unpublished',
  'item__published',
  'lot_tick',
  'message__create',
  'sale__update',
  'livequeue__post_execute',
  'clerk__sale__queued_bids_update',
  'clerk__sale__active_to_going_update',
  'force_reload',
];

/** Nested compact item on a public lot_tick for this lot, or null.
 * Overlay-only ticks have no item. A tick for a different uuid is ignored. */
export function nestedItemFromLotTick(data, itemUuid) {
  const item = data && data.item;
  if (!item || typeof item !== 'object') return null;
  if (itemUuid && item.uuid && item.uuid !== itemUuid) return null;
  return item;
}

function normalizePayload(data) {
  if (typeof data === 'string') {
    try {
      return JSON.parse(data);
    } catch (e) {
      return null;
    }
  }
  return data || null;
}

/** Full REST bid at `result.0`, or slim `{id, amount, status, item, bidder_id?}`
 * at the top level or nested as `result.0` (Pusher/Decoder.elm
 * decodePlaceBidLiveQueueResult). */
function placeBidPairFromResult(result) {
  if (!result || typeof result !== 'object') return null;
  if (result.id != null) return result;
  const nested = result['0'] ?? result[0];
  return nested && nested.id != null ? nested : null;
}

/**
 * The queued-bid result of a `livequeue__post_execute` payload
 * (Pusher/Decoder.elm decodeLiveQueuePostExecuteResult). Only the place-bid
 * labels matter to the bidder page; everything else maps to `other` (the Elm
 * update ignores those variants for bidders).
 */
function decodeLiveQueueResult(payload) {
  if (payload.label !== 'hedley_live_queue_place_bid') {
    return { kind: 'other' };
  }
  if (payload.status === 'Processed') {
    const pair = placeBidPairFromResult(payload.result);
    if (!pair || pair.id == null) return { kind: 'other' };
    return {
      kind: 'placeBidSuccess',
      bidKey: String(pair.id),
      bid: normalizeBid(pair),
    };
  }
  if (payload.status === 'Failed') {
    return {
      kind: 'placeBidFailure',
      error: typeof payload.result === 'string' ? payload.result : '',
    };
  }
  return { kind: 'other' };
}

/**
 * Decode one pusher event into a tagged object, or null when the payload is
 * malformed / the event is not one the bidder page consumes.
 *
 * @param {string} eventName  The pusher event name.
 * @param {*} data            The raw payload from pusher-js.
 * @param {object} [opts]
 * @param {number} [opts.nowMs]  Client clock (auto-clerk skew adjustment).
 * @returns {?object} One of:
 *   { type:'saleUpdate', data: <normalizeSaleUpdate> }
 *   { type:'itemUpdate', uuid, calculated }
 *   { type:'itemUnpublished', uuid }
 *   { type:'itemPublished', uuid, itemId, lotId }
 *   { type:'messageCreate', message }
 *   { type:'bidDelete', deletionType:'delete'|'changed_to_floor', itemId, bidKey, bid }
 *   { type:'bidUpdate', itemId, bidKey, bid }
 *   { type:'lotTick', itemUpdate?, overlay?, bidUpdate?, bidDelete? }
 *   { type:'bidderInfoUpdate' }
 *   { type:'creditRequestCreate'|'creditRequestUpdate', id, raw }
 *   { type:'liveQueuePostExecute', taskId, result }
 *   { type:'clerkQueuedBidsUpdate', bid, nextBid }
 *   { type:'clerkActiveToGoing' }
 *   { type:'forceReload' }
 */
export function decodePusherEvent(eventName, data, { nowMs = 0 } = {}) {
  const payload = normalizePayload(data);

  switch (eventName) {
    case 'sale__update': {
      const update = normalizeSaleUpdate(payload);
      return update ? { type: 'saleUpdate', data: update } : null;
    }

    case 'item__update': {
      if (!payload || payload.uuid == null) return null;
      return {
        type: 'itemUpdate',
        uuid: payload.uuid,
        calculated: normalizeCalculatedItem(payload, nowMs),
      };
    }

    case 'item__unpublished': {
      if (!payload || payload.uuid == null) return null;
      return { type: 'itemUnpublished', uuid: payload.uuid };
    }

    case 'item__published': {
      if (!payload || payload.uuid == null || payload.item_id == null || payload.lot == null) {
        return null;
      }
      const itemId = parseInt(payload.item_id, 10);
      if (!Number.isFinite(itemId)) return null;
      return {
        type: 'itemPublished',
        uuid: payload.uuid,
        itemId,
        lotId: String(payload.lot),
      };
    }

    case 'message__create': {
      const message = normalizeMessage(payload, { fromPusher: true });
      return message ? { type: 'messageCreate', message } : null;
    }

    case 'bid__delete': {
      if (!payload || payload.id == null) return null;
      return {
        type: 'bidDelete',
        // Wire: changed_to_floor is a bool (Pusher/Decoder.elm decodeDeletionType).
        deletionType: payload.changed_to_floor ? 'changed_to_floor' : 'delete',
        itemId: parseInt(payload.item) || 0,
        bidKey: String(payload.id),
        bid: normalizeBid(payload),
      };
    }

    case 'bid__update': {
      if (!payload || payload.id == null) return null;
      return {
        type: 'bidUpdate',
        itemId: parseInt(payload.item) || 0,
        bidKey: String(payload.id),
        bid: normalizeBid(payload),
      };
    }

    case 'lot_tick': {
      // Combined item+bid tick (Pusher/Decoder.elm decodeLotTick). Either
      // side may be omitted or null. Nested deleted bid → bidDelete.
      // Privileged overlay is decoded but the bidder reducer ignores it.
      const event = { type: 'lotTick' };
      if (!payload) return event;
      const item = payload.item;
      if (item && item.uuid != null) {
        event.itemUpdate = {
          uuid: item.uuid,
          calculated: normalizeCalculatedItem(item, nowMs),
        };
      }
      const overlay = payload.overlay;
      if (overlay && overlay.uuid != null) {
        event.overlay = {
          uuid: overlay.uuid,
          calculated: normalizeCalculatedItem(overlay, nowMs),
        };
      }
      const nestedBid = payload.bid;
      if (nestedBid && nestedBid.id != null) {
        const bidEvent = {
          itemId: parseInt(nestedBid.item) || 0,
          bidKey: String(nestedBid.id),
          bid: normalizeBid(nestedBid),
        };
        if (nestedBid.deleted) {
          event.bidDelete = {
            ...bidEvent,
            deletionType: nestedBid.changed_to_floor ? 'changed_to_floor' : 'delete',
          };
        } else {
          event.bidUpdate = bidEvent;
        }
      }
      return event;
    }

    case 'bidder_info__update':
      // The page only invalidates/refetches bidder info; no payload needed.
      return { type: 'bidderInfoUpdate' };

    case 'credit_request__create':
    case 'credit_request__update': {
      if (!payload) return null;
      return {
        type:
          eventName === 'credit_request__create'
            ? 'creditRequestCreate'
            : 'creditRequestUpdate',
        id: payload.id != null ? String(payload.id) : null,
        raw: payload,
      };
    }

    case 'livequeue__post_execute': {
      // Match key: payload.id (Pusher/Decoder.elm requiredAt ["data","id"]) —
      // NOT the embedded result task_id.
      if (!payload || payload.id == null) return null;
      return {
        type: 'liveQueuePostExecute',
        taskId: String(payload.id),
        result: decodeLiveQueueResult(payload),
      };
    }

    case 'clerk__sale__queued_bids_update': {
      if (!payload) return null;
      return {
        type: 'clerkQueuedBidsUpdate',
        bid: payload.bid != null ? parseInt(payload.bid) : null,
        nextBid: payload.next_bid != null ? parseInt(payload.next_bid) : null,
      };
    }

    case 'clerk__sale__active_to_going_update':
      return { type: 'clerkActiveToGoing' };

    case 'force_reload':
      return { type: 'forceReload' };

    default:
      return null;
  }
}
