import React from 'react';
import { Trans } from 'react-i18next';

export const CIRCUIT_AUCTION_URL = 'https://circuitauction.com/';

/**
 * Small "Auction Software by Circuit AI © <year>" line rendered under the main
 * embedded pages (item, sale, sales list, login, register, forgot password,
 * subscription magazine, prices realized). The whole phrase is the anchor
 * text on purpose — it is the circuitauction.com SEO backlink.
 */
const PoweredBy = () => {
  const year = new Date().getFullYear();
  return (
    <div className="powered-by" data-testid="powered-by">
      <Trans i18nKey="poweredBy.label" values={{ year }}>
        {/* rel="noopener" only: "noreferrer" would hide the referring auction
            house from circuitauction.com analytics, which defeats the backlink. */}
        {/* eslint-disable-next-line react/jsx-no-target-blank */}
        <a href={CIRCUIT_AUCTION_URL} target="_blank" rel="noopener">Auction Software by Circuit AI</a> © {{ year }}
      </Trans>
    </div>
  );
};

export default PoweredBy;
