import React, { useState, useEffect, useContext } from 'react';
import {
  ConfigContext,
  formatCurrencyAmount,
} from '../config/Config';
import { FileText, Filter, Info, Truck } from 'lucide-react';
// Chakra primitives we keep restyling in place: Table family for the
// responsive invoice grid, Spinner for loading, Badge for the per-row
// status pill (will be replaced by .interests-pill style next pass).
import {
  Table, Tbody, Tr, Th, Td,
  Text, Box, Spinner, Flex,
} from '@chakra-ui/react';
import { ExternalLink } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import TransactionList from './TransactionList';
import ShipmentDetails from './ShipmentDetails';
import Checkout from './Checkout';
import { completePayPalPayment } from '../services/PaymentProcessor';
import { consumePayPalReturn } from '../lib/paypalReturn';
import { LinkLanguage } from '../components/ItemLink';

const BillingPage = ({ savedCards = [], isLoadingPaymentMethods = false }) => {
  const { t } = useTranslation();
  const config = useContext(ConfigContext);
  const [billingData, setBillingData] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);
  const [expandedInvoices, setExpandedInvoices] = useState({});
  const [expandedShipments, setExpandedShipments] = useState({});
  const [statusFilter, setStatusFilter] = useState('all');
  const [loadingTransactions, setLoadingTransactions] = useState({});
  const [boUserData, setBoUserData] = useState(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalCount, setTotalCount] = useState(0);
  const itemsPerPage = 20; 
  const [checkoutInvoiceId, setCheckoutInvoiceId] = useState(null);
  const [lastPaymentResponse, setLastPaymentResponse] = useState(null);
  const [paypalNotice, setPaypalNotice] = useState(null);
  const [isCompletingPaypal, setIsCompletingPaypal] = useState(false);

  // Fetch BO user data to get customer_number
  useEffect(() => {
    const fetchBoUserData = async () => {
      try {
        if (!config.userData || !config.userData.uuid || !config.userData.bo_access_token) {
          return;
        }
        
        const response = await fetch(
          `${config.siteData.backoffice_url_lang}/api/v1.0/datatable-clients?fields=id&filter[uuid][value]=${config.userData.uuid}`,
          { headers: { 'access-token': config.userData.bo_access_token } }
        );
        
        if (!response.ok) {
          throw new Error('Failed to fetch user data');
        }
        
        const result = await response.json();
        const userData = result.data[0];
        setBoUserData(userData);
      } catch (error) {
        console.error('Failed to fetch BO user data:', error);
        setError(error.message);
      }
    };

    if (config.siteData?.backoffice_url && config.userData?.bo_access_token) {
      fetchBoUserData();
    }
  }, [config.siteData?.backoffice_url, config.siteData?.backoffice_url_lang, config.userData]);

  useEffect(() => {
    const fetchBillingData = async () => {
      try {
        if (!config.siteData?.backoffice_url || !config.userData?.bo_access_token) {
          setError('Missing configuration or authentication data');
          setIsLoading(false);
          return;
        }

        if (!boUserData?.id) {
          setError('No owner ID found. Unable to load billing data.');
          setIsLoading(false);
          return;
        }

        // Build API URL with query parameters
        const baseUrl = `${config.siteData.backoffice_url_lang}/api/v1.0/orders`;
        const params = new URLSearchParams({
          // Fields to return
          'fields': [
            'sale',
            'deduct_from_same_owner_cs',
            'same_owner_cs',
            'amount_due',
            'lock_date',
            'last_invoice_pdf',
            'id',
            'order_id',
            'total_invoice',
            'payment_received_raw',
            'status',
            'owner_language'
          ].join(','),

          // Filters
          'filter[owner][value]': boUserData.id,
          'filter[type][conjunction]': 'AND',
          'filter[type][operator]': '=',
          'filter[type][value]': 'bidder',
          'filter[status][conjunction]': 'AND',
          'filter[status][operator]': '<>',
          'filter[status][value]': 'canceled',

          // Pagination and sorting
          'page': currentPage,
          'range': itemsPerPage,
          'sort': '-lock_date'
        });

        const apiUrl = `${baseUrl}?${params.toString()}`;

        const response = await fetch(apiUrl, {
          headers: { 'access-token': config.userData.bo_access_token },
        });
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        
        const apiData = await response.json();

        setTotalCount(apiData.count || 0);
        
        // Transform API data to match our component structure
        const transformedData = {
          invoices: apiData.data.map(order => {

            const userLanguage = order.owner_language || 'en';

            return {
              id: order.order_id || order.id,
              internalId: order.id,
              saleLabel: order.sale?.label?.[userLanguage] || order.sale?.label?.en || order.sale?.label || '',
              date: order.lock_date ? new Date(order.lock_date).toISOString().split('T')[0] : new Date().toISOString().split('T')[0],
              dueDate: null, // API doesn't provide due date
              totalAmount: parseFloat(order.total_invoice || 0),
              paidAmount: (order.deduct_from_same_owner_cs && order.same_owner_cs !== null && order.same_owner_cs !== undefined) ? parseFloat(order.total_invoice || 0) : parseFloat(order.payment_received_raw || 0),
              remainingAmount: (order.deduct_from_same_owner_cs && order.same_owner_cs !== null && order.same_owner_cs !== undefined) ? 0 : Math.abs(parseFloat(order.amount_due || 0)),
              currency: config.siteData.currency || "USD",
              status: determineStatus(order.payment_received_raw, order.total_invoice, order.deduct_from_same_owner_cs, order.same_owner_cs),
              pdfUrl: order.last_invoice_pdf?.url || null,
              customerNumber: order.customer_number,
              ownerName: order.owner_name,
              country: order.country,
              itemCount: order.item_count,
              bidderIds: order.bidder_ids,
              isConsignmentSettled: (order.deduct_from_same_owner_cs && order.same_owner_cs !== null && order.same_owner_cs !== undefined),
              transactions: [],
              shipments: []
            };
          })
        };

        // Fetch shipment/tracking info per order in parallel. An empty
        // response means the order hasn't shipped yet, so we leave
        // `shipments` empty and the table hides the shipment cell.
        await Promise.all(
          transformedData.invoices.map(async (invoice) => {
            try {
              const shipmentUrl = `${config.siteData.backoffice_url}/api/shipments?order=${invoice.internalId}&with_tracking=1&access_token=${config.userData.bo_access_token}`;
              const shipmentResponse = await fetch(shipmentUrl);
              if (!shipmentResponse.ok) {
                throw new Error(`HTTP error! status: ${shipmentResponse.status}`);
              }
              const shipmentData = await shipmentResponse.json();
              const allShipments = Array.isArray(shipmentData?.data) ? shipmentData.data : [];
              // The API can return shipments that aren't tied to this order,
              // so keep only those whose `order` (or combined orders) matches.
              const orderId = String(invoice.internalId);
              invoice.shipments = allShipments.filter((shipment) => {
                if (String(shipment.order) === orderId) return true;
                const combined = Array.isArray(shipment.combined_orders) ? shipment.combined_orders : [];
                return combined.map(String).includes(orderId);
              });
            } catch (error) {
              console.error(`Failed to fetch shipments for order ${invoice.internalId}:`, error);
              invoice.shipments = [];
            }
          })
        );

        setBillingData(transformedData);
        setIsLoading(false);
      } catch (error) {
        console.error('Failed to fetch billing data:', error);
        setError(error.message);
        setIsLoading(false);
      }
    };

    // Only fetch data when we have the required config and owner ID
    if (config.siteData?.backoffice_url && config.userData?.bo_access_token && boUserData?.id) {
      fetchBillingData();
    } else if (boUserData && !boUserData.id) {
      // If we have boUserData but no ID, show error
      setError('No owner ID found. Unable to load billing data.');
      setIsLoading(false);
    }
  }, [config.siteData?.backoffice_url, config.siteData?.backoffice_url_lang, config.siteData?.currency, config.userData?.bo_access_token, boUserData, currentPage, itemsPerPage]);


  const determineStatus = (paidAmount, totalAmount, deductFromSameOwnerCs, sameOwnerCs) => {
    const paid = parseFloat(paidAmount || 0);
    const total = parseFloat(totalAmount || 0);
    
    // If deducted from consignment statement AND has a consignment statement number, it's considered paid
    if (deductFromSameOwnerCs && sameOwnerCs !== null && sameOwnerCs !== undefined) return 'paid';

    if (total === 0) return 'unpaid';
    if (paid === 0) return 'unpaid';
    if (paid >= total) return 'paid';
    return 'partially_paid';
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  };

  const getStatusBadge = (status) => {
    const labels = {
      unpaid: t('billing.unpaid') || 'Unpaid',
      partially_paid: t('billing.partiallyPaid') || 'Partially Paid',
      paid: t('billing.paid') || 'Paid',
    };
    const key = labels[status] ? status : 'unpaid';
    return (
      <span className={`invoice-status invoice-status--${key.replace('_', '-')}`}>
        {labels[key]}
      </span>
    );
  };

  // Label for the shipment column button. With one shipment we show its
  // delivery status; with several we show the count.
  const getShipmentLabel = (shipments) => {
    if (shipments.length > 1) {
      return t('billing.shipmentCount', { count: shipments.length });
    }
    const status = shipments[0]?.delivery_status;
    return t(`billing.deliveryStatus.${status}`, { defaultValue: status });
  };

  // Status determines the pill color: delivered (received) is green,
  // anything in transit is gold.
  const getShipmentStatusClass = (shipments) => {
    const allReceived = shipments.length > 0 && shipments.every(s => s.delivery_status === 'received');
    return allReceived ? 'shipment-status--received' : 'shipment-status--sent';
  };

  const toggleShipment = (invoiceId) => {
    setExpandedShipments(prev => ({ ...prev, [invoiceId]: !prev[invoiceId] }));
  };

  const renderProgress = (paid, total) => {
    const pct = total > 0 ? Math.min(100, Math.max(0, (paid / total) * 100)) : 0;
    return (
      <div className="invoice-progress">
        <div className="invoice-progress__bar" role="progressbar" aria-valuenow={pct} aria-valuemin={0} aria-valuemax={100}>
          <div className="invoice-progress__fill" style={{ width: `${pct}%` }} />
        </div>
      </div>
    );
  };

  const getFilteredInvoices = () => {
    if (!billingData?.invoices) return [];
    
    if (statusFilter === 'all') {
      return billingData.invoices;
    }
    
    return billingData.invoices.filter(invoice => invoice.status === statusFilter);
  };

  const getStatusCount = (status) => {
    if (!billingData?.invoices) return 0;
    if (status === 'all') return billingData.invoices.length;
    return billingData.invoices.filter(invoice => invoice.status === status).length;
  };

  const getTransactionDescription = (transaction, t) => {
    let description = '';
    
    switch (transaction.transaction_type) {
      case 'cash':
        description = transaction.info || (t('billing.cashPayment') || 'Cash Payment');
        break;
      
      case 'bank_transfer':
        description = transaction.info ? `${t('billing.bankTransfer') || 'Bank Transfer'} - #${transaction.info}` : (t('billing.bankTransfer') || 'Bank Transfer');
        break;
      
      case 'cheque':
        description = transaction.cheque_number ? `${t('billing.cheque') || 'Cheque'} #${transaction.cheque_number}` : (t('billing.cheque') || 'Cheque');
        break;
      
      case 'credit_card':
        if (transaction.cc_type && transaction.cc_last_4_digit) {
          description = `${transaction.cc_type.charAt(0).toUpperCase() + transaction.cc_type.slice(1)} ${t('billing.endingIn') || 'ending in'} ${transaction.cc_last_4_digit}`;
        } else {
          description = t('billing.creditCard') || 'Credit Card';
        }
        break;
      
      case 'paypal':
        description = transaction.info ? `${t('billing.paypal') || 'PayPal'} - ${transaction.info}` : (t('billing.paypal') || 'PayPal');
        break;
      
      default:
        description = transaction.info || (t('billing.payment') || 'Payment');
    }
    
    // Add transferred currency info if it exists
    if (transaction.transferred_currency && transaction.transferred_amount) {
      description += ` (${t('billing.actualPaid') || 'Actual Paid'}: ${formatCurrencyAmount(transaction.transferred_amount, transaction.transferred_currency.toUpperCase(), 2)})`;
    }
    
    return description;
  };

  const fetchTransactions = async (invoice) => {
    if (invoice.transactions.length > 0 || invoice.isConsignmentSettled) {
      return;
    }

    setLoadingTransactions(prev => ({ ...prev, [invoice.id]: true }));

    try {
      const apiUrl = `${config.siteData.backoffice_url_lang}/api/transactions?filter[order][value][0]=${invoice.internalId}&filter[order][value][1]=${invoice.internalId}&filter[order][operator]=IN`;

      const response = await fetch(apiUrl, {
        headers: { 'access-token': config.userData.bo_access_token },
      });
      
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      
      const transactionData = await response.json();
      
      // Map the API data to the format expected by TransactionList
      const mappedTransactions = transactionData.data.map((transaction, index) => ({
        id: transaction.id || `transaction-${index}`,
        date: transaction.transaction_date,
        description: getTransactionDescription(transaction, t),
        method: transaction.transaction_type || 'bank_transfer',
        amount: parseFloat(transaction.amount || 0)
      }));

      
      
      // Update the invoice with transaction data
      setBillingData(prevData => ({
        ...prevData,
        invoices: prevData.invoices.map(inv => 
          inv.id === invoice.id 
            ? { ...inv, transactions: mappedTransactions }
            : inv
        )
      }));
    } catch (error) {
      console.error('Failed to fetch transactions:', error);
    } finally {
      setLoadingTransactions(prev => ({ ...prev, [invoice.id]: false }));
    }
  };

  const handlePaymentComplete = (invoiceId, paidAmount, paymentResponse) => {
    setLastPaymentResponse(paymentResponse);
    // Update the invoice in billing data
    setBillingData(prevData => {
      if (!prevData?.invoices) return prevData;
      return {
        ...prevData,
        invoices: prevData.invoices.map(inv => {
          if (inv.id === invoiceId) {
            const newPaidAmount = inv.paidAmount + paidAmount;
            const newRemainingAmount = Math.max(0, inv.totalAmount - newPaidAmount);
            const newStatus = newRemainingAmount === 0 ? 'paid' :
                            newPaidAmount > 0 ? 'partially_paid' : 'unpaid';

            return {
              ...inv,
              paidAmount: newPaidAmount,
              remainingAmount: newRemainingAmount,
              status: newStatus
            };
          }
          return inv;
        })
      };
    });

  };

  // Finish (or cancel) a PayPal Express Checkout that redirected back to this
  // page. Runs once auth is ready; the return params were captured at module
  // load by consumePayPalReturn() so BillingContainer's URL rewrites can't lose
  // them, and the pending context (refTransId/amount/invoice) was stashed in
  // localStorage before the redirect.
  useEffect(() => {
    if (!config.userData?.uuid || !config.userData?.bo_access_token) {
      // Wait for auth before consuming the return params, so the complete call
      // is authenticated and the uuid match below is meaningful.
      return;
    }

    const ret = consumePayPalReturn();
    if (!ret) {
      return;
    }

    const pendingRaw = localStorage.getItem('paypal_pending');
    localStorage.removeItem('paypal_pending');
    const pending = pendingRaw ? JSON.parse(pendingRaw) : null;

    if (ret.isCancel) {
      setPaypalNotice({ type: 'cancel', message: t('transactions.paypalCancelled') || 'PayPal payment was cancelled.' });
      return;
    }

    if (!ret.payerId || !pending || pending.clientUuid !== config.userData.uuid) {
      setPaypalNotice({ type: 'error', message: t('transactions.paypalFailed') || 'PayPal payment failed. Please try again.' });
      return;
    }

    // Idempotency: never fire two completes for the same set-up transaction.
    if (localStorage.getItem('paypal_completing') === pending.refTransId) {
      return;
    }
    localStorage.setItem('paypal_completing', pending.refTransId);

    const finish = async () => {
      setIsCompletingPaypal(true);
      try {
        const res = await completePayPalPayment({
          config,
          refTransId: pending.refTransId,
          payerId: ret.payerId,
          amount: pending.amount,
          currency: pending.currency,
          invoiceId: pending.invoiceId,
          invoiceData: { internalId: pending.internalId },
        });

        if (res.success) {
          setPaypalNotice({ type: 'success', message: t('transactions.paypalSuccessful') || 'PayPal Payment Successful!' });
          handlePaymentComplete(pending.invoiceId, pending.amount, { ...res, success: true });
        } else {
          setPaypalNotice({ type: 'error', message: res.error || (t('transactions.paypalFailed') || 'PayPal payment failed. Please try again.') });
        }
      } catch (err) {
        console.error('PayPal completion error:', err);
        setPaypalNotice({ type: 'error', message: t('transactions.paypalFailed') || 'PayPal payment failed. Please try again.' });
      } finally {
        setIsCompletingPaypal(false);
        localStorage.removeItem('paypal_completing');
      }
    };

    finish();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [config.userData?.uuid, config.userData?.bo_access_token]);

  if (isLoading) {
    return (
      <div className="billing-page--loading">
        <Spinner color="blue.500" size="xl" thickness="4px" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="cream-note cream-note--error" role="alert">
        <strong>{t('billing.error') || 'Error'}</strong>{error}
      </div>
    );
  }

  const InvoiceTableView = ({ invoices }) => (
    <Box>
      {/* Desktop Table - Hidden on mobile */}
      <Box display={{ base: 'none', md: 'block' }}>
        <Table variant="simple" sx={{
            'td, th': {
              px: 3,
              py: 6
            }
          }}>
          <thead>
            <Tr>
              <Th>{t('billing.invoiceNumber') || 'Invoice Number'}</Th>
              <Th>{t('billing.sale') || 'Sale'}</Th>
              <Th>{t('billing.date') || 'Date'}</Th>
              <Th>{t('billing.amount') || 'Amount'}</Th>
              <Th>{t('billing.status') || 'Status'}</Th>
              <Th>{t('billing.progress') || 'Progress'}</Th>
              <Th>{t('billing.shipment') || 'Shipment'}</Th>
              <Th>{t('billing.actions') || 'Actions'}</Th>
            </Tr>
          </thead>
          <Tbody>
            {invoices.map((invoice) => (
              <React.Fragment key={invoice.id}>
                <Tr>
                  <Td>
                    <LinkLanguage
                      basePath={invoice.pdfUrl}
                      isExternal
                      className="invoice-link"
                    >
                      <FileText size={14} aria-hidden="true" />
                      <span className="invoice-link__number">{invoice.id}</span>
                      <ExternalLink size={12} aria-hidden="true" className="invoice-link__external" />
                    </LinkLanguage>
                  </Td>
                  <Td>
                    <Box fontSize="sm" color="gray.700" maxW="220px">
                      {invoice.saleLabel}
                    </Box>
                  </Td>
                  <Td>{formatDate(invoice.date)}</Td>
                  <Td>
                    <span className="invoice-amount">
                      {formatCurrencyAmount(invoice.totalAmount, invoice.currency, 2)}
                    </span>
                  </Td>
                  <Td>{getStatusBadge(invoice.status)}</Td>
                  <Td>
                    <div className="invoice-progress-wrap">
                      {renderProgress(invoice.paidAmount, invoice.totalAmount)}
                      <p className="invoice-progress__label">
                        <strong>{formatCurrencyAmount(invoice.paidAmount, invoice.currency, 2)}</strong>
                        <span className="invoice-progress__divider">/</span>
                        {formatCurrencyAmount(invoice.totalAmount, invoice.currency, 2)}
                      </p>
                    </div>
                  </Td>
                  <Td>
                    {invoice.shipments.length > 0 ? (
                      <button
                        type="button"
                        className={`shipment-status ${getShipmentStatusClass(invoice.shipments)}${expandedShipments[invoice.id] ? ' is-open' : ''}`}
                        onClick={() => toggleShipment(invoice.id)}
                        aria-expanded={!!expandedShipments[invoice.id]}
                      >
                        <Truck size={12} aria-hidden="true" />
                        {getShipmentLabel(invoice.shipments)}
                      </button>
                    ) : (
                      <span className="shipment-status shipment-status--none">
                        {t('billing.notShipped') || 'Not shipped yet'}
                      </span>
                    )}
                  </Td>
                  <Td>
                    <Flex gap={2} wrap="wrap">
                      {invoice.status !== 'paid' && !isPhonePayment && (
                        <button
                          type="button"
                          className="bid-limit-submit"
                          onClick={() => setCheckoutInvoiceId(invoice.id)}
                        >
                          {t('billing.pay') || 'Pay'} {formatCurrencyAmount(invoice.remainingAmount, invoice.currency, 2)}
                        </button>
                      )}
                      {invoice.isConsignmentSettled ? (
                        <Text fontSize="sm" color="green.600" fontStyle="italic">
                          {t('billing.settledWithConsignmentStatement') || 'Settled with Consignment Statement'}
                        </Text>
                      ) : (
                        <button
                          type="button"
                          className="btn-secondary-action btn-secondary-action--gold"
                          disabled={!!loadingTransactions[invoice.id]}
                          onClick={() => {
                            if (!expandedInvoices[invoice.id]) {
                              fetchTransactions(invoice);
                            }
                            setExpandedInvoices(prev => ({
                              ...prev,
                              [invoice.id]: !prev[invoice.id]
                            }));
                          }}
                        >
                          {expandedInvoices[invoice.id]
                            ? t('billing.hideTransactions', { defaultValue: 'Hide Transactions' })
                            : t('billing.viewTransactions', { defaultValue: 'View Transactions' })}
                        </button>
                      )}
                    </Flex>
                  </Td>
                </Tr>
              {expandedInvoices[invoice.id] && checkoutInvoiceId !== invoice.id && (
                <Tr>
                  <Td colSpan={8}>
                    <TransactionList invoice={invoice} />
                  </Td>
                </Tr>
              )}
              {expandedShipments[invoice.id] && checkoutInvoiceId !== invoice.id && (
                <Tr>
                  <Td colSpan={8}>
                    <ShipmentDetails shipments={invoice.shipments} currency={invoice.currency} />
                  </Td>
                </Tr>
              )}
              {checkoutInvoiceId === invoice.id && (
                <Tr>
                  <Td colSpan={8}>
                    <Checkout
                      invoice={invoice}
                      savedCards={savedCards}
                      onClose={() => {
                        setCheckoutInvoiceId(null);
                        setLastPaymentResponse(null); // Reset when closing
                      }}
                      onPaymentComplete={handlePaymentComplete}
                      lastPaymentResponse={checkoutInvoiceId === invoice.id ? lastPaymentResponse : null}
                    />
                  </Td>
                </Tr>
              )}
              </React.Fragment>
            ))}
          </Tbody>
        </Table>
      </Box>

      {/* Mobile Cards - Hidden on desktop */}
      <Box display={{ base: 'block', md: 'none' }}>
        {invoices.map((invoice) => (
          <Box key={invoice.id} mb={4}>
            <Box bg="white" p={4} rounded="lg" shadow="sm" border="1px" borderColor="gray.200">
              <Flex justify="space-between" align="start" mb={3}>
                <Box>
                  <LinkLanguage
                    basePath={invoice.pdfUrl}
                    isExternal
                    className="invoice-link"
                  >
                    <FileText size={14} aria-hidden="true" />
                    <span className="invoice-link__number">{invoice.id}</span>
                    <ExternalLink size={12} aria-hidden="true" className="invoice-link__external" />
                  </LinkLanguage>
                  <Text fontSize="sm" color="gray.600" mt={1}>
                    {invoice.saleLabel}
                  </Text>
                  <Text fontSize="sm" color="gray.600" mt={1}>
                    {formatDate(invoice.date)}
                  </Text>
                </Box>
                {getStatusBadge(invoice.status)}
              </Flex>

              <Box mb={3}>
                <p className="invoice-amount">
                  {formatCurrencyAmount(invoice.totalAmount, invoice.currency, 2)}
                </p>
                <div className="invoice-progress-wrap">
                  {renderProgress(invoice.paidAmount, invoice.totalAmount)}
                  <p className="invoice-progress__label">
                    <strong>{formatCurrencyAmount(invoice.paidAmount, invoice.currency, 2)}</strong>
                    <span className="invoice-progress__divider">/</span>
                    {formatCurrencyAmount(invoice.totalAmount, invoice.currency, 2)}
                  </p>
                </div>
              </Box>

              <Flex direction="column" gap={2}>
                {invoice.status !== 'paid' && !isPhonePayment && (
                  <button
                    type="button"
                    className="bid-limit-submit billing-invoice__action"
                    onClick={() => setCheckoutInvoiceId(invoice.id)}
                  >
                    {t('billing.pay') || 'Pay'} {formatCurrencyAmount(invoice.remainingAmount, invoice.currency, 2)}
                  </button>
                )}

                {invoice.isConsignmentSettled ? (
                  <Text fontSize="sm" color="green.600" fontStyle="italic" textAlign="center">
                    {t('billing.settledWithConsignmentStatement') || 'Settled with Consignment Statement'}
                  </Text>
                ) : (
                  <button
                    type="button"
                    className="btn-secondary-action btn-secondary-action--gold billing-invoice__action"
                    disabled={!!loadingTransactions[invoice.id]}
                    onClick={() => {
                      if (!expandedInvoices[invoice.id]) {
                        fetchTransactions(invoice);
                      }
                      setExpandedInvoices(prev => ({
                        ...prev,
                        [invoice.id]: !prev[invoice.id]
                      }));
                    }}
                  >
                    {expandedInvoices[invoice.id]
                      ? t('billing.hideTransactions', { defaultValue: 'Hide Transactions' })
                      : t('billing.viewTransactions', { defaultValue: 'View Transactions' })}
                  </button>
                )}

                {invoice.shipments.length > 0 ? (
                  <button
                    type="button"
                    className={`shipment-status shipment-status--block ${getShipmentStatusClass(invoice.shipments)}${expandedShipments[invoice.id] ? ' is-open' : ''}`}
                    onClick={() => toggleShipment(invoice.id)}
                    aria-expanded={!!expandedShipments[invoice.id]}
                  >
                    <Truck size={12} aria-hidden="true" />
                    {expandedShipments[invoice.id]
                      ? t('billing.hideShipment', { defaultValue: 'Hide Shipment' })
                      : getShipmentLabel(invoice.shipments)}
                  </button>
                ) : (
                  <span className="shipment-status shipment-status--block shipment-status--none">
                    {t('billing.notShipped') || 'Not shipped yet'}
                  </span>
                )}
              </Flex>
            </Box>

            {expandedInvoices[invoice.id] && checkoutInvoiceId !== invoice.id && (
              <Box mt={2}>
                <TransactionList invoice={invoice} />
              </Box>
            )}
            {expandedShipments[invoice.id] && checkoutInvoiceId !== invoice.id && (
              <Box mt={2}>
                <ShipmentDetails shipments={invoice.shipments} currency={invoice.currency} />
              </Box>
            )}
            {checkoutInvoiceId === invoice.id && (
              <Box mt={2}>
                <Checkout
                  invoice={invoice}
                  savedCards={savedCards}
                  onClose={() => {
                    setCheckoutInvoiceId(null);
                    setLastPaymentResponse(null); // Reset when closing
                  }}
                  onPaymentComplete={handlePaymentComplete}
                  lastPaymentResponse={checkoutInvoiceId === invoice.id ? lastPaymentResponse : null}
                />
              </Box>
            )}
          </Box>
        ))}
      </Box>
    </Box>
  );


  const filteredInvoices = getFilteredInvoices();

  // Check if payment gateway is phone.
  // Serverless site configs use both spellings of this flag — accept either.
  const isPhonePayment =
    (config.siteConfig?.paymentGateway ?? config.siteConfig?.paymentGetaway) === 'phone';

  const statusFilters = [
    { value: 'all',            label: t('billing.all') || 'All' },
    { value: 'unpaid',         label: t('billing.unpaid') || 'Unpaid' },
    { value: 'partially_paid', label: t('billing.partiallyPaid') || 'Partially Paid' },
    { value: 'paid',           label: t('billing.paid') || 'Paid' },
  ];
  const totalPages = Math.ceil(totalCount / itemsPerPage);

  return (
    <div className="billing-page">
      {paypalNotice && (
        <div
          className={`cream-note ${
            paypalNotice.type === 'success'
              ? 'cream-note--success'
              : paypalNotice.type === 'cancel'
                ? 'cream-note--warning'
                : 'cream-note--error'
          }`}
          role="status"
        >
          <span>{paypalNotice.message}</span>
        </div>
      )}
      {isCompletingPaypal && (
        <div className="cream-note" role="status">
          <Spinner size="sm" thickness="3px" />
          <span>{t('transactions.paypalCompleting') || 'Finalizing your PayPal payment...'}</span>
        </div>
      )}
      {isPhonePayment && (
        <div className="cream-note cream-note--warning" role="status">
          <Info size={16} aria-hidden="true" />
          <span>
            {t('billing.phonePaymentNotice') || 'Your invoice will be processed with assisted payment. Continue adding items as needed - our billing team will reach out to arrange payment.'}
          </span>
        </div>
      )}

      <div className="billing-filter">
        <div className="billing-filter__label">
          <Filter size={14} aria-hidden="true" />
          <span>{t('billing.filterByStatus') || 'Filter by Status'}</span>
        </div>
        <div className="billing-filter__chips" role="group">
          {statusFilters.map((f) => (
            <button
              key={f.value}
              type="button"
              className={`billing-chip billing-chip--${f.value.replace('_', '-')}${statusFilter === f.value ? ' is-active' : ''}`}
              onClick={() => setStatusFilter(f.value)}
            >
              {f.label}
              <span className="billing-chip__count">{getStatusCount(f.value)}</span>
            </button>
          ))}
        </div>
      </div>

      <p className="billing-summary">
        {totalCount > 0 ? (
          <>
            {t('billing.showing') || 'Showing'}{' '}
            <strong>
              {((currentPage - 1) * itemsPerPage) + 1}-{Math.min(currentPage * itemsPerPage, totalCount)}
            </strong>{' '}
            {t('billing.of') || 'of'}{' '}
            <strong>{totalCount}</strong>{' '}
            {totalCount !== 1 ? (t('billing.invoices') || 'invoices') : (t('billing.invoice') || 'invoice')}
          </>
        ) : (
          <>{t('billing.showing') || 'Showing'} 0 {t('billing.invoices') || 'invoices'}</>
        )}
      </p>

      {filteredInvoices.length === 0 ? (
        <div className="cream-note cream-note--warning" role="status">
          <div>
            <strong>{t('billing.noInvoicesFound') || 'No invoices found'}</strong>
            <p style={{ margin: '4px 0 0' }}>
              {t('billing.noInvoicesMatchingFilter') || 'There are no invoices matching the selected filter criteria.'}
            </p>
          </div>
        </div>
      ) : (
        <InvoiceTableView invoices={filteredInvoices} />
      )}

      {totalCount > itemsPerPage && billingData?.invoices?.length > 0 && (
        <nav className="favorites-pagination billing-pagination" aria-label="Pagination">
          <p className="favorites-pagination__status">
            {t('billing.page') || 'Page'} <strong>{currentPage}</strong>{' '}
            {t('billing.of') || 'of'} <strong>{totalPages}</strong>
          </p>
          <div className="favorites-pagination__controls">
            <button
              type="button"
              className="favorites-pagination__btn"
              onClick={() => setCurrentPage((prev) => Math.max(prev - 1, 1))}
              disabled={currentPage === 1}
            >
              {t('billing.previous') || 'Previous'}
            </button>
            <button
              type="button"
              className="favorites-pagination__btn"
              onClick={() => setCurrentPage((prev) => Math.min(prev + 1, totalPages))}
              disabled={currentPage >= totalPages}
            >
              {t('billing.next') || 'Next'}
            </button>
          </div>
        </nav>
      )}
    </div>
  );
};

export default BillingPage;