/**
 * Customer branding resolved from the serverless get-config response.
 *
 * The per-site `siteConfig` carries `logo_url` and `label` (business name),
 * e.g. test-hk → the Heinrich Köhler logo. Both fields can be missing:
 * older hardcoded configs (jbullConfigLive) and mock data lack them, and the
 * config may not be fetched yet at first render — callers must tolerate
 * `{ logoUrl: null, label: null }`.
 */
export const getBranding = (config) => {
  const site = config?.siteConfig || config?.siteData || {};
  return {
    logoUrl: site.logo_url || null,
    label: site.label || null,
  };
};

/**
 * Kelleher (US/HK) lot page: caption instead of body; hide estimate,
 * group category, and catalogue.
 */
export const isKelleherSite = (config) => {
  if (!config) {
    return false;
  }
  const haystack = [
    config.siteName,
    config.siteConfig?.login_site_name,
    config.siteConfig?.label,
    config.siteData?.login_site_name,
    config.siteData?.label,
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();
  return haystack.includes('kelleher');
};
