import React, { useContext, useState } from 'react';
import fetchData from '../utils/Util';
import { ConfigContext } from '../config/Config';
import { useTranslation } from 'react-i18next';

const EyeIcon = () => (
  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
    <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" />
    <circle cx="12" cy="12" r="3" />
  </svg>
);

const EyeOffIcon = () => (
  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
    <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24" />
    <line x1="1" y1="1" x2="23" y2="23" />
  </svg>
);

const ChangePassword = () => {
  const { t } = useTranslation();
  const [formData, setFormData] = useState({
    password: '',
    confirmPassword: '',
  });
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [isConfirmPasswordTouched, setIsConfirmPasswordTouched] = useState(false);
  const [error, setError] = useState(null);
  const [successMessage, setSuccessMessage] = useState(null);
  const config = useContext(ConfigContext);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });

    if (e.target.name === 'confirmPassword') {
      setIsConfirmPasswordTouched(true);
    }
  };

  const togglePasswordVisibility = () => setShowPassword((s) => !s);
  const toggleConfirmPasswordVisibility = () => setShowConfirmPassword((s) => !s);

  const handleSubmit = (e) => {
    e.preventDefault();

    if (!formData.password) {
      setError(t('changePassword.passwordRequired', 'Please enter a new password.'));
      return;
    }

    if (formData.password !== formData.confirmPassword) {
      setError(t('changePassword.passwordMismatch'));
      return;
    }

    const resetPasswordData = {
      pass: formData.password,
    };
    fetchData(`${config.backendUrl}/api/me`, {
      method: 'PATCH',
      headers: {
        'Content-Type': 'application/json',
        'access-token': config.accessToken,
      },
      body: JSON.stringify(resetPasswordData),
    })
      .then(async (response) => {
        if (!response.ok) {
          // The error title lives in the response body, not on the Response.
          let title = null;
          try {
            title = (await response.json())?.title;
          } catch (parseErr) { /* non-JSON error body */ }
          throw new Error(title || t('changePassword.networkError'));
        }
        setSuccessMessage(t('changePassword.successMessage'));
        setError(null);
      })
      .catch((err) => {
        setError(err.message);
        setSuccessMessage(null);
      });
  };

  const passwordsMatch =
    isConfirmPasswordTouched &&
    formData.confirmPassword !== '' &&
    formData.password === formData.confirmPassword;
  const passwordsMismatch =
    isConfirmPasswordTouched && formData.password !== formData.confirmPassword;

  return (
    <form onSubmit={handleSubmit} className="acct-form">
      {successMessage && (
        <div className="cream-note cream-note--success" role="status">
          <strong>{t('changePassword.successTitle')}</strong>{successMessage}
        </div>
      )}
      {error && (
        <div className="cream-note cream-note--error" role="alert">
          <strong>{t('changePassword.errorTitle')}</strong>{error}
        </div>
      )}

      <div className="field">
        <label htmlFor="cp-password" className="field-label">
          {t('changePassword.newPasswordLabel')}
        </label>
        <div className="password-input-wrap">
          <input
            id="cp-password"
            type={showPassword ? 'text' : 'password'}
            name="password"
            value={formData.password}
            onChange={handleChange}
            placeholder={t('changePassword.newPasswordPlaceholder')}
            className="field-input"
            autoComplete="new-password"
          />
          <button
            type="button"
            className="password-toggle"
            onClick={togglePasswordVisibility}
            aria-label={showPassword ? t('changePassword.hidePassword') : t('changePassword.showPassword')}
          >
            {showPassword ? <EyeOffIcon /> : <EyeIcon />}
          </button>
        </div>
      </div>

      <div className="field">
        <label htmlFor="cp-confirm" className="field-label">
          {t('changePassword.confirmPasswordLabel')}
        </label>
        <div className="password-input-wrap">
          <input
            id="cp-confirm"
            type={showConfirmPassword ? 'text' : 'password'}
            name="confirmPassword"
            value={formData.confirmPassword}
            onChange={handleChange}
            onBlur={() => setIsConfirmPasswordTouched(true)}
            placeholder={t('changePassword.confirmPasswordPlaceholder')}
            className="field-input"
            autoComplete="new-password"
          />
          <button
            type="button"
            className="password-toggle"
            onClick={toggleConfirmPasswordVisibility}
            aria-label={showConfirmPassword ? t('changePassword.hidePassword') : t('changePassword.showPassword')}
          >
            {showConfirmPassword ? <EyeOffIcon /> : <EyeIcon />}
          </button>
        </div>
        {passwordsMismatch && (
          <span className="validation-message validation-message--err">
            {t('changePassword.passwordMismatch')}
          </span>
        )}
        {passwordsMatch && (
          <span className="validation-message validation-message--ok">
            {t('changePassword.passwordsMatch')}
          </span>
        )}
      </div>

      <div className="card-actions">
        <button type="submit" className="btn-primary-action">
          {t('changePassword.submitButton')}
        </button>
      </div>
    </form>
  );
};

export default ChangePassword;
