const localDev = ['localhost'];

// Hosts (and any of their subdomains) that must use their own serverless
// domain instead of the shared circuit.auction one.
const ownServerlessDomains = [
  { match: /(^|\.)heinrich-koehler\.de$/, config: 'heinrichKoehler' },
];

const useMockData = 0;

// Exported for tests: pass a hostname to check the mapping without touching
// window.location.
export function getServerlessURL(hostname = window.location.hostname) {
  // Site-specific serverless domains win over the environment mapping below.
  const ownDomain = ownServerlessDomains.find((entry) => entry.match.test(hostname));
  if (ownDomain) {
    return configs[ownDomain.config].serverless;
  }

  if (localDev.includes(hostname) || hostname.match(/ddev\.site/)) {
    // Opt-in to a fully local serverless via `<div id="circuit-setup" serverless="local">`.
    const setupEl = document.getElementById('circuit-setup');
    if (setupEl?.getAttribute('serverless') === 'local') {
      return configs.ddevLocalServerless.serverless;
    }
    return configs.ddevLocal.serverless;
  } else if (hostname.match(/dev-[a-z-]+\.circuit\.auction/)) {
    return configs.devPantheon.serverless;
  } else if (hostname.match(/test-[a-z-]+\.circuit\.auction/)) {
    return configs.testPantheon.serverless;
  }

  // Default to live serverless.
  return configs.livePantheon.serverless;
}

const getConfigByHostname = (() => {
  let config = null;

  return async () => {
    if (config) {
      return config;
    }

    const hostname = window.location.hostname;

    // For affiliates we want to pass the site name.
    const siteElement = document.getElementById('circuit-setup');
    let siteName;
    let hostName;
    if (siteElement) {
      siteName = siteElement.getAttribute('site');
      hostName = siteElement.getAttribute('hostname') || window.location.hostname;
    }
    else {
      const siteElement_legacy = document.getElementById('site-name');
      if (siteElement_legacy) {
        siteName = siteElement_legacy.getAttribute('site');
      }
      else {
        // Display error message if no site name is found.
        console.error('Circuit config - No site name found in the DOM.');
      }
      hostName = window.location.hostname;
    }

    // Check if this is a jbull host - return hardcoded config to bypass China firewall
    if (hostname === 'jbull.com' || hostname === 'www.jbull.com') {
      config = {
        ...jbullConfigLive,
        success: true,
        useMockData: useMockData,
      };
      return config;
    }

    const serverlessURL = getServerlessURL();
    // Provenance for the ?debug=1 panel: everything downstream ("Missing
    // backoffice URL" & co) traces back to this bootstrap fetch, so record
    // its outcome — success, HTTP error, or network/parse failure.
    const debugKey = `${hostName || ''}/${siteName || ''}`;
    const url = `${serverlessURL}get-config?hostname=${encodeURIComponent(hostName)}&sitename=${encodeURIComponent(siteName || '')}`;
    try {
      const response = await fetch(url, {
        method: 'GET',
      });

      if (response.ok) {
        config = await response.json();
        recordDataSource({
          endpoint: 'get-config',
          key: debugKey,
          source: 'network',
          status: response.status,
        });
      } else {
        recordDataSource({
          endpoint: 'get-config',
          key: debugKey,
          source: 'error',
          status: response.status,
          error: `Failed to fetch configuration: ${response.statusText || response.status}`,
        });
        console.error('Failed to fetch configuration:', response.statusText);
        return {
          ...configs.ddevLocal,
          success: false,
          useMockData: useMockData,
        };
      }
    } catch (error) {
      const entry = recordDataSource({
        endpoint: 'get-config',
        key: debugKey,
        source: 'error',
        error: String(error?.message || error),
      });
      // Only fetch-rejects warrant the reachability probe — a JSON parse
      // error (also caught here) means the server DID answer.
      if (entry && error?.name === 'TypeError') {
        diagnoseNetworkFailure(url).then((diagnosis) => {
          entry.diagnosis = diagnosis;
          notifyDataSources();
        });
      }
      console.error('Error fetching configuration:', error);
      return {
        ...configs.ddevLocal,
        success: false,
        useMockData: useMockData,
      };
    }

    return {
      ...config,
      success: true,
      useMockData: useMockData,
    };
  };
})();

export const ConfigContext = createContext(null);

export const ConfigProvider = ({ children }) => {
  const [config, setConfig] = useState({
    siteName: null,
    backendUrl: null,
    success: false,
    useMockData: 0,
    accessToken: null,
    siteData: {},
    userData: {},
    fetchUserData: null,
    setAccessToken: null,
  });
  const [loading, setLoading] = useState(true);

  const processSiteData = useCallback((rawSiteData) => {
    const siteData = { ...(rawSiteData || {}) };

    // Normalize connected_backoffices: the serverless returns either a single
    // { url } object (per-site override) or nothing. Consumers expect an array.
    if (siteData.connected_backoffices === undefined || siteData.connected_backoffices === null) {
      siteData.connected_backoffices = [];
    } else if (!Array.isArray(siteData.connected_backoffices)) {
      siteData.connected_backoffices = [siteData.connected_backoffices];
    }

    // if there is more than one language, add language prefix.
    if (siteData.languages && siteData.languages.length > 1) {
      const languageForServer = i18n.language === 'zh' ? 'zh-hans' : i18n.language;
      siteData.backoffice_url_lang = siteData.backoffice_url + '/' + languageForServer;
    }
    else {
      siteData.backoffice_url_lang = siteData.backoffice_url;
    }

    return siteData;
  }, []);

  const setAccessToken = useCallback((token) => {
    if (!token) {
      localStorage.removeItem('bs_access_token');
    } else {
      localStorage.setItem('bs_access_token', token);
    }
    setConfig((prevConfig) => ({
      ...prevConfig,
      accessToken: token,
    }));
  }, []);

  const fetchConfig = useCallback(async () => {
    try {
      const configData = await getConfigByHostname();
      console.log('Config data:', configData);

      const siteData = processSiteData(configData.siteConfig);

      setConfig((prevConfig) => ({
        ...configData,
        userData: prevConfig?.userData || null,
        siteData,
        accessToken: prevConfig?.accessToken,
        fetchUserData: fetchUserData,
        setAccessToken: setAccessToken,
      }));
    } catch (error) {
      console.error('Error fetching configuration:', error);
    }
    // fetchUserData is intentionally omitted from the deps: it is stored into
    // config state here, and depending on it would re-fetch the whole site
    // config every time the token changes.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [processSiteData, setAccessToken]);

  const fetchUserData = useCallback(async () => {
    try {
      if (config.accessToken && config.backendUrl) {
        // Check if force_bo_refresh flag is set in localStorage
        const forceRefresh = localStorage.getItem('force_bo_refresh');
        let url = `${config.backendUrl}/api/me`;

        // Append force_bo_refresh parameter if it exists in localStorage
        if (forceRefresh === '1') {
          url += '?force_bo_refresh=1';
          // Clear the flag after using it
          localStorage.removeItem('force_bo_refresh');
        }

        const response = await fetchData(
            url,
            {
              mockData: 'api-me',
              headers: { 'access-token': config.accessToken },
            }
        );

        if (response.ok) {
          const userData = await response.json();
          // If no bo token, then take from local storage.
          if (!userData.bo_access_token) {
            userData.bo_access_token = localStorage.getItem('bo_access_token') || null;
          }
          setConfig((prevConfig) => ({
            ...prevConfig,
            userData: userData,
          }));
        } else {
          console.log('User data response:', response);
          throw new Error('Failed to fetch user data');
        }
      } else {
        console.warn('Access token is empty. Skipping user data fetch.');
      }
    } catch (error) {
      console.error('Error fetching user data:', error);
    }
  }, [config.accessToken, config.backendUrl]);

  useEffect(() => {
    const fetchConfigAsync = async () => {
      const accessToken = localStorage.getItem('bs_access_token');
      setAccessToken(accessToken);
      console.log('Fetching config...');
      await fetchConfig();
      setLoading(false);
    };

    fetchConfigAsync();
  }, [fetchConfig, setAccessToken]);

  useEffect(() => {
    if (config.accessToken && config.backendUrl) {
      fetchUserData();
    }
  }, [config.accessToken, config.backendUrl, fetchUserData]);

  const loadCSS = useCallback((url) => {
    const link = document.createElement('link');
    link.rel = 'stylesheet';
    link.href = url;
    document.head.appendChild(link);
  }, []);

  useEffect(() => {
    if (config.siteData && config.siteData.backoffice_url) {
      const cssUrl = `${config.siteData.backoffice_url}/css/user-ui.css`;
      // const cssUrl = `user-ui.css`;
      loadCSS(cssUrl);
    }
  }, [config.siteData, loadCSS]);

  const memoizedConfig = useMemo(() => config, [config]);

  if (loading) {
    return <div>Loading configuration...</div>;
  }

  return (
    <ConfigContext.Provider value={memoizedConfig}>
      {children}
    </ConfigContext.Provider>
  );
};

export function formatCurrencyAmount(amount, currency, fractionDigits = 0) {
  if (amount === null || amount === undefined) {
    return '';
  }
  
  // Convert amount to number
  const numAmount = Number(amount);
  
  let formatted;
  const numberFormat = {
    minimumFractionDigits: fractionDigits,
    maximumFractionDigits: fractionDigits,
    useGrouping: true
  };

  switch (currency) {
    case 'CHF':
      formatted = `${numAmount.toLocaleString('de-CH', numberFormat)} CHF`;
      break;
    case 'EUR':
      formatted = `${numAmount.toLocaleString('de-DE', numberFormat)} €`;
      break;
    case 'HKD':
      formatted = `${numAmount.toLocaleString('en-US', numberFormat)} HK$`;
      break;
    case 'GBP':
      formatted = `${numAmount.toLocaleString('en-US', numberFormat)} £`;
      break;
    case 'ILS':
      formatted = `${numAmount.toLocaleString('en-US', numberFormat)} ₪`;
      break;
    case 'USD':
      formatted = `$${numAmount.toLocaleString('en-US', numberFormat)}`;
      break;
    case 'ZAR':
      formatted = `R ${numAmount.toLocaleString('en-US', numberFormat)}`;
      break;
    default:
      formatted = numAmount.toLocaleString('en-US', numberFormat);
  }
  return formatted;
}