/**
 * Mounts the widget tree only when the site-config bootstrap (get-config)
 * succeeded. When it failed (`config.success === false`) nothing downstream
 * can fetch — every widget would fire doomed requests and paint its own red
 * error box for what is one root cause. Instead, mount ONLY the error
 * report panel: the recorded get-config failure auto-opens it (friendly
 * "Oops" card with the diagnosis and the email-to-support action).
 *
 * Portaled to document.body inside a `.circuit-user-ui` scope wrapper
 * because the shared React root (#circuit-app-root) is display:none — the
 * widgets normally portal out of it themselves (same approach as
 * CacheInvalidationNotice).
 */
import React, { useContext } from 'react';
import { createPortal } from 'react-dom';
import { ConfigContext } from '../config/Config';
import DataSourceDebugPanel from './DataSourceDebugPanel';

const ConfigFailureGate = ({ children }) => {
  const config = useContext(ConfigContext);

  if (config?.success === false) {
    return createPortal(
      <div className="circuit-user-ui">
        <DataSourceDebugPanel />
      </div>,
      document.body
    );
  }

  return children;
};

export default ConfigFailureGate;
