import React, { useState, useEffect, useContext } from 'react';
import { useTranslation } from 'react-i18next';
import { ConfigContext } from '../config/Config';
import fetchData from '../utils/Util';
import { Spinner } from '@chakra-ui/react';
import { CircuitDropdown } from '../components/CircuitDropdown';
import { useDataCache } from '../services/DataCache';

const PricesRealized = () => {
    const { t, i18n } = useTranslation();
    const config = useContext(ConfigContext);
    const { fetchSalesPublic } = useDataCache();

    // Configuration from data attributes
    const [pageConfig, setPageConfig] = useState({
        saleNid: '',
        itemsPerPage: 40,
        columns: 4,
        showFilters: true,
        showLotFilter: true,
        showStatusFilter: true,
        showItemsPerPage: true,
        showPagination: true,
        title: 'Prices Realized',
    });

    const [items, setItems] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState(null);
    const [currentPage, setCurrentPage] = useState(() => {
        const params = new URLSearchParams(window.location.search);
        const pageParam = params.get('page');
        return pageParam ? Math.max(1, parseInt(pageParam)) : 1;
    });
    const [totalPages, setTotalPages] = useState(1);
    const [, setTotalItems] = useState(0);
    const [pdfSaleResult, setPdfSaleResult] = useState(null);
    const [sale, setSale] = useState(null);

    const [filters, setFilters] = useState(() => {
        const params = new URLSearchParams(window.location.search);
        return {
            lotStart: params.get('lotStart') || '',
            status: params.get('status') || '',
            itemsPerPage: parseInt(params.get('itemsPerPage') || '40'),
        };
    });

    const [formInputs, setFormInputs] = useState(() => {
        const params = new URLSearchParams(window.location.search);
        return {
            lotStart: params.get('lotStart') || '',
            status: params.get('status') || '',
            itemsPerPage: parseInt(params.get('itemsPerPage') || '40'),
        };
    });

    // Read configuration from data attributes on mount
    useEffect(() => {
        const container = document.getElementById('ca-prices-realized');
        if (container) {
            const newConfig = {};

            const datasaleNid = container.getAttribute('data-sale-nid');
            const dataItemsPerPage = container.getAttribute('data-items-per-page');
            const dataColumns = container.getAttribute('data-columns');
            const dataShowFilters = container.getAttribute('data-show-filters');
            const dataShowLotFilter = container.getAttribute('data-show-lot-filter');
            const dataShowStatusFilter = container.getAttribute('data-show-status-filter');
            const dataShowItemsPerPage = container.getAttribute('data-show-items-per-page');
            const dataShowPagination = container.getAttribute('data-show-pagination');
            const dataTitle = container.getAttribute('data-title');

            if (datasaleNid) newConfig.saleNid = datasaleNid;
            if (dataItemsPerPage) newConfig.itemsPerPage = parseInt(dataItemsPerPage);
            if (dataColumns) newConfig.columns = parseInt(dataColumns);
            if (dataShowFilters) newConfig.showFilters = dataShowFilters === 'true';
            if (dataShowLotFilter) newConfig.showLotFilter = dataShowLotFilter === 'true';
            if (dataShowStatusFilter) newConfig.showStatusFilter = dataShowStatusFilter === 'true';
            if (dataShowItemsPerPage) newConfig.showItemsPerPage = dataShowItemsPerPage === 'true';
            if (dataShowPagination) newConfig.showPagination = dataShowPagination === 'true';
            if (dataTitle) newConfig.title = dataTitle;

            setPageConfig(prev => ({ ...prev, ...newConfig }));

            const params = new URLSearchParams(window.location.search);
            if (!params.has('itemsPerPage') && dataItemsPerPage) {
                const perPage = parseInt(dataItemsPerPage);
                setFilters(prev => ({ ...prev, itemsPerPage: perPage }));
                setFormInputs(prev => ({ ...prev, itemsPerPage: perPage }));
            }
        }
    }, []);

    // Fetch prices realized data
    useEffect(() => {
        const fetchPricesRealized = async () => {
            if (!config.siteData || !pageConfig.saleNid) {
                // No sale to fetch — stop the spinner so the missing-nid
                // warning below the loading guard can actually render.
                setIsLoading(false);
                return;
            }

            setIsLoading(true);
            setError(null);

            try {
                const params = new URLSearchParams({
                    fields: 'lot,opening_price,sold_price,sold_status',
                    sale_id: pageConfig.saleNid,
                    range: filters.itemsPerPage,
                    sort: 'lot_number',
                });

                if (currentPage > 1) params.append('page', currentPage);
                if (filters.status) params.append('filter[sold_status]', filters.status);
                if (filters.lotStart) {
                    params.append('filter[lot_number][value]', filters.lotStart);
                    params.append('filter[lot_number][operator]', '>=');
                }

                const response = await fetchData(
                    `${config.siteData.backoffice_url_lang}/api/v1.0/items-public?${params.toString()}`
                );

                if (!response.ok) throw new Error('Failed to fetch prices realized data');

                const data = await response.json();
                setItems(data.data || []);

                if (data.count) {
                    setTotalItems(data.count);
                    setTotalPages(Math.ceil(data.count / filters.itemsPerPage));
                }
            } catch (err) {
                setError(err.message);
            } finally {
                setIsLoading(false);
            }
        };

        fetchPricesRealized();
    }, [config.siteData, pageConfig.saleNid, currentPage, filters]);

    // Fetch the sale to get the prices-realized PDF link
    useEffect(() => {
        if (!config.siteData || !pageConfig.saleNid) return;

        let cancelled = false;
        fetchSalesPublic(config.siteData.backoffice_url_lang, { saleNid: pageConfig.saleNid })
            .then(data => {
                if (cancelled) return;
                // API returns data as an array with one element
                const saleData = data.data?.[0] || data[0] || data;
                setSale(saleData || null);
                setPdfSaleResult(saleData?.pdf_sale_result || null);
            })
            .catch(err => {
                if (!cancelled) console.error('Error fetching sale PDF link:', err);
            });

        return () => { cancelled = true; };
    }, [config.siteData, pageConfig.saleNid, fetchSalesPublic]);

    // Resolve language-specific sale display fields.
    const getSaleDisplayData = (s) => {
        if (!s) return null;
        const lang = i18n.language === 'zh' ? 'zh-hans' : i18n.language;
        return {
            title: s.label?.[lang] || s.label?.en || '',
            dateLocation: s.date_and_location_string?.[lang] || s.date_and_location_string?.en || '',
        };
    };

    const handleFormInputChange = (inputName, value) => {
        setFormInputs(prev => ({ ...prev, [inputName]: value }));
    };

    const handleApplyFilters = (e) => {
        if (e?.preventDefault) e.preventDefault();
        setFilters({ ...formInputs });
        setCurrentPage(1);
    };

    const handleResetFilters = () => {
        const resetValues = {
            lotStart: '',
            status: '',
            itemsPerPage: pageConfig.itemsPerPage,
        };
        setFilters(resetValues);
        setFormInputs(resetValues);
        setCurrentPage(1);
    };

    // Update URL when page or filters change
    useEffect(() => {
        const params = new URLSearchParams();
        if (currentPage > 1) params.set('page', currentPage);
        if (filters.lotStart) params.set('lotStart', filters.lotStart);
        if (filters.status) params.set('status', filters.status);
        if (filters.itemsPerPage !== 40) params.set('itemsPerPage', filters.itemsPerPage);

        const newUrl = params.toString() ? `?${params.toString()}` : window.location.pathname;
        window.history.replaceState({}, '', newUrl);
    }, [currentPage, filters]);

    const handlePageChange = (page) => {
        setCurrentPage(page);
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    // Renders the right-most price/status cell of a row.
    const renderSoldCell = (item) => {
        const status = item.sold_status?.toLowerCase();
        if (status === 'sold') {
            return (
                <span className="pr-row__sold pr-row__sold--sold">
                    {item.sold_price?.formatted || t('pricesRealized.sold', 'Sold')}
                </span>
            );
        }
        if (status === 'unsold') {
            return (
                <span className="pr-row__sold pr-row__sold--unsold">
                    {t('pricesRealized.unsold', 'Unsold')}
                </span>
            );
        }
        if (status === 'withdrawn') {
            return (
                <span className="pr-row__sold pr-row__sold--withdrawn">
                    {t('pricesRealized.withdrawn', 'Withdrawn')}
                </span>
            );
        }
        return <span className="pr-row__sold pr-row__sold--unknown">—</span>;
    };

    const splitIntoColumns = (items, numColumns) => {
        const itemsPerColumn = Math.ceil(items.length / numColumns);
        const columns = [];
        for (let i = 0; i < numColumns; i++) {
            const start = i * itemsPerColumn;
            columns.push(items.slice(start, start + itemsPerColumn));
        }
        return columns;
    };

    const getPaginationRange = () => {
        const range = 2;
        const pages = [];

        if (currentPage > range + 1) {
            pages.push(1);
            if (currentPage > range + 2) pages.push('...');
        }

        for (let i = Math.max(1, currentPage - range); i <= Math.min(totalPages, currentPage + range); i++) {
            pages.push(i);
        }

        if (currentPage < totalPages - range) {
            if (currentPage < totalPages - range - 1) pages.push('...');
            pages.push(totalPages);
        }

        return pages;
    };

    if (isLoading) {
        return (
            <div className="prices-realized prices-realized--loading">
                <Spinner size="xl" />
            </div>
        );
    }

    if (error) {
        return (
            <div className="prices-realized">
                <div className="cream-note cream-note--error" role="alert">{error}</div>
            </div>
        );
    }

    if (!pageConfig.saleNid) {
        return (
            <div className="prices-realized">
                <div className="cream-note cream-note--warning" role="status">
                    {t('pricesRealized.nosaleNid', 'Please provide a sale UUID to view prices realized.')}
                </div>
            </div>
        );
    }

    const columns = splitIntoColumns(items, pageConfig.columns);
    const paginationRange = getPaginationRange();
    const saleDisplay = getSaleDisplayData(sale);

    return (
        <section className="prices-realized">
            <header className="prices-realized__sale-header">
                {pageConfig.title && (
                    <p className="prices-realized__kicker">{pageConfig.title}</p>
                )}
                {saleDisplay?.title && (
                    <h1 className="prices-realized__sale-title">{saleDisplay.title}</h1>
                )}
                {saleDisplay?.dateLocation && (
                    <p className="prices-realized__sale-date">{saleDisplay.dateLocation}</p>
                )}
            </header>

            {/* Filters */}
            {pageConfig.showFilters && (
                <form className="prices-realized__filters" onSubmit={handleApplyFilters}>
                    {pageConfig.showLotFilter && (
                        <div className="prices-realized__field">
                            <label className="prices-realized__label">
                                {t('pricesRealized.startAtLot', 'Start at Lot no')}
                            </label>
                            <input
                                type="number"
                                className="field-input"
                                value={formInputs.lotStart}
                                onChange={(e) => handleFormInputChange('lotStart', e.target.value)}
                                placeholder={t('pricesRealized.enterLotNumber', 'Enter lot number')}
                            />
                        </div>
                    )}

                    {pageConfig.showStatusFilter && (
                        <div className="prices-realized__field">
                            <label className="prices-realized__label">
                                {t('pricesRealized.status', 'Status')}
                            </label>
                            <CircuitDropdown
                                value={formInputs.status || ''}
                                ariaLabel={t('pricesRealized.status', 'Status')}
                                variant="compact"
                                onChange={(v) => handleFormInputChange('status', v)}
                                options={[
                                    { value: '', label: t('pricesRealized.any', 'Any') },
                                    { value: 'sold', label: t('pricesRealized.sold', 'Sold') },
                                    { value: 'unsold', label: t('pricesRealized.unsold', 'Unsold') },
                                ]}
                            />
                        </div>
                    )}

                    {pageConfig.showItemsPerPage && (
                        <div className="prices-realized__field">
                            <label className="prices-realized__label">
                                {t('pricesRealized.itemsPerPage', 'Items per page')}
                            </label>
                            <CircuitDropdown
                                value={String(formInputs.itemsPerPage)}
                                ariaLabel={t('pricesRealized.itemsPerPage', 'Items per page')}
                                variant="compact"
                                onChange={(v) => handleFormInputChange('itemsPerPage', parseInt(v))}
                                options={[
                                    { value: '40', label: '40' },
                                    { value: '80', label: '80' },
                                    { value: '100', label: '100' },
                                ]}
                            />
                        </div>
                    )}

                    <div className="prices-realized__actions">
                        <button type="submit" className="btn-primary-action">
                            {t('pricesRealized.apply', 'Apply')}
                        </button>
                        <button type="button" className="btn-secondary-action" onClick={handleResetFilters}>
                            {t('pricesRealized.reset', 'Reset')}
                        </button>
                        {pdfSaleResult?.url && (
                            <a
                                href={pdfSaleResult.url}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="pr-pdf-btn"
                            >
                                <svg
                                    className="pr-pdf-btn__icon"
                                    viewBox="0 0 24 24"
                                    width="16"
                                    height="16"
                                    aria-hidden="true"
                                    focusable="false"
                                >
                                    <path
                                        fill="currentColor"
                                        d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8l-6-6Zm0 1.5L18.5 8H14V3.5ZM8.7 12.6c.45 0 .8.12 1.03.36.24.23.36.55.36.95 0 .4-.12.72-.36.96-.24.23-.59.35-1.05.35h-.62V16H7.2v-3.4h1.5Zm-.04 1.95c.18 0 .31-.04.4-.13.09-.09.13-.21.13-.38s-.04-.29-.13-.37c-.09-.09-.22-.13-.4-.13h-.6v1.01h.6Zm3.04-1.95c.55 0 .98.16 1.29.47.31.31.46.74.46 1.28s-.15.97-.46 1.28c-.31.31-.74.47-1.29.47h-1.35v-3.5h1.35Zm-.05 2.74c.27 0 .48-.09.62-.26.14-.18.21-.43.21-.73s-.07-.55-.21-.72c-.14-.18-.35-.27-.62-.27h-.43v1.98h.43Zm4.86-2.74v.8h-1.4v.63h1.27v.78h-1.27V16h-.94v-3.4h2.34Z"
                                    />
                                </svg>
                                {t('pricesRealized.downloadPdf', 'Download PDF')}
                            </a>
                        )}
                    </div>
                </form>
            )}

            {/* Results */}
            {items.length === 0 ? (
                <p className="prices-realized__empty">
                    {t('pricesRealized.noResults', 'No items found matching your criteria.')}
                </p>
            ) : (
                <>
                    <div
                        className="prices-realized__grid"
                        style={{ '--pr-columns': pageConfig.columns }}
                    >
                        {columns.map((column, colIndex) => (
                            <div key={colIndex} className="prices-realized__column">
                                <header className="pr-row pr-row--header">
                                    <span className="pr-row__lot">{t('pricesRealized.lotNo', 'Lot no.')}</span>
                                    <span className="pr-row__opening">{t('pricesRealized.opening', 'Opening')}</span>
                                    <span className="pr-row__sold-label">{t('pricesRealized.soldFor', 'Sold for')}</span>
                                </header>

                                {column.map((item, itemIndex) => (
                                    <div key={itemIndex} className="pr-row">
                                        <span className="pr-row__lot">{item.lot || '—'}</span>
                                        <span className="pr-row__opening">
                                            {item.opening_price?.formatted || '—'}
                                        </span>
                                        {renderSoldCell(item)}
                                    </div>
                                ))}
                            </div>
                        ))}
                    </div>

                    {/* Pagination */}
                    {pageConfig.showPagination && totalPages > 1 && (
                        <nav className="prices-realized__pagination" aria-label="Pagination">
                            {currentPage > 1 && (
                                <button
                                    type="button"
                                    className="favorites-pagination__btn"
                                    onClick={() => handlePageChange(currentPage - 1)}
                                >
                                    « {t('pricesRealized.prev', 'prev')}
                                </button>
                            )}

                            {paginationRange.map((page, index) =>
                                page === '...' ? (
                                    <span key={`dots-${index}`} className="prices-realized__pagination-dots">…</span>
                                ) : (
                                    <button
                                        key={page}
                                        type="button"
                                        className={`favorites-pagination__btn favorites-pagination__btn--num${currentPage === page ? ' is-active' : ''}`}
                                        onClick={() => handlePageChange(page)}
                                        aria-current={currentPage === page ? 'page' : undefined}
                                    >
                                        {page}
                                    </button>
                                )
                            )}

                            {currentPage < totalPages && (
                                <>
                                    <button
                                        type="button"
                                        className="favorites-pagination__btn"
                                        onClick={() => handlePageChange(currentPage + 1)}
                                    >
                                        {t('pricesRealized.next', 'next')} »
                                    </button>
                                    <button
                                        type="button"
                                        className="favorites-pagination__btn"
                                        onClick={() => handlePageChange(totalPages)}
                                    >
                                        {t('pricesRealized.last', 'last')} »
                                    </button>
                                </>
                            )}
                        </nav>
                    )}
                </>
            )}
        </section>
    );
};

export default PricesRealized;
