/**
 * Backoffice items-json (and bid-server) fields that mean a lot is already
 * closed. Migrated historical lots often have no bid-server instance, so a
 * 400 "Sale is not synced with Bid server" is expected — callers must not
 * treat it as a user-facing failure.
 */
const CLOSED = new Set(['sold', 'unsold']);

const token = (value) => String(value || '').toLowerCase();

export function isSoldOrUnsold(item) {
  if (!item || typeof item !== 'object') return false;
  if (item.sale_status === 'finished') return true;
  return (
    CLOSED.has(token(item.sold_status)) ||
    CLOSED.has(token(item.sold_status_class)) ||
    CLOSED.has(token(item.status))
  );
}
