  /**
   * Fetch multiple items by IDs (NIDs or UUIDs) with individual caching.
   * Shares the same cache as fetchItemJson since both return the same item structure.
   * Items are cached by both `nid` and `uuid` so callers can look up by either key.
   *
   * Splits very long ID lists into multiple parallel GET requests so the URL
   * stays under the safe browser/server limit (~2000 chars).
   *
   * Singleton Pattern: Prevents duplicate parallel requests for the same batch.
   */
  const fetchItemsByIds = useCallback(async (backofficeUrl, ids, language, { reset: resetOpt = false } = {}) => {
    if (!backofficeUrl || !ids || ids.length === 0) {
      throwConfigError('items-json', ids?.length ? `${ids.length} ids` : '', 'Missing required parameters');
    }

    const reset = wantsReset(resetOpt);
    const epoch = cacheEpoch.current;

    // Separate cached and uncached IDs.
    // Cache is keyed by both nid and uuid; localStorage is checked as a fallback.
    const cachedItems = [];
    const uncachedIds = [];

    ids.forEach(id => {
      if (!reset) {
        const cached = getItemJsonFromCache(id);
        if (cached) {
          cachedItems.push(cached);
          return;
        }
      }
      uncachedIds.push(id);
    });

    // If all items are cached, return them immediately
    if (uncachedIds.length === 0) {
      return {
        data: cachedItems,
        count: cachedItems.length
      };
    }

    // ==================== URL LENGTH BATCHING ====================
    // Split IDs into batches if URL would be too long (max ~2000 chars safe limit)
    // Pick query param based on input format: numeric NIDs use `ids=`, UUIDs use `uuids=`.
    const isUuidInput = uncachedIds.some(id => !/^\d+$/.test(String(id)));
    const idParamName = isUuidInput ? 'uuids' : 'ids';
    const MAX_URL_LENGTH = 2000;
    const baseUrl = `${backofficeUrl}/api/items-json?`;
    const baseParams = new URLSearchParams({
      json_type: 'web',
      language: language ?? '',
    });
    // +1 for "&", +1 for "=", + length of the param name
    const baseUrlLength = baseUrl.length + baseParams.toString().length + idParamName.length + 2;

    // Calculate URL length for a batch of IDs (comma-joined, encoded)
    const calculateUrlLength = (idBatch) =>
      baseUrlLength + encodeURIComponent(idBatch.join(',')).length;

    const batches = [];
    let currentBatch = [];

    for (const id of uncachedIds) {
      const testBatch = [...currentBatch, id];
      if (calculateUrlLength(testBatch) > MAX_URL_LENGTH && currentBatch.length > 0) {
        batches.push(currentBatch);
        currentBatch = [id];
      } else {
        currentBatch.push(id);
      }
    }
    if (currentBatch.length > 0) {
      batches.push(currentBatch);
    }

    // Fetch one batch with singleton de-duplication
    const fetchBatch = (batch) => {
      const cacheKey = `${[...batch].sort().join(',')}-${language}`;

      if (!reset && pendingItemsByIdsRequests.current[cacheKey]) {
        return pendingItemsByIdsRequests.current[cacheKey];
      }

      const batchPromise = (async () => {
        try {
          const params = new URLSearchParams({
            json_type: 'web',
            [idParamName]: batch.join(','),
            language: language ?? '',
          });
          if (reset) params.set('reset', '1');

          const { data: result } = await debugFetchJson(
            `${backofficeUrl}/api/items-json?${params.toString()}`,
            { cache: 'no-store' },
            {
              endpoint: 'items-json',
              key: `batch of ${batch.length}`,
              errorMessage: 'Failed to fetch item details',
            }
          );

          if (epoch === cacheEpoch.current && result.data && Array.isArray(result.data)) {
            result.data.forEach(cacheItemJson);
          }

          delete pendingItemsByIdsRequests.current[cacheKey];
          return result;
        } catch (error) {
          delete pendingItemsByIdsRequests.current[cacheKey];
          throw error;
        }
      })();

      pendingItemsByIdsRequests.current[cacheKey] = batchPromise;
      return batchPromise;
    };

    // Fire all batches in parallel
    const batchResults = await Promise.all(batches.map(fetchBatch));
    const fetchedItems = batchResults.flatMap(r => r.data || []);

    const allItems = [...cachedItems, ...fetchedItems];

    return {
      data: allItems,
      count: allItems.length
    };
  }, []);

