  /**
   * Invalidate cached data (useful after mutations like placing a bid)
   *
   * @param {string|string[]} itemUuid - Single UUID string or array of UUID strings
   * @param {string} saleUuid - Sale UUID (optional when invalidating multiple items)
   */
  const invalidateItem = useCallback((itemUuid, saleUuid) => {
    const isMultiple = Array.isArray(itemUuid);

    if (isMultiple) {
      // Invalidate each item's cache (without saleUuid)
      itemUuid.forEach(uuid => {
        delete itemsCache.current[uuid];
      });
    } else {
      // Invalidate both cache formats for single item
      if (saleUuid) {
        delete itemsCache.current[`${saleUuid}:${itemUuid}`];
      }
      delete itemsCache.current[itemUuid];
    }
  }, []);

  const invalidateSale = useCallback((saleUuid) => {
    delete salesCache.current[saleUuid];
    saleBsLs.remove(saleUuid);
  }, []);

  const invalidateBidderIds = useCallback((saleUuid, userUuid) => {
    const cacheKey = `${saleUuid}:${userUuid}`;
    delete bidderIdsCache.current[cacheKey];
  }, []);

  const invalidateItemJson = useCallback((itemId) => {
    const item = itemsJsonCache.current[itemId];
    // Resolve nid -> uuid via in-memory item or the LS pointer (covers cold caches).
    const uuid = item?.uuid || itemsJsonNidLs.read(itemId) || itemId;
    const nid = item?.nid || (uuid !== itemId ? itemId : null);
    // Memory is keyed by both nid + uuid — clear every alias.
    const memKeys = new Set([itemId, uuid]);
    if (nid) memKeys.add(nid);
    memKeys.forEach(key => key && delete itemsJsonCache.current[key]);
    // localStorage: drop the full uuid-keyed entry and the nid -> uuid pointer.
    itemsJsonLs.remove(uuid);
    if (nid) itemsJsonNidLs.remove(nid);
  }, []);

