import React, { useState, useEffect, useContext } from 'react';
import { useTranslation } from 'react-i18next';
import { ConfigContext } from '../config/Config';
import fetchData from '../utils/Util';
import { useDataCache } from '../services/DataCache';
import {
    Box,
    Heading,
    Text,
    Flex,
    Spinner,
    SimpleGrid,
    Link,
    Image,
} from '@chakra-ui/react';
import { FaTh, FaThList, FaGavel } from 'react-icons/fa';
import SingleSaleCarousel from './SingleSaleCarousel';
import { SaleLinkChakra, LinkLanguage } from "../components/ItemLink";
import { CircuitDropdown } from '../components/CircuitDropdown';
import { handleImageError } from '../utils/imageFallback';

const SalesList = () => {
    const { t, i18n } = useTranslation();
    const config = useContext(ConfigContext);
    const { fetchSalesPublic } = useDataCache();
    const [sales, setSales] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState(null);
    const [viewMode, setViewMode] = useState(() => {
        const saved = localStorage.getItem('sales_viewMode');
        return saved || 'grid';
    });

    // Hidden filters from data attributes (not shown in UI)
    const [hiddenFilters, setHiddenFilters] = useState({});

    // Track if hidden filters have been initialized from data attributes
    const [hiddenFiltersInitialized, setHiddenFiltersInitialized] = useState(false);

    // Fixed display mode from data attribute (hides view toggle)
    const [fixedDisplayMode, setFixedDisplayMode] = useState(null);

    // Remove filters flag from data attribute (hides entire filter section)
    const [removeFilters, setRemoveFilters] = useState(false);

    // Featured items settings from data attributes
    const [showFeaturedItems, setShowFeaturedItems] = useState(false);
    const [itemDisplayMode, setItemDisplayMode] = useState(null);

    // Pagination state
    const [currentPage, setCurrentPage] = useState(() => {
        const params = new URLSearchParams(window.location.search);
        const page = parseInt(params.get('page'));
        return page && page > 0 ? page : 1;
    });
    const [totalPages, setTotalPages] = useState(1);
    const itemsPerPage = 20;

    // First year for year filter dropdown
    const [firstYear, setFirstYear] = useState(null);

    // Filter states
    const [filters, setFilters] = useState(() => {
        const params = new URLSearchParams(window.location.search);

        // Determine status - check if it's a single value or both
        let status = 'both';
        if (params.get('filter[status]')) {
            status = params.get('filter[status]');
        } else if (params.get('filter[status][operator]') === 'IN') {
            status = 'both';
        }

        return {
            search: params.get('filter[label][value]') || '',
            year: params.get('year') || '',
            department: params.get('filter[departments]') || '',
            status: status,
        };
    });

    // Separate state for search input (not applied until user clicks Apply)
    const [searchInput, setSearchInput] = useState(() => {
        const params = new URLSearchParams(window.location.search);
        return params.get('filter[label][value]') || '';
    });

    // Available options for dropdowns
    const [years, setYears] = useState([]);
    const [departments, setDepartments] = useState([]);
    const [departmentsLoading, setDepartmentsLoading] = useState(true);

    // Read hidden filters and display mode from data attributes on mount
    useEffect(() => {
        const container = document.getElementById('ca-sales-list');
        if (container) {
            const hidden = {};

            // Read filter data attributes
            const dataSearch = container.getAttribute('data-search');
            const dataYear = container.getAttribute('data-year');
            const dataDepartment = container.getAttribute('data-department');
            const dataStatus = container.getAttribute('data-status');

            if (dataSearch) hidden.search = dataSearch;
            if (dataYear) hidden.year = dataYear;
            if (dataDepartment) hidden.department = dataDepartment;
            if (dataStatus) hidden.status = dataStatus;

            setHiddenFilters(hidden);

            // Read display mode data attribute
            const dataDisplayMode = container.getAttribute('data-display-mode');
            if (dataDisplayMode && (dataDisplayMode === 'grid' || dataDisplayMode === 'list' || dataDisplayMode === 'minimal')) {
                setFixedDisplayMode(dataDisplayMode);
                if (dataDisplayMode !== 'minimal') {
                    setViewMode(dataDisplayMode);
                }
            }

            // Read remove filters data attribute
            const dataRemoveFilters = container.getAttribute('data-remove-filters');
            if (dataRemoveFilters === 'true' || dataRemoveFilters === '1') {
                setRemoveFilters(true);
            }

            // Read first year data attribute
            const dataFirstYear = container.getAttribute('data-first-year');
            if (dataFirstYear) {
                setFirstYear(parseInt(dataFirstYear));
            }

            // Read featured items data attributes
            const dataShowFeaturedItems = container.getAttribute('data-show-featured-items');
            if (dataShowFeaturedItems === 'true' || dataShowFeaturedItems === '1') {
                setShowFeaturedItems(true);
            }

            const dataItemDisplay = container.getAttribute('data-item-display');
            if (dataItemDisplay) {
                setItemDisplayMode(dataItemDisplay);
            }
        }

        // Mark hidden filters as initialized
        setHiddenFiltersInitialized(true);
    }, []);

    // Generate years array from firstYear to current year + 45 days
    useEffect(() => {
        if (firstYear) {
            const today = new Date();
            const futureDate = new Date(today);
            futureDate.setDate(today.getDate() + 45); // Add 45 days
            const endYear = futureDate.getFullYear();

            const yearsArray = [];
            for (let year = endYear; year >= firstYear; year--) {
                yearsArray.push(year);
            }
            setYears(yearsArray);
        }
    }, [firstYear]);

    // Fetch departments for filter dropdown
    useEffect(() => {
        const fetchDepartments = async () => {
            if (!config.siteData) return;

            try {
                const response = await fetchData(
                    `${config.siteData.backoffice_url_lang}/api/v1.0/departments`
                );

                if (!response.ok) {
                    throw new Error('Failed to fetch departments');
                }

                const data = await response.json();
                setDepartments(data.data || []);

                // If hidden department filter is a label (string), convert to ID
                if (hiddenFilters.department && isNaN(hiddenFilters.department)) {
                    const deptLabel = hiddenFilters.department.toLowerCase();
                    const matchedDept = data.data.find(dept =>
                        dept.label.toLowerCase() === deptLabel
                    );
                    if (matchedDept) {
                        setHiddenFilters(prev => ({
                            ...prev,
                            department: matchedDept.id.toString()
                        }));
                    }
                }
            } catch (err) {
                console.error('Error fetching departments:', err);
            } finally {
                setDepartmentsLoading(false);
            }
        };

        fetchDepartments();
    }, [config.siteData, hiddenFilters.department]);

    // Fetch sales with server-side filtering and pagination
    useEffect(() => {
        const fetchSales = async () => {
            if (!config.siteData || !hiddenFiltersInitialized) return;

            setIsLoading(true);
            setError(null);

            try {
                // Combine user filters with hidden filters (hidden filters take precedence)
                const activeFilters = {
                    search: hiddenFilters.search || filters.search,
                    year: hiddenFilters.year || filters.year,
                    department: hiddenFilters.department || filters.department,
                    status: hiddenFilters.status || filters.status,
                };

                // Build query parameters
                const params = new URLSearchParams();

                // Pagination
                params.set('range', itemsPerPage);
                params.set('page', currentPage); // API uses 1-based page index

                // Sorting
                params.set('sort', '-live_sale_date_from');

                // Search filter
                if (activeFilters.search) {
                    params.set('filter[label][conjunction]', 'AND');
                    params.set('filter[label][operator]', 'CONTAINS');
                    params.set('filter[label][value]', activeFilters.search);
                }

                // Year filter
                if (activeFilters.year) {
                    params.set('year', activeFilters.year);
                }

                // Department filter
                if (activeFilters.department) {
                    params.set('filter[departments]', activeFilters.department);
                }

                // Status filter
                if (activeFilters.status && activeFilters.status !== 'both') {
                    params.set('filter[status]', activeFilters.status);
                } else if (activeFilters.status === 'both') {
                    params.set('filter[status][operator]', 'IN');
                    params.set('filter[status][value][0]', 'published_on_site');
                    params.set('filter[status][value][1]', 'finished');
                }

                const data = await fetchSalesPublic(
                    config.siteData.backoffice_url_lang,
                    { queryString: params.toString() }
                );

                setSales(data.data || []);

                // Calculate total pages from count
                if (data.count !== undefined) {
                    const calculatedTotalPages = Math.ceil(data.count / itemsPerPage);
                    setTotalPages(calculatedTotalPages > 0 ? calculatedTotalPages : 1);
                }
            } catch (err) {
                setError(err.message);
            } finally {
                setIsLoading(false);
            }
        };

        fetchSales();
    }, [config.siteData, currentPage, filters, hiddenFilters, itemsPerPage, hiddenFiltersInitialized, fetchSalesPublic]);

    // Save viewMode to localStorage (only if not fixed by data attribute)
    useEffect(() => {
        if (!fixedDisplayMode) {
            localStorage.setItem('sales_viewMode', viewMode);
        }
    }, [viewMode, fixedDisplayMode]);

    // Reset to page 1 when filters change
    useEffect(() => {
        setCurrentPage(1);
    }, [filters, hiddenFilters]);

    // Update URL when filters or page change
    useEffect(() => {
        const params = new URLSearchParams();

        if (filters.search) {
            params.set('filter[label][conjunction]', 'AND');
            params.set('filter[label][operator]', 'CONTAINS');
            params.set('filter[label][value]', filters.search);
        }
        if (filters.year) {
            params.set('year', filters.year);
        }
        if (filters.department) {
            params.set('filter[departments]', filters.department);
        }
        if (filters.status && filters.status !== 'both') {
            params.set('filter[status]', filters.status);
        } else if (filters.status === 'both') {
            params.set('filter[status][operator]', 'IN');
            params.set('filter[status][value][0]', 'published_on_site');
            params.set('filter[status][value][1]', 'finished');
        }

        // Add page to URL if not page 1
        if (currentPage > 1) {
            params.set('page', currentPage);
        }

        const newUrl = params.toString() ? `?${params.toString()}` : window.location.pathname;
        window.history.replaceState({}, '', newUrl);
    }, [filters, currentPage]);

    // Filter change handlers
    const handleFilterChange = (filterName, value) => {
        setFilters(prev => ({
            ...prev,
            [filterName]: value
        }));
    };

    const handleSearchInputChange = (e) => {
        setSearchInput(e.target.value);
    };

    const handleApplySearch = () => {
        setFilters(prev => ({
            ...prev,
            search: searchInput
        }));
    };

    const handleClearFilters = () => {
        setSearchInput('');
        setFilters({
            search: '',
            year: '',
            department: '',
            status: 'both'
        });
    };

    if (isLoading) {
        return (
            <div className="sales-list-page sales-list-page--loading">
                <Spinner size="xl" />
            </div>
        );
    }

    if (error) {
        return (
            <div className="sales-list-page">
                <div className="cream-note cream-note--error" role="alert">
                    {error}
                </div>
            </div>
        );
    }

    // Pagination handlers
    const handlePageChange = (page) => {
        setCurrentPage(page);
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    const handlePreviousPage = () => {
        if (currentPage > 1) {
            handlePageChange(currentPage - 1);
        }
    };

    const handleNextPage = () => {
        if (currentPage < totalPages) {
            handlePageChange(currentPage + 1);
        }
    };

    // Get language-specific data for a sale
    const getSaleData = (sale) => {
        const currentLang = i18n.language === 'zh' ? 'zh-hans' : i18n.language;
        return {
            title: sale.label?.[currentLang] || sale.label?.en || '',
            subtitle: sale.subtitle?.[currentLang] || sale.subtitle?.en || '',
            description: sale.description?.[currentLang]?.value || sale.description?.en?.value || '',
            dateLocation: sale.date_and_location_string?.[currentLang] || sale.date_and_location_string?.en || '',
        };
    };

    // Format sale dates for minimal mode
    const formatSaleDate = (sale) => {
        if (!sale.live_sale_date_from) return '';

        const fromDate = new Date(sale.live_sale_date_from);
        const toDate = sale.live_sale_date_to ? new Date(sale.live_sale_date_to) : null;

        const monthNames = ['January', 'February', 'March', 'April', 'May', 'June',
            'July', 'August', 'September', 'October', 'November', 'December'];

        const fromMonth = monthNames[fromDate.getMonth()];
        const fromDay = fromDate.getDate();
        const fromYear = fromDate.getFullYear();

        // Single day event or no end date
        if (!toDate || fromDate.toDateString() === toDate.toDateString()) {
            return `${fromMonth} ${fromDay}, ${fromYear}`;
        }

        const toMonth = monthNames[toDate.getMonth()];
        const toDay = toDate.getDate();
        const toYear = toDate.getFullYear();

        // Same month and year
        if (fromDate.getMonth() === toDate.getMonth() && fromDate.getFullYear() === toDate.getFullYear()) {
            return `${fromMonth} ${fromDay}-${toDay}, ${fromYear}`;
        }

        // Same year, different month
        if (fromDate.getFullYear() === toDate.getFullYear()) {
            return `${fromMonth} ${fromDay} - ${toMonth} ${toDay}, ${fromYear}`;
        }

        // Different years
        return `${fromMonth} ${fromDay}, ${fromYear} - ${toMonth} ${toDay}, ${toYear}`;
    };

    const SaleCard = ({ sale, showFeaturedItems, itemDisplayMode }) => {
        const saleData = getSaleData(sale);
        const logoUrl = sale.logo?.url || 'https://placehold.co/400x300/e2e8f0/718096?text=No+Image';

        // Minimal mode: Show image, title, and "Sale # - Date"
        if (fixedDisplayMode === 'minimal') {
            const formattedDate = formatSaleDate(sale);
            const saleNumber = sale.sale_number || sale.id;

            return (
                <Box className="sale-card sale-card--minimal" textAlign="center" mb={6}>
                    {/* Sale Image */}
                    <SaleLinkChakra saleId={sale.id} className="sale-card__image-link" display="block" mb={3}>
                        <Image
                            src={logoUrl}
                            onError={handleImageError}
                            alt={sale.logo?.alt || saleData.title}
                            className="sale-card__image"
                            maxW="100%"
                            height="auto"
                            objectFit="contain"
                            mx="auto"
                            loading="lazy"
                        />
                    </SaleLinkChakra>

                    {/* Sale Title */}
                    <SaleLinkChakra saleId={sale.id} className="sale-card__title-link">
                        <Heading className="sale-card__title" fontSize="xl" mb={2}>
                            {saleData.title}
                        </Heading>
                    </SaleLinkChakra>

                    {/* Sale Number and Date */}
                    <Text className="sale-card__date-info" fontSize="md" color="gray.600" mb={2}>
                        Sale {saleNumber} - {formattedDate}
                    </Text>

                    {/* Prices Realized row - always rendered so cards align; link only for finished sales */}
                    <Flex className="sale-card__prices-realized-link" justifyContent="center" mb={3}>
                        {sale.status?.value === 'finished' && (
                            <LinkLanguage
                                basePath="prices-realized"
                                id={sale.id}
                                className="sale-card__prices-link"
                                color="blue.600"
                                fontSize="sm"
                                display="flex"
                                alignItems="center"
                                gap={1}
                            >
                                <FaGavel /> {t('sales.pricesRealized', 'Prices Realized')}
                            </LinkLanguage>
                        )}
                    </Flex>

                    {/* Featured Items Carousel */}
                    {showFeaturedItems && (
                        <Box mt={4}>
                            <SingleSaleCarousel
                                sale={sale}
                                displayMode={null}
                                itemDisplayMode={itemDisplayMode}
                                hideSaleHeader={true}
                            />
                        </Box>
                    )}
                </Box>
            );
        }

        // Standard grid/list mode
        return (
            <Box
                className={`sale-card sale-card--${viewMode}`}
                display="flex"
                flexDirection="column"
                height="100%"
            >
                {/* Sale Departments - Top Right Corner - Only show in list view */}
                {viewMode === 'list' && sale.departments && sale.departments.length > 0 && (
                    <Box className="sale-card__departments-corner">
                        {sale.departments.map((dept, index) => (
                            <Text
                                key={dept.uuid || index}
                                className="sale-card__department-label"
                                fontSize="xs"
                                color="gray.600"
                            >
                                {dept.name}
                            </Text>
                        ))}
                    </Box>
                )}

                <Flex className="sale-card__content">
                    {/* Sale Logo/Image - Clickable */}
                    <SaleLinkChakra saleId={sale.id} className="sale-card__image-link">
                        <Box className="sale-card__image-wrapper">
                            <Image
                                src={logoUrl}
                                onError={handleImageError}
                                alt={sale.logo?.alt || saleData.title}
                                className="sale-card__image"
                                loading="lazy"
                            />
                        </Box>
                    </SaleLinkChakra>

                    {/* Sale Content */}
                    <Box className="sale-card__info">
                        {/* Fixed-height heading block keeps the date row aligned across cards */}
                        <div className="sale-card__heading-block">
                            <Flex className="sale-card__header">
                                {/* Title - Clickable */}
                                <SaleLinkChakra saleId={sale.id} className="sale-card__title-link">
                                    <Heading
                                        className="sale-card__title"
                                        fontSize={viewMode === 'grid' ? '1.5rem' : '2rem'}
                                    >
                                        {saleData.title}
                                    </Heading>
                                </SaleLinkChakra>
                            </Flex>

                            {/* Subtitle - Clickable */}
                            {saleData.subtitle && (
                                <SaleLinkChakra saleId={sale.id} className="sale-card__subtitle-link">
                                    <Text className="sale-card__subtitle">
                                        {saleData.subtitle}
                                    </Text>
                                </SaleLinkChakra>
                            )}
                        </div>

                        {/* Formatted Sale Date - Below title/subtitle, above PDF links */}
                        <Text className="sale-card__date" fontSize="md" color="gray.600" mt={2} mb={3}>
                            {formatSaleDate(sale)}
                        </Text>

                        {/* Description - Only show in list view */}
                        {viewMode === 'list' && saleData.description && (
                            <Box
                                className="sale-card__description"
                                dangerouslySetInnerHTML={{ __html: saleData.description }}
                            />
                        )}

                        {/* Prices Realized row - always rendered so its slot aligns across cards;
                            link only for finished sales (empty row is hidden in list view via CSS) */}
                        <Flex className="sale-card__prices-realized-link" mb={3}>
                            {sale.status?.value === 'finished' && (
                                <LinkLanguage
                                    basePath="prices-realized"
                                    id={sale.id}
                                    className="sale-card__prices-link"
                                    color="blue.600"
                                    fontSize="sm"
                                    display="flex"
                                    alignItems="center"
                                    gap={1}
                                >
                                    <FaGavel /> {t('sales.pricesRealized', 'Prices Realized')}
                                </LinkLanguage>
                            )}
                        </Flex>

                        {/* PDF Links */}
                        {(sale.pdf_link?.url || sale.e_book_link?.url || sale.pdf_sale_result?.url) && (
                            <Flex className="sale-card__pdf-links">
                                {sale.pdf_link?.url && (
                                    <Link
                                        href={sale.pdf_link.url}
                                        className="sale-card__pdf-link"
                                        isExternal
                                        color="blue.600"
                                        fontSize="sm"
                                        mr={3}
                                    >
                                        📄 {t('sales.pdfCatalogue', 'PDF Catalogue')}
                                    </Link>
                                )}
                                {sale.e_book_link?.url && (
                                    <Link
                                        href={sale.e_book_link.url}
                                        className="sale-card__ebook-link"
                                        isExternal
                                        color="blue.600"
                                        fontSize="sm"
                                        mr={3}
                                    >
                                        📖 {t('sales.ebook', 'E-Book')}
                                    </Link>
                                )}
                                {sale.pdf_sale_result?.url && (
                                    <Link
                                        href={sale.pdf_sale_result.url}
                                        className="sale-card__results-link"
                                        isExternal
                                        color="blue.600"
                                        fontSize="sm"
                                    >
                                        📊 {t('sales.saleResults', 'Sale Results')}
                                    </Link>
                                )}
                            </Flex>
                        )}
                    </Box>
                </Flex>

                {/* Featured Items Carousel */}
                {showFeaturedItems && (
                    <Box mt={4} width="100%">
                        <SingleSaleCarousel
                            sale={sale}
                            displayMode={null}
                            itemDisplayMode={itemDisplayMode}
                            hideSaleHeader={true}
                        />
                    </Box>
                )}
            </Box>
        );
    };

    return (
        <Box className="sales-list-page">
            {/* Special case: Year links when filters are removed but firstYear is provided */}
            {removeFilters && firstYear && (
                <>
                    <Flex
                        justifyContent="center"
                        gap={4}
                        mb={4}
                        flexWrap="wrap"
                        className="sales-list-year-links"
                    >
                        {[...years].reverse().map(year => (
                            <button
                                key={year}
                                type="button"
                                className={`sales-year-chip${filters.year === year.toString() ? ' is-active' : ''}`}
                                onClick={() => handleFilterChange('year', year.toString())}
                            >
                                {year}
                            </button>
                        ))}
                        <button
                            type="button"
                            className={`sales-year-chip${!filters.year ? ' is-active' : ''}`}
                            onClick={() => handleFilterChange('year', '')}
                        >
                            {t('sales.reset', 'Reset')}
                        </button>
                    </Flex>

                    {/* Year Heading */}
                    <Heading
                        as="h2"
                        size="lg"
                        textAlign="center"
                        mb={6}
                        className="sales-list-year-heading"
                    >
                        {filters.year ? `${filters.year} ${t('sales.catalogs', 'Catalogs')}` : t('sales.allCatalogs', 'All Catalogs')}
                    </Heading>
                </>
            )}

            {/* Filters Section - Hide completely if data-remove-filters is set, otherwise only show filters that aren't hidden via data attributes */}
            {!removeFilters && (!hiddenFilters.search || !hiddenFilters.year || !hiddenFilters.department || !hiddenFilters.status) && (
                <Box className="sales-list-filters">
                    <Flex className="sales-list-filters__wrapper">
                        {/* Search Input - hide if set via data attribute */}
                        {!hiddenFilters.search && (
                            <Box className="sales-list-filters__field">
                                <input
                                    type="text"
                                    className="sales-list-filters__search field-input"
                                    placeholder={t('sales.searchPlaceholder', 'Search sales...')}
                                    value={searchInput}
                                    onChange={handleSearchInputChange}
                                    onKeyDown={(e) => {
                                        if (e.key === 'Enter') {
                                            e.preventDefault();
                                            handleApplySearch();
                                        }
                                    }}
                                />
                            </Box>
                        )}

                        {/* Year Dropdown - hide if set via data attribute or if firstYear is not provided */}
                        {!hiddenFilters.year && firstYear && (
                            <Box className="sales-list-filters__field">
                                <CircuitDropdown
                                    value={filters.year || ''}
                                    ariaLabel={t('sales.allYears', 'All Years')}
                                    variant="compact"
                                    onChange={(v) => handleFilterChange('year', v)}
                                    options={[
                                        { value: '', label: t('sales.allYears', 'All Years') },
                                        ...years.map((year) => ({
                                            value: year.toString(),
                                            label: year.toString(),
                                        })),
                                    ]}
                                />
                            </Box>
                        )}

                        {/* Department Dropdown - hide if set via data attribute */}
                        {!hiddenFilters.department && (
                            <Box className="sales-list-filters__field">
                                <CircuitDropdown
                                    value={filters.department || ''}
                                    ariaLabel={t('sales.allDepartments', 'All Departments')}
                                    variant="compact"
                                    disabled={departmentsLoading}
                                    onChange={(v) => handleFilterChange('department', v)}
                                    options={[
                                        { value: '', label: t('sales.allDepartments', 'All Departments') },
                                        ...departments.map((dept) => ({
                                            value: String(dept.id),
                                            label: dept.label,
                                        })),
                                    ]}
                                />
                            </Box>
                        )}

                        {/* Status Dropdown - hide if set via data attribute */}
                        {!hiddenFilters.status && (
                            <Box className="sales-list-filters__field">
                                <CircuitDropdown
                                    value={filters.status || 'both'}
                                    ariaLabel="Status"
                                    variant="compact"
                                    onChange={(v) => handleFilterChange('status', v)}
                                    options={[
                                        { value: 'both', label: t('sales.statusBoth', 'All Sales') },
                                        { value: 'published_on_site', label: t('sales.statusLive', 'Active') },
                                        { value: 'finished', label: t('sales.statusFinished', 'Closed') },
                                    ]}
                                />
                            </Box>
                        )}

                        {/* Search and Reset Buttons - only show if search is visible */}
                        {!hiddenFilters.search && (
                            <Box className="sales-list-filters__field" display="flex" gap={2}>
                                <button
                                    type="button"
                                    className="btn-primary-action"
                                    onClick={handleApplySearch}
                                >
                                    {t('sales.search', 'Search')}
                                </button>
                                <button
                                    type="button"
                                    className="btn-secondary-action"
                                    onClick={handleClearFilters}
                                >
                                    {t('sales.reset', 'Reset')}
                                </button>
                            </Box>
                        )}
                    </Flex>
                </Box>
            )}

            {/* View Mode Toggle - Below filters, aligned right */}
            {!fixedDisplayMode && (
                <div className="sales-list-view-toggle">
                    <div className="view-toggle" role="group" aria-label="Display mode">
                        <button
                            type="button"
                            className={`view-toggle__btn${viewMode === 'grid' ? ' is-active' : ''}`}
                            onClick={() => setViewMode('grid')}
                            aria-label="Grid view"
                        >
                            <FaTh /> {t('sales.gridView', { defaultValue: 'Grid' })}
                        </button>
                        <button
                            type="button"
                            className={`view-toggle__btn${viewMode === 'list' ? ' is-active' : ''}`}
                            onClick={() => setViewMode('list')}
                            aria-label="List view"
                        >
                            <FaThList /> {t('sales.listView', { defaultValue: 'List' })}
                        </button>
                    </div>
                </div>
            )}

            {sales.length === 0 ? (
                <Text className="sales-list-empty">
                    {t('sales.noSales', 'No sales found')}
                </Text>
            ) : (
                <>
                    {/* Sales Display */}
                    {fixedDisplayMode === 'minimal' ? (
                        <SimpleGrid className="sales-list-minimal" columns={{ base: 1, md: 2, lg: 5 }} spacing={6}>
                            {sales.map((sale) => (
                                <SaleCard
                                    key={sale.id}
                                    sale={sale}
                                    showFeaturedItems={showFeaturedItems}
                                    itemDisplayMode={itemDisplayMode}
                                />
                            ))}
                        </SimpleGrid>
                    ) : viewMode === 'grid' ? (
                        <SimpleGrid className="sales-list-grid" columns={{ base: 1, md: 2, lg: 5 }} spacing={6}>
                            {sales.map((sale) => (
                                <SaleCard
                                    key={sale.id}
                                    sale={sale}
                                    showFeaturedItems={showFeaturedItems}
                                    itemDisplayMode={itemDisplayMode}
                                />
                            ))}
                        </SimpleGrid>
                    ) : (
                        <Flex className="sales-list-list" direction="column" gap={4}>
                            {sales.map((sale) => (
                                <SaleCard
                                    key={sale.id}
                                    sale={sale}
                                    showFeaturedItems={showFeaturedItems}
                                    itemDisplayMode={itemDisplayMode}
                                />
                            ))}
                        </Flex>
                    )}

                    {/* Pagination */}
                    {totalPages > 1 && (
                        <nav className="sales-list-pagination" aria-label="Pagination">
                            <button
                                type="button"
                                className="favorites-pagination__btn"
                                onClick={handlePreviousPage}
                                disabled={currentPage === 1}
                            >
                                {t('sales.previous', 'Previous')}
                            </button>

                            {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => (
                                <button
                                    key={page}
                                    type="button"
                                    className={`favorites-pagination__btn favorites-pagination__btn--num${currentPage === page ? ' is-active' : ''}`}
                                    onClick={() => handlePageChange(page)}
                                    aria-current={currentPage === page ? 'page' : undefined}
                                >
                                    {page}
                                </button>
                            ))}

                            <button
                                type="button"
                                className="favorites-pagination__btn"
                                onClick={handleNextPage}
                                disabled={currentPage === totalPages}
                            >
                                {t('sales.next', 'Next')}
                            </button>
                        </nav>
                    )}
                </>
            )}
        </Box>
    );
};

export default SalesList;
