/**
 * Decide whether a live cache__invalidate should reload THIS host page.
 *
 * DataCache still drops the matching cache entries everywhere. Only the
 * Circuit widgets currently showing the changed item (item page) or the
 * changed sale (sale-level payload) should auto-reload. A sale page whose
 * lot changed refreshes that lot in place; other open pages stay put.
 */

const addId = (set, value) => {
  if (value == null || value === '') return;
  set.add(String(value));
};

/**
 * IDs of items/sales this page's Circuit widgets are bound to.
 *
 * @param {Document} [doc]
 * @returns {{items: Set<string>, sales: Set<string>}}
 */
export function collectPageScope(doc = typeof document !== 'undefined' ? document : null) {
  const items = new Set();
  const sales = new Set();
  if (!doc || typeof doc.getElementById !== 'function') {
    return { items, sales };
  }

  const byId = (id, attr, set) => {
    const el = doc.getElementById(id);
    if (el) addId(set, el.getAttribute(attr));
  };

  byId('ca-item-page', 'data-item-id', items);
  byId('ca-sale-page', 'data-sale-nid', sales);
  byId('ca-sale-info', 'data-sale-nid', sales);
  byId('ca-featured-items', 'data-sale-nid', sales);
  byId('ca-prices-realized', 'data-sale-nid', sales);

  if (typeof doc.querySelectorAll === 'function') {
    doc.querySelectorAll('[data-item-id]').forEach((el) => addId(items, el.getAttribute('data-item-id')));
    doc.querySelectorAll('[data-item-uuid]').forEach((el) => addId(items, el.getAttribute('data-item-uuid')));
    doc.querySelectorAll('[data-sale-nid]').forEach((el) => addId(sales, el.getAttribute('data-sale-nid')));
    doc.querySelectorAll('[data-sale-uuid]').forEach((el) => addId(sales, el.getAttribute('data-sale-uuid')));
  }

  return { items, sales };
}

export function normalizePageUrl(url, baseHref) {
  try {
    const base = baseHref
      || (typeof window !== 'undefined' ? window.location.href : 'http://local.test/');
    const u = new URL(url, base);
    u.hash = '';
    u.search = '';
    u.pathname = u.pathname.replace(/\/+$/, '') || '/';
    return `${u.origin}${u.pathname}`;
  } catch {
    return String(url || '');
  }
}

/**
 * Item ids (nid and/or uuid) carried by an item-scoped payload.
 *
 * The backoffice sends one `cache__invalidate` per item save, and each
 * carries the parent sale ids (and both web URLs) alongside the item ids.
 * Consumers use this to tell "one lot changed" apart from "the sale
 * itself changed".
 *
 * @param {object} payload
 * @returns {string[]} Empty for `all:true` or sale-only payloads.
 */
export function payloadItemIds(payload) {
  if (!payload || payload.all) return [];
  return Array.isArray(payload.items) ? payload.items.map(String) : [];
}

/**
 * @param {object} payload
 * @param {{scope?: {items: Set<string>, sales: Set<string>}, href?: string}} [opts]
 */
export function payloadAffectsCurrentPage(payload, opts = {}) {
  if (!payload) return false;
  if (payload.all) return true;

  const page = opts.scope || collectPageScope();
  const items = payloadItemIds(payload);
  if (items.some((id) => page.items.has(id))) return true;
  // An item-scoped payload also names the parent sale (ids + web URL), but
  // that only means "one lot in this sale changed". Sale pages patch that
  // lot in place (see Sale.js) instead of reloading, so the sale/url
  // matches below are reserved for sale-level payloads. During a live
  // auction every closed lot is an item save; reloading the sale page on
  // each one made it unusable.
  if (items.length > 0) return false;

  const sales = Array.isArray(payload.sales) ? payload.sales.map(String) : [];
  if (sales.some((id) => page.sales.has(id))) return true;

  const href = opts.href
    || (typeof window !== 'undefined' ? window.location.href : '');
  if (Array.isArray(payload.urls) && href) {
    const here = normalizePageUrl(href);
    if (payload.urls.some((u) => normalizePageUrl(u, href) === here)) {
      return true;
    }
  }
  return false;
}

export default payloadAffectsCurrentPage;
