import React, { useState, useEffect, useRef, useCallback } from 'react';
import { createPortal } from 'react-dom';

const ChevronIcon = () => (
  <svg className="circuit-dropdown__chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
    <polyline points="6 9 12 15 18 9" />
  </svg>
);

/**
 * Pill-and-popover dropdown. The popover is portal-mounted onto
 * document.body so it escapes any overflow:hidden ancestor (.rc-card,
 * scrolling tables) and any restrictive stacking context. The portal
 * subtree is re-wrapped in a .circuit-user-ui div so design-system
 * styles cascade in.
 *
 * Props:
 *   value           — currently selected option's `value`
 *   options         — [{ value, label, html? }] (html optional, see renderers)
 *   onChange(value) — fired when an option is selected
 *   ariaLabel       — accessible label
 *   placeholder     — shown in the trigger when no value matches an option
 *   renderTrigger   — (option) => ReactNode  for the trigger label
 *   renderOption    — (option) => ReactNode  for each menu item
 *   variant         — 'narrow' (default) | 'wide' | 'compact'
 */
export const CircuitDropdown = ({
  value,
  options,
  onChange,
  ariaLabel,
  placeholder,
  renderTrigger,
  renderOption,
  variant = 'narrow',
}) => {
  const [open, setOpen] = useState(false);
  const [pos, setPos] = useState(null);
  const wrapperRef = useRef(null);
  const menuRef = useRef(null);

  const measurePos = useCallback(() => {
    if (!wrapperRef.current) return;
    const rect = wrapperRef.current.getBoundingClientRect();
    setPos({
      left: rect.left + window.scrollX,
      top: rect.bottom + window.scrollY + 6,
      width: rect.width,
    });
  }, []);

  // Measure when opening.
  useEffect(() => {
    if (open) measurePos();
  }, [open, measurePos]);

  // Close on outside-click / Escape / page scroll while open.
  useEffect(() => {
    if (!open) return undefined;
    const handlePointer = (e) => {
      const inTrigger = wrapperRef.current && wrapperRef.current.contains(e.target);
      const inMenu = menuRef.current && menuRef.current.contains(e.target);
      if (!inTrigger && !inMenu) setOpen(false);
    };
    const handleKey = (e) => {
      if (e.key === 'Escape') setOpen(false);
    };
    // Page scrolls stale the portal position, so close — but scrolling
    // inside the menu itself (long option lists) must not close it.
    const handleScroll = (e) => {
      if (menuRef.current && menuRef.current.contains(e.target)) return;
      setOpen(false);
    };

    document.addEventListener('mousedown', handlePointer);
    document.addEventListener('touchstart', handlePointer);
    document.addEventListener('keydown', handleKey);
    window.addEventListener('scroll', handleScroll, true);
    return () => {
      document.removeEventListener('mousedown', handlePointer);
      document.removeEventListener('touchstart', handlePointer);
      document.removeEventListener('keydown', handleKey);
      window.removeEventListener('scroll', handleScroll, true);
    };
  }, [open]);

  const selected = options.find((o) => o.value === value);

  return (
    <div
      className={`circuit-dropdown circuit-dropdown--${variant}${open ? ' is-open' : ''}`}
      ref={wrapperRef}
    >
      <button
        type="button"
        className="circuit-dropdown__trigger"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-label={ariaLabel}
        onClick={() => setOpen((o) => !o)}
      >
        <span className="circuit-dropdown__label">
          {selected
            ? renderTrigger
              ? renderTrigger(selected)
              : selected.label
            : (placeholder ?? ariaLabel)}
        </span>
        <ChevronIcon />
      </button>

      {open && pos && createPortal(
        <div className="circuit-user-ui">
          <div
            ref={menuRef}
            className="circuit-dropdown__menu circuit-dropdown__menu--portaled"
            role="listbox"
            style={{
              left: `${pos.left}px`,
              top: `${pos.top}px`,
              minWidth: `${pos.width}px`,
            }}
          >
            {options.map((opt) => (
              <button
                key={opt.value}
                type="button"
                role="option"
                aria-selected={opt.value === value}
                className={`circuit-dropdown__item${opt.value === value ? ' is-selected' : ''}`}
                onClick={() => {
                  onChange(opt.value);
                  setOpen(false);
                }}
              >
                {renderOption ? renderOption(opt) : opt.label}
              </button>
            ))}
          </div>
        </div>,
        document.body
      )}
    </div>
  );
};

export default CircuitDropdown;
