/**
 * localStorage that can never take the app down.
 *
 * Production incident this guards against: with the origin's ~5MB quota full
 * (our dc:* caches store a full search payload per facet-combination URL, so
 * heavy catalog browsing fills it), a bare localStorage.setItem throws
 * QuotaExceededError inside a React effect and production React unmounts the
 * whole tree — "the catalog disappears". Storage here is best-effort:
 * reads/writes fail soft, and a quota failure evicts the oldest dc:* cache
 * entries (they're only caches) and retries before giving up.
 */

const DC_PREFIX = 'dc:';
const EVICT_BATCH = 20;

export function safeGetItem(key) {
  try {
    return localStorage.getItem(key);
  } catch {
    return null;
  }
}

export function safeRemoveItem(key) {
  try {
    localStorage.removeItem(key);
  } catch {
    // ignore
  }
}

/** Parse a stored JSON value; corrupt/absent → fallback. */
export function safeGetJson(key, fallback = null) {
  const raw = safeGetItem(key);
  if (raw == null) return fallback;
  try {
    return JSON.parse(raw);
  } catch {
    safeRemoveItem(key);
    return fallback;
  }
}

/** All dc:* cache keys sorted oldest-first by their entry timestamp. */
function dcKeysOldestFirst() {
  const keys = [];
  try {
    for (let i = 0; i < localStorage.length; i += 1) {
      const key = localStorage.key(i);
      if (key && key.startsWith(DC_PREFIX)) {
        let ts = 0;
        try {
          ts = JSON.parse(localStorage.getItem(key))?.ts || 0;
        } catch {
          ts = 0; // corrupt entries evict first
        }
        keys.push({ key, ts });
      }
    }
  } catch {
    return [];
  }
  return keys.sort((a, b) => a.ts - b.ts).map((entry) => entry.key);
}

/**
 * Best-effort setItem: on quota failure, evict the oldest dc:* cache entries
 * in batches and retry until it fits or nothing is left to evict.
 *
 * @returns {boolean} whether the value was stored.
 */
export function safeSetItem(key, value) {
  try {
    localStorage.setItem(key, value);
    return true;
  } catch {
    // Quota (or storage disabled). Caches are expendable — evict and retry.
  }

  const evictable = dcKeysOldestFirst().filter((dcKey) => dcKey !== key);
  while (evictable.length > 0) {
    evictable.splice(0, EVICT_BATCH).forEach(safeRemoveItem);
    try {
      localStorage.setItem(key, value);
      return true;
    } catch {
      // still full — keep evicting
    }
  }
  return false;
}

export function safeSetJson(key, value) {
  try {
    return safeSetItem(key, JSON.stringify(value));
  } catch {
    return false; // unstringifiable value
  }
}
