/**
 * `?debug=1` data-source panel — a floating box listing where every item /
 * sale fetch of this page load was served from:
 *
 *   MEM   in-memory cache of this page load
 *   LS    persisted localStorage cache (dc:*)
 *   NET   real request — with HTTP status, the edge cache verdict
 *         (CF-Cache-Status / Age / X-Cache) and the backend's own cache
 *         verdict (`_debug.backend_cache`, e.g. items-json Drupal cache
 *         hit/miss).
 *   ERR   FAILED request — HTTP status, the error message shown to the
 *         user, and a snippet of a non-JSON response body (so an HTML
 *         error page from a proxy/edge is recognizable). Also logged for
 *         pre-flight config failures ("Missing API URL") and the
 *         get-config bootstrap fetch, which those usually trace back to.
 *
 * Two layouts share the log:
 *   - with ?debug=1: the compact bottom-left developer panel below;
 *   - without the flag, when a failure was recorded: a friendly
 *     top-centered "Oops" card (`.error-report-panel`, styled in
 *     styles.scss) with a prominent email-to-support action, so end
 *     users can report the failure without knowing about debug=1.
 *
 * Renders nothing when there is neither the flag nor an error.
 * Feeds off utils/dataSourceLog.
 */
import React, { useContext, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { isDebugRequested } from '../utils/debugParam';
import { getDataSourceLog, subscribeDataSources } from '../utils/dataSourceLog';
import { ConfigContext } from '../config/Config';

const SOURCE_BADGE = {
  memory: { label: 'MEM', color: '#8a6d1a', bg: 'rgba(212,175,55,0.18)' },
  localStorage: { label: 'LS', color: '#1a5f8a', bg: 'rgba(55,140,212,0.15)' },
  network: { label: 'NET', color: '#1a7a3a', bg: 'rgba(60,190,110,0.15)' },
  error: { label: 'ERR', color: '#e05555', bg: 'rgba(224,85,85,0.18)' },
};

const time = (at) => new Date(at).toLocaleTimeString([], { hour12: false });

const netDetails = (entry) => {
  const parts = [];
  if (entry.status) parts.push(`HTTP ${entry.status}`);
  if (entry.cfCacheStatus) parts.push(`CF ${entry.cfCacheStatus}`);
  if (entry.age) parts.push(`age ${entry.age}s`);
  if (entry.xCache) parts.push(entry.xCache);
  if (entry.backend?.backend_cache) parts.push(`backend ${entry.backend.backend_cache}`);
  return parts.join(' · ');
};

const errDetails = (entry) => {
  const parts = [];
  if (entry.status) parts.push(`HTTP ${entry.status}`);
  if (entry.cfCacheStatus) parts.push(`CF ${entry.cfCacheStatus}`);
  if (entry.error) parts.push(entry.error);
  return parts.join(' · ');
};

// Pre-filled mailto: so a customer can send the failure log to the auction
// house (siteData.support_email) in one click. mailto bodies get
// truncated by mail clients around ~2000 chars, so keep it tight.
const buildErrorReportMailto = (email, entries) => {
  const errors = entries.filter((entry) => entry.source === 'error');
  const lines = [
    `Page: ${window.location.href}`,
    `Time: ${new Date().toISOString()}`,
    `Browser: ${navigator.userAgent}`,
    '',
    ...errors.map((entry) => {
      const parts = [`[${time(entry.at)}] ${entry.endpoint} ${String(entry.key).slice(0, 80)}`];
      if (entry.status) parts.push(`  HTTP ${entry.status}`);
      if (entry.error) parts.push(`  error: ${entry.error}`);
      if (entry.diagnosis) parts.push(`  diagnosis: ${entry.diagnosis}`);
      if (entry.url) parts.push(`  url: ${String(entry.url).slice(0, 120)}`);
      if (entry.body) parts.push(`  body: ${String(entry.body).slice(0, 120)}`);
      return parts.join('\n');
    }),
  ];
  const subject = `Circuit error report — ${window.location.hostname}`;
  const body = lines.join('\n').slice(0, 1800);
  return `mailto:${email}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
};

const renderLogEntries = (log) => (
  <>
    {log.length === 0 && <div>— no fetches yet —</div>}
    {[...log].reverse().map((entry, index) => {
      const badge = SOURCE_BADGE[entry.source] || SOURCE_BADGE.network;
      return (
        <div key={`${entry.at}-${index}`} style={{ marginBottom: 3 }}>
          <span style={{ color: '#74777d' }}>{time(entry.at)} </span>
          <span
            style={{
              color: badge.color,
              background: badge.bg,
              borderRadius: 4,
              padding: '0 5px',
              fontWeight: 700,
            }}
          >
            {badge.label}
          </span>
          <span style={{ color: '#e9c349' }}> {entry.endpoint}</span>
          <span style={{ color: '#a5a9b0' }}> {String(entry.key).slice(0, 60)}</span>
          {entry.source === 'network' && (
            <div style={{ paddingLeft: 58, color: '#88d982' }}>{netDetails(entry)}</div>
          )}
          {entry.source === 'error' && (
            <div style={{ paddingLeft: 58, color: '#ff9d9d' }}>
              {errDetails(entry)}
              {entry.diagnosis && (
                <div style={{ color: '#ffcf87' }}>diagnosis: {entry.diagnosis}</div>
              )}
              {entry.body && (
                <div style={{ color: '#c98686', wordBreak: 'break-all' }}>
                  body: {String(entry.body).slice(0, 140)}
                </div>
              )}
            </div>
          )}
        </div>
      );
    })}
  </>
);

const DataSourceDebugPanel = () => {
  const config = useContext(ConfigContext);
  const { t } = useTranslation();
  const [log, setLog] = useState(() => [...getDataSourceLog()]);
  const [collapsed, setCollapsed] = useState(false);
  const [dismissed, setDismissed] = useState(false);

  // Always subscribe: error entries are recorded regardless of the debug
  // flag and must be able to pop the panel open when a request fails.
  useEffect(() => subscribeDataSources((entries) => setLog([...entries])), []);

  const hasErrors = log.some((entry) => entry.source === 'error');
  const debugMode = isDebugRequested();
  if (!debugMode && (!hasErrors || dismissed)) return null;

  const supportEmail = config?.siteData?.support_email || null;
  const mailtoHref = hasErrors && supportEmail ? buildErrorReportMailto(supportEmail, log) : null;

  if (!debugMode) {
    // Friendly auto-opened variant for end users.
    return (
      <div className="error-report-panel" role="alert">
        <button
          type="button"
          className="error-report-panel__dismiss"
          aria-label={t('errorReport.dismiss')}
          onClick={() => setDismissed(true)}
        >
          ×
        </button>
        <div className="error-report-panel__title">{t('errorReport.title')}</div>
        <div className="error-report-panel__body">{t('errorReport.body')}</div>
        {mailtoHref && (
          <a
            className="error-report-panel__email"
            href={mailtoHref}
            target="_blank"
            rel="noopener noreferrer"
          >
            ✉ {t('errorReport.emailButton')}
          </a>
        )}
        <div className="error-report-panel__log">{renderLogEntries(log)}</div>
      </div>
    );
  }

  return (
    <div
      style={{
        position: 'fixed',
        bottom: 10,
        left: 10,
        zIndex: 99999,
        maxWidth: 420,
        maxHeight: collapsed ? 32 : 300,
        overflow: 'hidden',
        background: 'rgba(19,19,19,0.95)',
        color: '#d6f5d6',
        borderRadius: 8,
        fontFamily: 'monospace',
        fontSize: 11,
        lineHeight: 1.5,
        boxShadow: '0 4px 14px rgba(0,0,0,0.4)',
      }}
    >
      <div
        onClick={() => setCollapsed((value) => !value)}
        style={{
          padding: '6px 10px',
          cursor: 'pointer',
          fontWeight: 700,
          color: '#e9c349',
          display: 'flex',
          justifyContent: 'space-between',
          gap: 12,
        }}
      >
        <span>DATA SOURCES ({log.length})</span>
        <span>{collapsed ? '▲' : '▼'}</span>
      </div>
      {!collapsed && mailtoHref && (
        <div style={{ padding: '0 10px 6px' }}>
          <a
            href={mailtoHref}
            target="_blank"
            rel="noopener noreferrer"
            style={{ color: '#e9c349', textDecoration: 'underline' }}
          >
            ✉ Email this report
          </a>
        </div>
      )}
      {!collapsed && (
        <div style={{ padding: '0 10px 8px', maxHeight: 260, overflowY: 'auto' }}>
          {renderLogEntries(log)}
        </div>
      )}
    </div>
  );
};

export default DataSourceDebugPanel;
