import React, { useContext, useEffect, useRef, useState, useCallback } from 'react';
import { createPortal } from 'react-dom';
import { Spinner, useToast } from '@chakra-ui/react';
import { ConfigContext } from '../config/Config';
import { useTranslation } from 'react-i18next';
import { LinkLanguage } from '../components/ItemLink';
import { useDataCache } from '../services/DataCache';

const ChevronIcon = () => (
  <svg className="user-pill__chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
    <polyline points="6 9 12 15 18 9" />
  </svg>
);

const initialFor = (name) => {
  if (!name) return 'U';
  const trimmed = String(name).trim();
  if (!trimmed) return 'U';
  return trimmed.charAt(0).toUpperCase();
};

const UserBlock = ({ language }) => {
  const { t } = useTranslation();
  const [isDropdownExpanded, setIsDropdownExpanded] = useState(false);
  const config = useContext(ConfigContext);
  const { clearItemsAndSalesCache } = useDataCache();
  const [isLoggingOut, setIsLoggingOut] = useState(false);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [menuPos, setMenuPos] = useState(null);
  const wrapperRef = useRef(null);
  const menuRef = useRef(null);

  const measurePos = useCallback(() => {
    if (!wrapperRef.current) return;
    const rect = wrapperRef.current.getBoundingClientRect();
    setMenuPos({
      left: rect.left + window.scrollX,
      top: rect.bottom + window.scrollY + 6,
    });
  }, []);
  const isAdmin =
    config.userData?.user_type === 'privileged' ||
    document.getElementById('circuit-setup')?.getAttribute('debug') === '1';

  const handleClearCache = () => {
    clearItemsAndSalesCache();
    toast({
      title: t('userBlock.cacheCleared'),
      status: 'success',
      duration: 3000,
      isClosable: true,
    });
  };

  const toggleDropdown = () => {
    setIsDropdownExpanded((open) => {
      if (!open) measurePos();
      return !open;
    });
  };

  const closeDropdown = () => setIsDropdownExpanded(false);

  const toast = useToast();

  useEffect(() => {
    const handleUserLoggedOut = () => setIsAuthenticated(false);
    const handleUserLoggedIn = () => setIsAuthenticated(true);
    const handleUserAuthenticated = () => setIsAuthenticated(true);

    if (config.accessToken) {
      setIsAuthenticated(true);
    }

    window.addEventListener('userLoggedOut', handleUserLoggedOut);
    window.addEventListener('userLoggedIn', handleUserLoggedIn);
    window.addEventListener('userAuthenticated', handleUserAuthenticated);

    return () => {
      window.removeEventListener('userLoggedOut', handleUserLoggedOut);
      window.removeEventListener('userLoggedIn', handleUserLoggedIn);
      window.removeEventListener('userAuthenticated', handleUserAuthenticated);
    };
  }, [config.accessToken]);

  // Close on outside click / Escape / page scroll while open.
  // Outside = NOT in trigger wrapper AND NOT in portaled menu.
  useEffect(() => {
    if (!isDropdownExpanded) return undefined;

    const handlePointer = (e) => {
      const inTrigger = wrapperRef.current && wrapperRef.current.contains(e.target);
      const inMenu = menuRef.current && menuRef.current.contains(e.target);
      if (!inTrigger && !inMenu) closeDropdown();
    };
    const handleKey = (e) => {
      if (e.key === 'Escape') closeDropdown();
    };
    const handleScroll = () => closeDropdown();

    document.addEventListener('mousedown', handlePointer);
    document.addEventListener('touchstart', handlePointer);
    document.addEventListener('keydown', handleKey);
    window.addEventListener('scroll', handleScroll, true);
    return () => {
      document.removeEventListener('mousedown', handlePointer);
      document.removeEventListener('touchstart', handlePointer);
      document.removeEventListener('keydown', handleKey);
      window.removeEventListener('scroll', handleScroll, true);
    };
  }, [isDropdownExpanded]);

  const handleLogout = () => {
    setIsLoggingOut(true);
    config.setAccessToken(null);
    setIsDropdownExpanded(false);
    window.dispatchEvent(new Event('userLoggedOut'));
    // TODO(circuit): replace Chakra useToast with a native skill toast once a
    // floating notification pattern is documented.
    toast({
      title: t('userBlock.logoutSuccessful'),
      status: 'success',
      duration: 3000,
      isClosable: true,
    });
    setIsLoggingOut(false);
  };

  if (!isAuthenticated) {
    const existingRedirect = new URLSearchParams(window.location.search).get('redirect');
    const redirectTarget = existingRedirect || window.location.href;
    const redirectQuery = `?redirect=${encodeURIComponent(redirectTarget)}`;
    return (
      <div className="user-block">
        <div className="logged-out">
          <LinkLanguage basePath="login" queryParams={redirectQuery}>
            {t('userBlock.login')}
          </LinkLanguage>
          {' '}{t('userBlock.or')}{' '}
          <LinkLanguage basePath="register" queryParams={redirectQuery}>
            {t('userBlock.register')}
          </LinkLanguage>
          {isAdmin && (
            <button
              type="button"
              className="user-menu__item"
              onClick={handleClearCache}
              style={{ background: 'none', border: 'none', cursor: 'pointer' }}
            >
              {t('userBlock.clearCache')}
            </button>
          )}
        </div>
      </div>
    );
  }

  const displayName =
    config.userData?.first_name
      || config.userData?.mail
      || t('userBlock.user');

  return (
    <div className="user-block">
      <div className="logged-in" ref={wrapperRef}>
        <button
          type="button"
          id="dropdownMenuButton"
          className={`user-pill${isDropdownExpanded ? ' is-open' : ''}`}
          aria-haspopup="menu"
          aria-expanded={isDropdownExpanded}
          onClick={toggleDropdown}
        >
          <span className="user-pill__avatar" aria-hidden="true">
            {initialFor(config.userData?.first_name || config.userData?.mail)}
          </span>
          <span className="user-pill__name">{displayName}</span>
          <ChevronIcon />
        </button>

        {isDropdownExpanded && menuPos && createPortal(
          <div className="circuit-user-ui">
            <div
              ref={menuRef}
              className="user-menu user-menu--portaled"
              role="menu"
              style={{ left: `${menuPos.left}px`, top: `${menuPos.top}px` }}
            >
              <LinkLanguage
                className="user-menu__item"
                basePath="my-account"
                onClick={closeDropdown}
              >
                {t('userBlock.myAccount')}
              </LinkLanguage>
              <LinkLanguage
                className="user-menu__item"
                basePath="my-bids"
                onClick={closeDropdown}
              >
                {t('userBlock.myBidsAndCredit')}
              </LinkLanguage>
              {config.siteConfig?.displayBilling && (
                <LinkLanguage
                  className="user-menu__item"
                  basePath="billing"
                  onClick={closeDropdown}
                >
                  {t('userBlock.Billing')}
                </LinkLanguage>
              )}
              <LinkLanguage
                className="user-menu__item"
                basePath="my-favorites"
                onClick={closeDropdown}
              >
                {t('userBlock.myFavorites')}
              </LinkLanguage>
              <LinkLanguage
                className="user-menu__item"
                basePath="my-interests"
                onClick={closeDropdown}
              >
                {t('userBlock.myInterests')}
              </LinkLanguage>
              {isAdmin && (
                <button
                  type="button"
                  className="user-menu__item"
                  onClick={() => { handleClearCache(); closeDropdown(); }}
                >
                  {t('userBlock.clearCache')}
                </button>
              )}
              <button
                type="button"
                className="user-menu__item user-menu__item--logout"
                onClick={handleLogout}
              >
                {isLoggingOut && <Spinner size="sm" color="gray.500" mr={2} />}
                {t('userBlock.logout')}
              </button>
            </div>
          </div>,
          document.body
        )}
      </div>
    </div>
  );
};

export default UserBlock;
