/**
 * "Add to my calendar" link builders for auction sessions.
 *
 * Two flavors cover every user without any library:
 *  - googleCalendarUrl(): the calendar.google.com render?action=TEMPLATE
 *    deep link (one click for Google users);
 *  - icsDataUri(): a standards-compliant VEVENT as a data: URI for an
 *    <a download> — the agnostic path (Apple Calendar, Outlook,
 *    Thunderbird, Android all open .ics natively).
 *
 * Times are Unix epochs (seconds, UTC) straight from the backoffice
 * session node; both outputs use the UTC "basic" stamp (YYYYMMDDTHHMMSSZ)
 * so every calendar app converts to the viewer's timezone itself.
 */

// Epoch seconds → 20260323T120000Z
export function toCalendarStamp(epochSeconds) {
  return new Date(epochSeconds * 1000)
    .toISOString()
    .replace(/[-:]/g, '')
    .replace(/\.\d{3}/, '');
}

const DEFAULT_DURATION_S = 2 * 60 * 60; // sessions without an end: 2h block

function normalizeRange({ start, end }) {
  const from = parseInt(start, 10);
  let to = parseInt(end, 10);
  if (!to || to <= from) {
    to = from + DEFAULT_DURATION_S;
  }
  return { from, to };
}

/** Strip HTML tags + collapse whitespace (sale titles/locations are HTML). */
export function plainText(html) {
  return String(html || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * @param {object} args
 * @param {string} args.title
 * @param {number} args.start   epoch seconds (UTC)
 * @param {number} [args.end]   epoch seconds; defaults to start + 2h
 * @param {string} [args.details]
 * @param {string} [args.location]
 */
export function googleCalendarUrl({ title, start, end, details = '', location = '' }) {
  const { from, to } = normalizeRange({ start, end });
  const params = new URLSearchParams({
    action: 'TEMPLATE',
    text: title,
    dates: `${toCalendarStamp(from)}/${toCalendarStamp(to)}`,
  });
  if (details) params.set('details', details);
  if (location) params.set('location', location);
  return `https://calendar.google.com/calendar/render?${params.toString()}`;
}

// RFC 5545 text escaping: backslash, semicolon, comma, newline.
function icsEscape(value) {
  return String(value || '')
    .replace(/\\/g, '\\\\')
    .replace(/;/g, '\\;')
    .replace(/,/g, '\\,')
    .replace(/\r?\n/g, '\\n');
}

/**
 * Same arguments as googleCalendarUrl, plus uid (stable per lot/session so
 * re-adding updates instead of duplicating in most clients).
 */
export function icsDataUri({ title, start, end, details = '', location = '', uid = '' }) {
  const { from, to } = normalizeRange({ start, end });
  const lines = [
    'BEGIN:VCALENDAR',
    'VERSION:2.0',
    'PRODID:-//Circuit Auction//Session//EN',
    'BEGIN:VEVENT',
    `UID:${icsEscape(uid || `${from}@circuitauction.com`)}`,
    `DTSTAMP:${toCalendarStamp(Math.floor(Date.now() / 1000))}`,
    `DTSTART:${toCalendarStamp(from)}`,
    `DTEND:${toCalendarStamp(to)}`,
    `SUMMARY:${icsEscape(title)}`,
  ];
  if (details) lines.push(`DESCRIPTION:${icsEscape(details)}`);
  if (location) lines.push(`LOCATION:${icsEscape(location)}`);
  lines.push('END:VEVENT', 'END:VCALENDAR');
  // RFC 5545 wants CRLF line endings.
  return `data:text/calendar;charset=utf-8,${encodeURIComponent(lines.join('\r\n'))}`;
}
