import React, { useContext, useEffect, useState } from 'react';
import { ConfigContext } from '../config/Config';
import Login from '../pages/Login';
import axios from 'axios';
import { Alert, AlertIcon, AlertTitle, AlertDescription, Box } from '@chakra-ui/react';

const AuthWrapper = ({ children }) => {
  const config = useContext(ConfigContext);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isProcessingToken, setIsProcessingToken] = useState(false);
  const [showChangePasswordTab, setShowChangePasswordTab] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    const handleUserLoggedOut = () => {
      setIsAuthenticated(false);
    };

    const handleUserLoggedIn = () => {
      setIsAuthenticated(true);
    };

    window.addEventListener('userLoggedOut', handleUserLoggedOut);
    window.addEventListener('userLoggedIn', handleUserLoggedIn);

    return () => {
      window.removeEventListener('userLoggedOut', handleUserLoggedOut);
      window.removeEventListener('userLoggedIn', handleUserLoggedIn);
    };
  }, []);

  useEffect(() => {
    if (config.accessToken) {
      setIsAuthenticated(true);
    } else {
      setIsAuthenticated(false);
    }
  }, [config.accessToken]);

  useEffect(() => {
    const processToken = async () => {
      const urlParams = new URLSearchParams(window.location.search);
      const uid = urlParams.get('u');
      const timestamp = urlParams.get('t');
      const hash = urlParams.get('h');
      const sale = urlParams.get('sale');

      if (uid && timestamp && hash) {
        const isRedirectRequest = !!sale;
        setIsProcessingToken(true);
        setError(null);
        try {
          const response = await axios.get(`${config.backendUrl}/user/get-token/${uid}/${timestamp}/${hash}`);
          if (response.data.status === 'success') {
            config.setAccessToken(response.data.access_token);
            setIsAuthenticated(true);

            if (isRedirectRequest) {
              // Handle redirect to sale
              const redirectUrl = `/live/#/sale/${sale}`;
              // Remove the query parameters from the URL before redirect
              window.history.replaceState({}, document.title, window.location.pathname);
              // Dispatch a custom event for successful authentication
              window.dispatchEvent(new Event('userAuthenticated'));
              window.location.href = redirectUrl;
            } else {
              // Handle password reset
              setShowChangePasswordTab(true);
              // Remove the query parameters from the URL
              window.history.replaceState({}, document.title, window.location.pathname);
              // Dispatch a custom event for successful authentication
              window.dispatchEvent(new Event('userAuthenticated'));
            }
          } else {
            setError(response.data.message || 'An error occurred while processing your request.');
          }
        } catch (error) {
          console.error('Error processing token:', error);
          setError(error.response?.data?.message || error.message || 'An unexpected error occurred.');
        }
        setIsProcessingToken(false);
      }
    };

    processToken();
  }, [config]);

  if (!config || isProcessingToken) {
    return <div>Loading...</div>;
  }

  const handleLogin = async () => {
    setIsAuthenticated(true);
  };

  if (!isAuthenticated) {
    return (
      <Box>
        {error && (
          <Alert status="error" mb={4}>
            <AlertIcon />
            <AlertTitle mr={2}>Error</AlertTitle>
            <AlertDescription>{error}</AlertDescription>
          </Alert>
        )}
        <Login onLogin={handleLogin} />
      </Box>
    );
  }

  return (
    <Box>
      {error && (
        <Alert status="error" mb={4}>
          <AlertIcon />
          <AlertTitle mr={2}>Error</AlertTitle>
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      )}
      {React.Children.map(children, child =>
        React.cloneElement(child, { showChangePasswordTab })
      )}
    </Box>
  );
};

export default AuthWrapper;