import React, { useState, useEffect, useContext } from 'react';
// useToast is a portal-mounted overlay (no in-page layout), so it stays.
// TODO(circuit): replace Chakra toast with a native notification.
import { useToast } from '@chakra-ui/react';
import { X, Edit, Check, CreditCard } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { ConfigContext, formatCurrencyAmount } from '../config/Config';
import { processPayment, setUpPayPalPayment } from '../services/PaymentProcessor';
import { loadAcceptJs, isAcceptJsLoaded } from '../lib/AcceptJsLoader';

const CARD_TYPES = {
  visa: { logo: 'https://cdn.circuitauction.com/images/card-logos/visa.png' },
  mastercard: { logo: 'https://cdn.circuitauction.com/images/card-logos/mastercard.png' },
  amex: { logo: 'https://cdn.circuitauction.com/images/card-logos/amex.png' },
  discover: { logo: 'https://cdn.circuitauction.com/images/card-logos/discover.jpeg' },
  jcb: { logo: 'https://cdn.circuitauction.com/images/card-logos/jcb.jpeg' },
  dinersclub: { logo: 'https://cdn.circuitauction.com/images/card-logos/dinersclub.png' }
};

const CardTypeIndicator = ({ type }) => {
  if (!type || !CARD_TYPES[type]) return null;

  return (
    <img
      className="checkout-card__logo"
      src={CARD_TYPES[type].logo}
      alt={type}
      loading="lazy"
    />
  );
};

const Checkout = ({ invoice, savedCards, onClose, onPaymentComplete, lastPaymentResponse }) => {
  const { t } = useTranslation();
  const config = useContext(ConfigContext);
  const toast = useToast();

  const [selectedCardId, setSelectedCardId] = useState('');
  const [paymentAmount, setPaymentAmount] = useState(invoice.remainingAmount);
  const [isEditingAmount, setIsEditingAmount] = useState(false);
  const [tempAmount, setTempAmount] = useState(invoice.remainingAmount);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isRedirectingPayPal, setIsRedirectingPayPal] = useState(false);
  const [paymentResponse, setPaymentResponse] = useState(null);
  const [, setAcceptJsLoaded] = useState(false);
  const [isEditingCard, setIsEditingCard] = useState(false);
  const [tempCardId, setTempCardId] = useState('');

  // Set default card on component mount
  useEffect(() => {
    const defaultCard = savedCards.find(card => card.isDefault);
    const cardId = defaultCard ? defaultCard.id : (savedCards.length > 0 ? savedCards[0].id : '');

    setSelectedCardId(cardId);
    setTempCardId(cardId); // Initialize tempCardId as well
  }, [savedCards]);

  // Load Accept.js script using shared utility
  useEffect(() => {
    const loadScript = async () => {
      try {
        // Check if already loaded
        if (isAcceptJsLoaded()) {
          setAcceptJsLoaded(true);
          return;
        }

        // Load using shared utility
        await loadAcceptJs(config);
        setAcceptJsLoaded(true);
      } catch (error) {
        console.error('Failed to load Accept.js in Checkout:', error);
        // Don't set error state in checkout, just log it
      }
    };

    loadScript();
  }, [config]);

  useEffect(() => {
    if (lastPaymentResponse && !paymentResponse) {
      setPaymentResponse(lastPaymentResponse);
    }
  }, [lastPaymentResponse, paymentResponse]);


  const handleAmountEdit = () => {
    setTempAmount(paymentAmount);
    setIsEditingAmount(true);
  };

  const handleAmountSave = () => {
    const amount = parseFloat(tempAmount);
    if (amount > 0 && amount <= invoice.remainingAmount) {
      setPaymentAmount(amount);
      setIsEditingAmount(false);
    }
  };

  const handleAmountCancel = () => {
    setTempAmount(paymentAmount);
    setIsEditingAmount(false);
  };

  const handleCardEdit = () => {
    const currentCardId = selectedCardId || (savedCards.length > 0 ? savedCards[0].id : '');
    setTempCardId(currentCardId);
    setIsEditingCard(true);
  };

  const handleCardSave = () => {
    if (tempCardId && savedCards.find(card => card.id === tempCardId)) {
      setSelectedCardId(tempCardId);
      setIsEditingCard(false);
    }
  };

  const handleCardCancel = () => {
    setTempCardId(selectedCardId || '');
    setIsEditingCard(false);
  };

  const handlePayment = async () => {
    if (!selectedCardId) {
      toast({
        title: t('transactions.errorSelectCard') || 'Please select a credit card',
        status: 'error',
        duration: 3000,
      });
      return;
    }

    if (paymentAmount <= 0 || paymentAmount > invoice.remainingAmount) {
      toast({
        title: t('transactions.errorInvalidAmount') || 'Please enter a valid amount',
        status: 'error',
        duration: 3000,
      });
      return;
    }

    setIsProcessing(true);
    setPaymentResponse(null);

    try {
      // Get selected card for response display
      const selectedCard = savedCards.find(card => card.id === selectedCardId);

      // Call the real payment API
      const response = await processPayment({
        config,
        paymentMethodId: selectedCardId,
        amount: paymentAmount,
        currency: invoice.currency,
        invoiceId: invoice.id,
        invoiceData: {
          internalId: invoice.internalId,
          saleLabel: invoice.saleLabel,
          totalAmount: invoice.totalAmount,
          paidAmount: invoice.paidAmount,
          remainingAmount: invoice.remainingAmount
        }
      });

      if (response.success) {
        // Format successful response for UI
        const successResponse = {
          success: true,
          transactionId: response.transactionId,
          card: selectedCard,
          amount: paymentAmount,
          authCode: response.authCode,
          data: response.data
        };

        setPaymentResponse(successResponse);

        // Call parent callback to update invoice
        onPaymentComplete && onPaymentComplete(invoice.id, paymentAmount, successResponse);

        toast({
          title: t('transactions.paymentSuccessful') || 'Payment Successful!',
          description: `Transaction ID: ${response.transactionId}`,
          status: 'success',
          duration: 5000,
        });
      } else {
        // Format error response for UI
        const errorResponse = {
          success: false,
          errorKey: response.error || 'Payment processing failed',
          helpKey: 'Please try again or contact support if the problem persists',
          responseCode: response.errorCode
        };

        setPaymentResponse(errorResponse);

        toast({
          title: t('transactions.paymentFailed') || 'Payment Failed',
          description: response.error,
          status: 'error',
          duration: 5000,
        });
      }
    } catch (error) {
      console.error('Payment error:', error);

      const errorResponse = {
        success: false,
        errorKey: error.message || 'Payment processing failed',
        helpKey: 'Please try again later or contact support'
      };

      setPaymentResponse(errorResponse);

      toast({
        title: t('transactions.paymentFailed') || 'Payment Failed',
        description: error.message || 'An unexpected error occurred',
        status: 'error',
        duration: 5000,
      });
    } finally {
      setIsProcessing(false);
    }
  };

  const handlePayPal = async () => {
    if (paymentAmount <= 0 || paymentAmount > invoice.remainingAmount) {
      toast({
        title: t('transactions.errorInvalidAmount') || 'Please enter a valid amount',
        status: 'error',
        duration: 3000,
      });
      return;
    }

    setIsRedirectingPayPal(true);

    try {
      // PayPal redirects the buyer back to this exact page; the return handler
      // in BillingPage finishes the capture using the stashed context below.
      const returnUrl = window.location.origin + window.location.pathname;
      const res = await setUpPayPalPayment({
        config,
        amount: paymentAmount,
        currency: invoice.currency,
        invoiceId: invoice.id,
        invoiceData: {
          internalId: invoice.internalId,
          saleLabel: invoice.saleLabel,
          totalAmount: invoice.totalAmount,
          paidAmount: invoice.paidAmount,
          remainingAmount: invoice.remainingAmount,
        },
        returnUrl,
      });

      if (res.success && res.secureAcceptanceUrl && res.refTransId) {
        localStorage.setItem('paypal_pending', JSON.stringify({
          refTransId: res.refTransId,
          invoiceId: invoice.id,
          internalId: invoice.internalId,
          amount: paymentAmount,
          currency: invoice.currency,
          clientUuid: config.userData.uuid,
          ts: Date.now(),
        }));
        // Leave the SPA for PayPal.
        window.location.assign(res.secureAcceptanceUrl);
      } else {
        setIsRedirectingPayPal(false);
        toast({
          title: t('transactions.paypalFailed') || 'PayPal payment failed. Please try again.',
          description: res.error,
          status: 'error',
          duration: 5000,
        });
      }
    } catch (error) {
      console.error('PayPal setup error:', error);
      setIsRedirectingPayPal(false);
      toast({
        title: t('transactions.paypalFailed') || 'PayPal payment failed. Please try again.',
        description: error.message,
        status: 'error',
        duration: 5000,
      });
    }
  };

  // Show "Pay with PayPal" only when the site's serverless config opts in
  // (siteConfig.paypal === true). See circuit-serverless/config.js.
  const paypalEnabled = config.siteConfig?.paypal === true;

  const selectedCard = savedCards.find(card => card.id === selectedCardId);
  const capitalize = (s) => (s ? s.charAt(0).toUpperCase() + s.slice(1) : '');

  return (
    <div className="checkout-panel">
      {/* Header with amount due and close button */}
      <div className="checkout-panel__head">
        <h4 className="checkout-panel__title">
          {t('billing.amountDue') || 'Amount Due'}:{' '}
          <span className="checkout-panel__due">
            {formatCurrencyAmount(invoice.remainingAmount, invoice.currency, 2)}
          </span>
        </h4>
        <button
          type="button"
          className="checkout-icon-btn"
          onClick={onClose}
          aria-label="Close checkout"
        >
          <X size={18} />
        </button>
      </div>

      {/* Payment Method Selection */}
      {!paymentResponse?.success && (
        <div className="field">
          <span className="field-label">{t('payment.selectCard') || 'Payment Method'}</span>

          {savedCards.length === 0 ? (
            <div className="cream-note cream-note--warning" role="status">
              <span>
                {t('payment.noSavedCards') || 'No saved payment methods. Please add a payment method first.'}{' '}
                <a href="#payment-methods" className="checkout-inline-link">
                  {t('payment.goToPaymentMethods') || 'Go to Payment Methods'}
                </a>
              </span>
            </div>
          ) : isEditingCard ? (
            <div className="checkout-row">
              <select
                className="field-select checkout-card-select"
                value={tempCardId}
                onChange={(e) => setTempCardId(e.target.value)}
              >
                {savedCards.map(card => (
                  <option key={card.id} value={card.id}>
                    {capitalize(card.cardType)} •••• {card.last4} - {card.cardholderName}
                    {card.isDefault ? ' (Default)' : ''}
                  </option>
                ))}
              </select>
              <button
                type="button"
                className="checkout-icon-btn checkout-icon-btn--confirm"
                onClick={handleCardSave}
                aria-label="Save card selection"
              >
                <Check size={16} />
              </button>
              <button
                type="button"
                className="checkout-icon-btn"
                onClick={handleCardCancel}
                aria-label="Cancel card edit"
              >
                <X size={16} />
              </button>
            </div>
          ) : (
            <div className="checkout-row checkout-row--card">
              <div className="checkout-card">
                <CardTypeIndicator type={selectedCard?.cardType} />
                <span className="checkout-card__name">
                  {capitalize(selectedCard?.cardType)} •••• {selectedCard?.last4}
                </span>
                {selectedCard?.isDefault && (
                  <span className="checkout-badge">{t('payment.default', { defaultValue: 'Default' })}</span>
                )}
                <span className="checkout-card__holder">{selectedCard?.cardholderName}</span>
              </div>
              <button
                type="button"
                className="btn-secondary-action"
                onClick={handleCardEdit}
              >
                <Edit size={14} aria-hidden="true" />
                {t('billing.edit') || 'Edit'}
              </button>
            </div>
          )}
        </div>
      )}

      {/* Payment Amount */}
      {!paymentResponse?.success && (
        <div className="field">
          <span className="field-label">
            {t('transactions.amountToChargeLabel') || 'Amount to Charge'}
          </span>

          <div className="checkout-row">
            {isEditingAmount ? (
              <>
                <input
                  className="field-input checkout-amount-input"
                  type="number"
                  step="0.01"
                  min="0.01"
                  max={invoice.remainingAmount}
                  value={tempAmount}
                  onChange={(e) => setTempAmount(parseFloat(e.target.value) || 0)}
                />
                <span className="checkout-currency">{invoice.currency}</span>
                <button
                  type="button"
                  className="checkout-icon-btn checkout-icon-btn--confirm"
                  onClick={handleAmountSave}
                  aria-label="Save amount"
                >
                  <Check size={16} />
                </button>
                <button
                  type="button"
                  className="checkout-icon-btn"
                  onClick={handleAmountCancel}
                  aria-label="Cancel edit"
                >
                  <X size={16} />
                </button>
              </>
            ) : (
              <>
                <span className="invoice-amount checkout-amount">
                  {formatCurrencyAmount(paymentAmount, invoice.currency, 2)}
                </span>
                <button
                  type="button"
                  className="btn-secondary-action"
                  onClick={handleAmountEdit}
                >
                  <Edit size={14} aria-hidden="true" />
                  {t('billing.edit') || 'Edit'}
                </button>
              </>
            )}
          </div>

          <p className="field-help">
            {t('transactions.amountToChargeHelp') || 'Enter the amount to charge. You can adjust this to charge less than the full amount.'}
          </p>
        </div>
      )}

      {!paymentResponse?.success && <hr className="checkout-divider" />}

      {/* Payment Response */}
      {paymentResponse && (
        paymentResponse.success ? (
          <div className="cream-note cream-note--success" role="status">
            <div>
              <strong>{t('transactions.paymentSuccessful') || 'Payment Successful!'}</strong>
              <p className="checkout-note-line">
                {t('transactions.transactionId') || 'Transaction ID'}: {paymentResponse.transactionId}
              </p>
              <p className="checkout-note-line">
                {t('transactions.card') || 'Card'}: {paymentResponse.card?.cardType} •••• {paymentResponse.card?.last4}
              </p>
              <p className="checkout-note-line">
                {t('transactions.amountCharged') || 'Amount Charged'}: {formatCurrencyAmount(paymentResponse.amount, invoice.currency, 2)}
              </p>
              <p className="checkout-note-line">
                {t('transactions.authCode') || 'Auth Code'}: {paymentResponse.authCode}
              </p>
            </div>
          </div>
        ) : (
          <div className="cream-note cream-note--error" role="alert">
            <div>
              <strong>{t('transactions.paymentFailed') || 'Payment Failed!'}</strong>
              <p className="checkout-note-line">
                {t('transactions.error', { defaultValue: 'Error' })}: {t(paymentResponse.errorKey) || paymentResponse.errorKey}
              </p>
              {paymentResponse.responseCode && (
                <p className="checkout-note-line">
                  {t('transactions.responseCode') || 'Response Code'}: {paymentResponse.responseCode}
                </p>
              )}
              <p className="checkout-note-line">
                {t(paymentResponse.helpKey) || paymentResponse.helpKey}
              </p>
            </div>
          </div>
        )
      )}

      {/* Pay Button or Close Button */}
      <div className="checkout-actions">
        {paymentResponse && paymentResponse.success ? (
          <button
            type="button"
            className="btn-secondary-action"
            onClick={onClose}
          >
            <X size={16} aria-hidden="true" />
            {t('billing.closeCheckout') || 'Close Checkout'}
          </button>
        ) : (
          <>
            <button
              type="button"
              className="bid-limit-submit checkout-pay"
              onClick={handlePayment}
              disabled={!selectedCardId || savedCards.length === 0 || paymentAmount <= 0 || isEditingAmount || isEditingCard || isProcessing || isRedirectingPayPal}
            >
              <CreditCard size={16} aria-hidden="true" />
              {isProcessing
                ? (t('transactions.processingButton') || 'Processing...')
                : `${t('transactions.payButton') || 'Pay Now'} - ${formatCurrencyAmount(paymentAmount, invoice.currency, 2)}`}
            </button>
            {paypalEnabled && (
              <button
                type="button"
                className="checkout-pay checkout-pay--paypal"
                onClick={handlePayPal}
                disabled={paymentAmount <= 0 || isEditingAmount || isEditingCard || isProcessing || isRedirectingPayPal}
                aria-label={`${t('transactions.payWithPaypal') || 'Pay with PayPal'} ${formatCurrencyAmount(paymentAmount, invoice.currency, 2)}`}
              >
                {isRedirectingPayPal ? (
                  <span>{t('transactions.redirectingButton') || 'Redirecting to PayPal...'}</span>
                ) : (
                  <>
                    <img
                      className="checkout-pay__paypal-logo"
                      src="https://www.paypalobjects.com/webstatic/mktg/Logo/pp-logo-200px.png"
                      alt="PayPal"
                      loading="lazy"
                    />
                    <span className="checkout-pay__paypal-amount">
                      {formatCurrencyAmount(paymentAmount, invoice.currency, 2)}
                    </span>
                  </>
                )}
              </button>
            )}
          </>
        )}
      </div>
    </div>
  );
};

export default Checkout;
