import React, { useContext, useState } from 'react';
import { useTranslation, Trans } from 'react-i18next';
import { Spinner } from '@chakra-ui/react';
import ReCAPTCHA from 'react-google-recaptcha';
import fetchData from '../utils/Util';
import { ConfigContext } from '../config/Config';
import { LinkLanguage } from '../components/ItemLink';

const EyeIcon = () => (
  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
    <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" />
    <circle cx="12" cy="12" r="3" />
  </svg>
);

const EyeOffIcon = () => (
  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
    <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24" />
    <line x1="1" y1="1" x2="23" y2="23" />
  </svg>
);

const Login = ({ onLogin }) => {
  const { t, i18n } = useTranslation();
  const [formData, setFormData] = useState({
    email: '',
    password: '',
  });
  const [showPassword, setShowPassword] = useState(false);
  const [termsAccepted, setTermsAccepted] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');
  const config = useContext(ConfigContext);

  if (!config) {
    return (
      <div className="auth-page auth-page--loading">
        <Spinner color="blue.500" size="xl" thickness="4px" />
      </div>
    );
  }

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const credentials = btoa(`${formData.email}:${formData.password}`);
    try {
      const response = await fetchData(
        `${config.backendUrl}/api/login-token?site=${config.siteName}`,
        {
          method: 'GET',
          headers: { Authorization: `Basic ${credentials}` },
        }
      );

      if (response.ok) {
        const data = await response.json();
        setErrorMessage('');
        handleLoginSuccess(data.access_token);
      } else {
        setErrorMessage('login.errors.badCredentials');
      }
    } catch (error) {
      setErrorMessage('login.errors.networkError');
    }
  };

  const handleLoginSuccess = async (accessToken) => {
    await config.setAccessToken(accessToken);
    window.dispatchEvent(new Event('userLoggedIn'));
    if (onLogin) onLogin();

    const urlParams = new URLSearchParams(window.location.search);
    const redirectUrl = urlParams.get('redirect');
    window.location.href = redirectUrl || '/';
  };

  const togglePasswordVisibility = () => setShowPassword((s) => !s);

  if (config.success === false) {
    return (
      <div className="auth-page">
        <div className="cream-note cream-note--error" role="alert">
          Cannot access site settings.
        </div>
      </div>
    );
  }

  return (
    <div className="auth-page user-login">
      <section className="rc-card auth-card">
        <header className="card-head">
          <h2 className="page-title">{t('login.title')}</h2>
        </header>

        <div className="card-body">
          <div className="auth-intro">
            <p>{t('login.emailInstructions')}</p>
            <p>{t('login.passwordInstructions')}</p>
          </div>

          <form onSubmit={handleSubmit} className="acct-form">
            <div className="field">
              <label htmlFor="login-email" className="field-label">
                {t('login.email')}<span className="req">*</span>
              </label>
              <input
                id="login-email"
                type="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                placeholder={t('login.emailPlaceholder')}
                required
                autoComplete="email"
                className="field-input"
              />
            </div>

            <div className="field">
              <label htmlFor="login-password" className="field-label">
                {t('login.password')}<span className="req">*</span>
              </label>
              <div className="password-input-wrap">
                <input
                  id="login-password"
                  type={showPassword ? 'text' : 'password'}
                  name="password"
                  value={formData.password}
                  onChange={handleChange}
                  placeholder={t('login.passwordPlaceholder')}
                  autoComplete="current-password"
                  className="field-input"
                />
                <button
                  type="button"
                  className="password-toggle"
                  onClick={togglePasswordVisibility}
                  aria-label={showPassword ? 'Hide password' : 'Show password'}
                >
                  {showPassword ? <EyeOffIcon /> : <EyeIcon />}
                </button>
              </div>
            </div>

            <label className="checkbox-row terms-acceptance">
              <input
                type="checkbox"
                id="termsCheckbox"
                checked={termsAccepted}
                onChange={() => setTermsAccepted(!termsAccepted)}
                required
              />
              <span className="checkbox-label">
                <Trans i18nKey="register.termsAcceptance">
                  I have read and accepted the Auctioneers <a href="/terms" target="_blank" rel="noopener noreferrer">Terms and Conditions</a> and <a href="/conditions" target="_blank" rel="noopener noreferrer">Data Privacy Terms</a> and I agree to abide by them.
                </Trans>
              </span>
            </label>

            {/* TODO(circuit): the ReCAPTCHA iframe is third-party and won't
                respect design tokens. Wrapper provides spacing only. */}
            <div className="recaptcha-wrap">
              <ReCAPTCHA
                sitekey={config.recaptchaKey}
                hl={i18n.language}
                onChange={(token) => console.log(token)}
              />
            </div>

            <div className="card-actions">
              <button
                type="submit"
                className="btn-primary-action"
                disabled={!termsAccepted}
              >
                {t('login.loginButton')}
              </button>
            </div>

            {errorMessage && (
              <div className="cream-note cream-note--error" role="alert" style={{ marginTop: 'var(--space-5)' }}>
                {t(errorMessage)}
              </div>
            )}
          </form>

          <p className="forgot-password-link">
            <LinkLanguage basePath="forgot-password">{t('login.forgotPassword')}</LinkLanguage>
          </p>
        </div>
      </section>
    </div>
  );
};

export default Login;
