import React, { useEffect, useState } from 'react';
import { createPortal } from 'react-dom';
import { useTranslation } from 'react-i18next';
import { reloadWithCacheReset } from '../utils/resetParam';
import { payloadAffectsCurrentPage } from '../utils/cacheInvalidationScope';

const AUTO_RELOAD_MS = 2500;

const defaultReloadPage = () => {
  reloadWithCacheReset();
};

const bannerStyle = {
  position: 'fixed',
  top: 16,
  left: '50%',
  transform: 'translateX(-50%)',
  zIndex: 10001,
  maxWidth: 'min(560px, calc(100vw - 24px))',
  padding: '12px 16px',
  borderRadius: 8,
  background: '#E9C349',
  color: '#1A160E',
  boxShadow: '0 8px 24px rgba(0,0,0,0.25)',
  fontFamily: 'Manrope, system-ui, -apple-system, sans-serif',
  fontSize: 14,
  lineHeight: 1.4,
};

const titleStyle = {
  fontWeight: 700,
  marginBottom: 4,
};

const actionsStyle = {
  marginTop: 10,
  display: 'flex',
  gap: 8,
  justifyContent: 'flex-end',
};

const buttonStyle = {
  background: '#131313',
  color: '#FBF7EB',
  border: 'none',
  borderRadius: 4,
  padding: '6px 12px',
  cursor: 'pointer',
  fontWeight: 600,
  fontSize: 13,
};

/**
 * Visible notice when a live `cache__invalidate` Pusher event lands.
 *
 * Portaled to document.body because the React root (`#circuit-app-root`)
 * is `display: none`. A full wipe (`all: true`) always auto-reloads.
 * An item edit only reloads when this page's widgets are bound to that
 * item; a sale-level edit only when they are bound to that sale. A sale
 * page whose lot changed patches the lot in place (Sale.js listens to
 * `circuit:items-invalidated`) — during a live auction every closed lot
 * is an item edit, so reloading there is not an option.
 *
 * Listens on `circuit:cache-invalidated` (dispatched from DataCache)
 * rather than the DataCache context so other consumers don't re-render.
 */
const CacheInvalidationNotice = ({ reloadPage = defaultReloadPage } = {}) => {
  const { t } = useTranslation();
  const [notice, setNotice] = useState(null);

  useEffect(() => {
    const onInvalidate = (event) => {
      const payload = event?.detail;
      if (!payloadAffectsCurrentPage(payload)) return;
      setNotice({ ...payload, receivedAt: Date.now() });
    };
    window.addEventListener('circuit:cache-invalidated', onInvalidate);
    return () => window.removeEventListener('circuit:cache-invalidated', onInvalidate);
  }, []);

  useEffect(() => {
    if (!notice) return undefined;
    const timer = window.setTimeout(() => {
      try {
        reloadPage();
      } catch {
        // jsdom and some embed hosts refuse reload; the banner still shows.
      }
    }, AUTO_RELOAD_MS);
    return () => window.clearTimeout(timer);
  }, [notice, reloadPage]);

  if (!notice || typeof document === 'undefined') {
    return null;
  }

  const isAll = !!notice.all;
  const title = isAll
    ? t('cacheInvalidation.allTitle')
    : t('cacheInvalidation.partialTitle');
  const body = isAll
    ? t('cacheInvalidation.allBody')
    : t('cacheInvalidation.partialBody');

  return createPortal(
    <div className="circuit-user-ui">
      <div
        role="status"
        aria-live="polite"
        data-testid="cache-invalidation-notice"
        style={bannerStyle}
      >
        <div style={titleStyle}>{title}</div>
        <div>{body}</div>
        <div style={actionsStyle}>
          <button
            type="button"
            style={buttonStyle}
            onClick={() => {
              try {
                reloadPage();
              } catch {
                // ignore
              }
            }}
          >
            {t('cacheInvalidation.reloadNow')}
          </button>
        </div>
      </div>
    </div>,
    document.body
  );
};

export default CacheInvalidationNotice;
export { AUTO_RELOAD_MS };
