import React from 'react';
import {
  calculateSaleBidSummary,
  BidSummaryDisplay,
  prepareSaleItemsData,
  prepareUserBidsData,
} from '../utils/BidSummaryCalculator';
import { useTranslation } from 'react-i18next';

const SaleSummary = ({ groupedBids, currency, isActive = true, itemDetails }) => {
  const { t } = useTranslation();

  const saleItems = prepareSaleItemsData(groupedBids, itemDetails);
  const userBids = prepareUserBidsData(groupedBids);
  const summary = calculateSaleBidSummary(saleItems, userBids);
  const displayData = BidSummaryDisplay({ summary, currency, t });

  const hasWonItems = Object.values(groupedBids).some(
    (lotData) =>
      lotData.item.status === 'sold' &&
      lotData.bids.some((bid) => bid.id === lotData.item.winning_bid)
  );

  const Stat = ({ label, value, accent }) => (
    <div className="sale-summary__stat">
      <span className="sale-summary__label">{label}</span>
      <span
        className={`sale-summary__value${
          accent ? ` sale-summary__value--${accent}` : ''
        }`}
      >
        {value}
      </span>
    </div>
  );

  return (
    <>
      <div className="sale-summary__row">
        <Stat
          label={t('myBids.summary.totalItemsBidOn')}
          value={displayData.itemsBidOn}
        />
        <Stat
          label={t('myBids.summary.openingTotal')}
          value={displayData.openingTotal}
        />
        <Stat
          label={t('myBids.summary.currentBidsTotal')}
          value={displayData.topBidTotal}
          accent="primary"
        />
      </div>
      {hasWonItems && (
        <div className="sale-summary__row sale-summary__row--won">
          <Stat
            label={t('myBids.summary.wonLots')}
            value={displayData.itemsWon}
          />
          <Stat
            label={t('myBids.summary.wonOpeningTotal')}
            value={displayData.wonOpeningTotal}
          />
          <Stat
            label={t('myBids.summary.soldForTotal')}
            value={displayData.wonAmount}
            accent="green"
          />
        </div>
      )}
    </>
  );
};

export default SaleSummary;
