import Pusher from 'pusher-js';

/**
 * PusherService - Handles real-time updates for Circuit Auction
 *
 * Based on the Elm implementation:
 * - Subscribes to public sale channel: `sale-{saleUuid}`
 * - Subscribes to private user channel: `private-user-{userUuid}`
 * - Listens for events: item__update, sale__update, bidder_info__update, lot_tick
 */

class PusherService {
  constructor() {
    this.pusher = null;
    this.channels = {};
    this.channelSubscribers = {}; // Track number of subscribers per channel
    this.eventHandlers = {};
    this.isInitializing = false;
    this.initConfig = null;
    this.accessToken = null;
  }

  /**
   * Initialize Pusher connection
   * @param {Object} config - Pusher configuration
   * @param {string} config.key - Pusher app key
   * @param {string} config.cluster - Pusher cluster
   * @param {string} config.authEndpoint - Auth endpoint URL
   * @param {string} config.accessToken - User access token
   */
  init(config) {
    // Always keep the freshest token — a public-only consumer (e.g.
    // LiveSaleLinks) may init first without one, and a later init from a
    // logged-in component must still be able to auth private channels.
    if (config.accessToken) {
      this.accessToken = config.accessToken;
    }

    // If already initialized with the same config, do nothing
    if (this.pusher && this.initConfig) {
      const isSameConfig =
        this.initConfig.key === config.key &&
        this.initConfig.cluster === config.cluster &&
        this.initConfig.authEndpoint === config.authEndpoint;

      if (isSameConfig) {
        console.log('[PusherService] Already initialized with same config, skipping');
        return;
      }
    }

    // If already initialized with different config, warn
    if (this.pusher) {
      console.warn('[PusherService] Pusher already initialized with different config');
      return;
    }

    // If currently initializing, skip
    if (this.isInitializing) {
      console.log('[PusherService] Already initializing, skipping duplicate init');
      return;
    }

    this.isInitializing = true;
    const { key, cluster, authEndpoint } = config;

    // Store config for comparison
    this.initConfig = { key, cluster, authEndpoint };

    // Normalize cluster name to lowercase (EuWest1 -> eu, UsEast1 -> us2, etc.)
    // Pusher only accepts lowercase cluster identifiers
    // TODO: serverless still hold old cluster format value, since we use older version of pusher in live app
    // when wee stitch to new version we can remove this.
    const lowerCluster = cluster.toLowerCase();
    const normalizedCluster = lowerCluster === 'useast1'
      ? 'us2' // Pusher's US East cluster id — plain 'us' is not a valid cluster
      : lowerCluster.replace(/west1?|east1?/i, '');

    // Initialize Pusher with configuration
    this.pusher = new Pusher(key, {
      cluster: normalizedCluster,
      authEndpoint: authEndpoint,
      auth: {
        params: {
          access_token: this.accessToken,
        },
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
        },
      },
      // Custom authorizer to handle the auth response format
      authorizer: (channel, options) => {
        return {
          authorize: (socketId, callback) => {
            // Prepare form data
            const formData = new URLSearchParams();
            formData.append('socket_id', socketId);
            formData.append('channel_name', channel.name);

            // Make auth request
            fetch(authEndpoint, {
              method: 'POST',
              headers: {
                'Content-Type': 'application/x-www-form-urlencoded',
                // Read at call time so a token set by a later init is used.
                'access-token': this.accessToken,
              },
              body: formData.toString(),
            })
              .then((response) => {
                if (!response.ok) {
                  throw new Error(`Auth failed with status ${response.status}`);
                }
                return response.json();
              })
              .then((data) => {
                // The API returns { auth: "key:signature", ... }
                // Pusher expects { auth: "key:signature" }
                callback(null, { auth: data.auth });
              })
              .catch((error) => {
                console.error('Pusher auth error:', error);
                callback(error, null);
              });
          },
        };
      },
      forceTLS: true,
    });

    // Handle connection state
    this.pusher.connection.bind('connected', () => {
      console.log('Pusher connected');
      this.isInitializing = false;
    });

    this.pusher.connection.bind('disconnected', () => {
      console.log('Pusher disconnected');
    });

    this.pusher.connection.bind('error', (err) => {
      console.error('Pusher connection error:', err);
      this.isInitializing = false;
    });
  }

  /**
   * Subscribe to channels for a sale
   * @param {string} saleUuid - Sale UUID
   * @param {string} userUuid - User UUID (optional, for private channel)
   */
  subscribe(saleUuid, userUuid = null) {
    if (!this.pusher) {
      console.error('Pusher not initialized');
      return;
    }

    // Subscribe to public sale channel
    const publicChannelName = `sale-${saleUuid}`;
    if (!this.channels[publicChannelName]) {
      console.log(`Subscribing to public channel: ${publicChannelName}`);
      this.channels[publicChannelName] = this.pusher.subscribe(publicChannelName);
      this._bindChannelEvents(this.channels[publicChannelName], 'public');
    }

    // Subscribe to private user channel if userUuid is provided
    if (userUuid) {
      const privateChannelName = `private-user-${userUuid}`;
      if (!this.channels[privateChannelName]) {
        console.log(`Subscribing to private channel: ${privateChannelName}`);
        this.channels[privateChannelName] = this.pusher.subscribe(privateChannelName);
        this._bindChannelEvents(this.channels[privateChannelName], 'private');
      }
    }
  }

  /**
   * Bind events to a channel
   * @param {Object} channel - Pusher channel
   * @param {string} channelType - 'public' or 'private'
   * @private
   */
  _bindChannelEvents(channel, channelType) {
    // Event names from Elm Pusher/Model.elm
    const eventNames = [
      'item__update',
      'sale__update',
      'bidder_info__update',
      'lot_tick',
    ]; // keep in sync with common DEFAULT_SALE_EVENTS

    eventNames.forEach((eventName) => {
      channel.bind(eventName, (data) => {
        console.log(`Received ${eventName} from ${channelType} channel:`, data);

        // Call registered handlers for this event
        if (this.eventHandlers[eventName]) {
          this.eventHandlers[eventName].forEach((handler) => {
            handler(data, channelType);
          });
        }
      });
    });

    // Handle subscription success
    channel.bind('pusher:subscription_succeeded', () => {
      console.log(`Successfully subscribed to ${channelType} channel: ${channel.name}`);
    });

    // Handle subscription error
    channel.bind('pusher:subscription_error', (status) => {
      console.error(`Subscription error for ${channelType} channel ${channel.name}:`, status);
    });
  }

  /**
   * Subscribe to an arbitrary channel and bind a custom set of event names.
   * Used for global channels (e.g. cache invalidation) that don't fit the
   * per-sale pattern in `subscribe()`.
   * @param {string} channelName - Channel to subscribe to (public if no `private-` prefix)
   * @param {string[]} eventNames - Events to bind on that channel
   */
  subscribeChannel(channelName, eventNames) {
    if (!this.pusher) {
      console.error('Pusher not initialized');
      return;
    }
    if (this.channels[channelName]) {
      return;
    }

    console.log(`Subscribing to channel: ${channelName}`);
    const channel = this.pusher.subscribe(channelName);
    this.channels[channelName] = channel;

    eventNames.forEach((eventName) => {
      channel.bind(eventName, (data) => {
        console.log(`Received ${eventName} from channel ${channelName}:`, data);
        if (this.eventHandlers[eventName]) {
          this.eventHandlers[eventName].forEach((handler) => handler(data));
        }
      });
    });

    channel.bind('pusher:subscription_succeeded', () => {
      console.log(`Successfully subscribed to channel: ${channelName}`);
    });
    channel.bind('pusher:subscription_error', (status) => {
      console.error(`Subscription error for channel ${channelName}:`, status);
    });
  }

  /**
   * Unsubscribe from a single channel previously subscribed via subscribeChannel.
   * @param {string} channelName
   */
  unsubscribeChannel(channelName) {
    if (!this.pusher || !this.channels[channelName]) {
      return;
    }
    console.log(`Unsubscribing from channel: ${channelName}`);
    this.pusher.unsubscribe(channelName);
    delete this.channels[channelName];
  }

  /**
   * Register an event handler
   * @param {string} eventName - Event name (e.g., 'item__update')
   * @param {Function} handler - Handler function (data, channelType) => void
   */
  on(eventName, handler) {
    if (!this.eventHandlers[eventName]) {
      this.eventHandlers[eventName] = [];
    }
    this.eventHandlers[eventName].push(handler);
  }

  /**
   * Unregister an event handler
   * @param {string} eventName - Event name
   * @param {Function} handler - Handler function to remove
   */
  off(eventName, handler) {
    if (this.eventHandlers[eventName]) {
      this.eventHandlers[eventName] = this.eventHandlers[eventName].filter(
        (h) => h !== handler
      );
    }
  }

  /**
   * Unsubscribe from all channels
   */
  unsubscribe() {
    if (!this.pusher) {
      return;
    }

    Object.keys(this.channels).forEach((channelName) => {
      console.log(`Unsubscribing from channel: ${channelName}`);
      this.pusher.unsubscribe(channelName);
    });

    this.channels = {};
  }

  /**
   * Disconnect and cleanup
   */
  disconnect() {
    if (this.pusher) {
      console.log('Disconnecting Pusher');
      this.unsubscribe();
      this.pusher.disconnect();
      this.pusher = null;
    }
    // A disconnect before 'connected' fired would otherwise leave this stuck
    // true and silently skip every future init().
    this.isInitializing = false;
    this.eventHandlers = {};
  }
}

// Export singleton instance
const pusherService = new PusherService();
export default pusherService;