import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Box, Tooltip } from '@chakra-ui/react';
import { HelpCircle } from 'lucide-react';

/**
 * Help-icon tooltip that works with mouse, touch and keyboard.
 *
 * Chakra's Tooltip only opens on hover/focus and deliberately ignores
 * touch pointers, so on phones the icon was dead. This component owns
 * the open state itself:
 *   - mouse: hover opens, leaving closes
 *   - touch: tap toggles, tapping anywhere else (or Escape) closes
 *   - keyboard: focus opens, blur closes, Enter/Space toggles
 *
 * Props:
 *   label — tooltip text
 *   size  — icon size (default 14)
 *   ...rest is forwarded to Chakra's Tooltip (placement, etc.)
 */
export const HelpTooltip = ({ label, size = 14, ...rest }) => {
  const [isOpen, setIsOpen] = useState(false);
  const triggerRef = useRef(null);
  // Set on pointerdown and cleared after the resulting click so that
  // the focus event fired by a tap/click doesn't also open the tooltip
  // (which would make the click toggle it straight back shut).
  const pointerType = useRef(null);

  useEffect(() => {
    if (!isOpen) return undefined;
    const onDocPointerDown = (e) => {
      if (triggerRef.current && !triggerRef.current.contains(e.target)) {
        setIsOpen(false);
      }
    };
    const onKeyDown = (e) => {
      if (e.key === 'Escape') setIsOpen(false);
    };
    document.addEventListener('pointerdown', onDocPointerDown, true);
    document.addEventListener('keydown', onKeyDown);
    return () => {
      document.removeEventListener('pointerdown', onDocPointerDown, true);
      document.removeEventListener('keydown', onKeyDown);
    };
  }, [isOpen]);

  const handlePointerEnter = useCallback((e) => {
    if (e.pointerType !== 'touch') setIsOpen(true);
  }, []);
  const handlePointerLeave = useCallback((e) => {
    if (e.pointerType !== 'touch') setIsOpen(false);
  }, []);
  const handlePointerDown = useCallback((e) => {
    pointerType.current = e.pointerType || 'mouse';
  }, []);
  const handleClick = useCallback(() => {
    if (pointerType.current === 'mouse') {
      setIsOpen(true); // hover already opened it; keep it that way
    } else {
      setIsOpen((open) => !open);
    }
    pointerType.current = null;
  }, []);
  const handleFocus = useCallback(() => {
    if (!pointerType.current) setIsOpen(true); // keyboard focus only
  }, []);
  const handleBlur = useCallback(() => setIsOpen(false), []);
  const handleKeyDown = useCallback((e) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      setIsOpen((open) => !open);
    }
  }, []);

  return (
    <Tooltip label={label} hasArrow placement="top" isOpen={isOpen} {...rest}>
      <Box
        as="span"
        ref={triggerRef}
        role="button"
        tabIndex={0}
        aria-label={label}
        className="help-tooltip-trigger"
        cursor="help"
        display="inline-flex"
        alignItems="center"
        onPointerEnter={handlePointerEnter}
        onPointerLeave={handlePointerLeave}
        onPointerDown={handlePointerDown}
        onClick={handleClick}
        onFocus={handleFocus}
        onBlur={handleBlur}
        onKeyDown={handleKeyDown}
      >
        <HelpCircle size={size}/>
      </Box>
    </Tooltip>
  );
};

export default HelpTooltip;
