/**
 * Data-source provenance log for the `?debug=1` panel.
 *
 * DataCache records one entry per resolved fetch: which endpoint, and which
 * layer served it —
 *   'memory'        in-memory cache of this page load
 *   'localStorage'  persisted client cache (dc:*)
 *   'network'       a real request; the entry then also carries the HTTP
 *                   status, the edge/proxy cache headers (CF-Cache-Status /
 *                   Age / X-Cache — readable cross-origin because the
 *                   backoffice exposes them) and the backend's own `_debug`
 *                   block (items-json: Drupal-cache hit/miss).
 *   'error'         a FAILED request — network reject, non-2xx status, or a
 *                   non-JSON body — with the status, error message and a
 *                   body snippet. Also logged for pre-flight config
 *                   failures ("Missing API URL") and the get-config
 *                   bootstrap fetch, so the panel explains WHY widgets fail.
 *
 * Module-scoped ring buffer + tiny pub/sub so the panel re-renders as
 * entries arrive. Recording is a no-op unless ?debug=1 is active, so the
 * production hot path stays untouched.
 */
import { isDebugRequested } from './debugParam';

const MAX_ENTRIES = 50;
const entries = [];
const listeners = new Set();

export function recordDataSource(entry) {
  // Failures are ALWAYS recorded — they auto-open the debug panel so a
  // customer can see and report them without knowing about ?debug=1.
  // Success provenance stays behind the flag: it fires on every fetch and
  // the production hot path must stay untouched.
  if (entry?.source !== 'error' && !isDebugRequested()) return null;
  const stored = { at: Date.now(), ...entry };
  entries.push(stored);
  if (entries.length > MAX_ENTRIES) entries.shift();
  listeners.forEach((listener) => listener(entries));
  // Returned so async enrichment (diagnoseNetworkFailure) can mutate the
  // stored entry and re-broadcast via notifyDataSources().
  return stored;
}

/** Re-broadcast after an async enrichment mutated a stored entry. */
export function notifyDataSources() {
  listeners.forEach((listener) => listener(entries));
}

// One probe per origin — a burst of failures against one host shares it.
const diagnosisByOrigin = new Map();

/**
 * Best-effort explanation of an opaque "Failed to fetch". The browser hides
 * WHY a fetch rejected — CORS, DNS, connection refused, TLS and offline all
 * surface as the same TypeError. A `mode: 'no-cors'` probe reaches the
 * server WITHOUT requiring CORS headers, which splits the cases:
 *
 *   probe resolves -> the server answered, so the browser blocked the real
 *                     response: almost always missing/invalid CORS headers.
 *   probe rejects  -> the server never answered: DNS, refused, TLS
 *                     certificate, or a firewall / ad-blocker.
 */
export function diagnoseNetworkFailure(url) {
  let origin = String(url || '');
  try {
    origin = new URL(url, typeof window !== 'undefined' ? window.location.href : undefined).origin;
  } catch {
    // Unparseable URL — memoize on the raw string.
  }
  if (!diagnosisByOrigin.has(origin)) {
    diagnosisByOrigin.set(origin, (async () => {
      if (typeof navigator !== 'undefined' && navigator.onLine === false) {
        return 'browser offline';
      }
      if (
        typeof window !== 'undefined' &&
        window.location.protocol === 'https:' &&
        String(url).startsWith('http:')
      ) {
        return 'mixed content — HTTP API called from an HTTPS page, blocked by the browser';
      }
      try {
        await fetch(url, { mode: 'no-cors', cache: 'no-store' });
        return 'likely CORS — server reachable, but the browser blocked the response (missing/invalid CORS headers)';
      } catch {
        return 'server unreachable — DNS failure, connection refused, TLS certificate problem, or blocked by firewall/ad-blocker';
      }
    })());
  }
  return diagnosisByOrigin.get(origin);
}

/** Pull the cache-related response headers the panel displays. */
export function cacheHeadersOf(response) {
  const pick = (name) => {
    try {
      return response?.headers?.get(name) || null;
    } catch {
      return null;
    }
  };
  return {
    cfCacheStatus: pick('cf-cache-status'),
    age: pick('age'),
    xCache: pick('x-cache'),
  };
}

export function getDataSourceLog() {
  return entries;
}

export function subscribeDataSources(listener) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

/** Test-only: reset the module state between test cases. */
export function __clearDataSourceLog() {
  entries.length = 0;
  listeners.clear();
  diagnosisByOrigin.clear();
}
