import React, { useState, useEffect, useContext } from 'react';
import { useTranslation } from 'react-i18next';
import { ConfigContext } from '../config/Config';
// Chakra still in use: the subscription-required modal + Spinner.
import {
  Spinner,
  Modal, ModalOverlay, ModalContent, ModalHeader, ModalFooter, ModalBody, ModalCloseButton,
  useDisclosure,
} from '@chakra-ui/react';
import fetchData from '../utils/Util';

const SubscriptionMagazine = () => {
  const { t, i18n } = useTranslation();
  const config = useContext(ConfigContext);
  const [magazines, setMagazines] = useState([]);
  const [boUserData, setBoUserData] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [selectedMagazine, setSelectedMagazine] = useState(null);
  const { isOpen, onOpen, onClose } = useDisclosure();

  // Get sale_id for magazines - from backoffice_subscription_magazines_sale_nid variable
  // Fetch magazines and user data
  useEffect(() => {
    const fetchBoUserData = async () => {
      try {
        // Only fetch user data if user is logged in
        if (config.userData && config.userData.uuid && config.userData.bo_access_token) {
          const response = await fetchData(
            `${config.siteData.backoffice_url_lang}/api/v1.0/datatable-clients?filter[uuid][value]=${config.userData.uuid}`,
            {
              mockData: 'api-me',
              headers: { 'access-token': config.userData.bo_access_token },
            }
          );
          
          if (!response.ok) {
            throw new Error(response.title || t('subscriptionMagazine.networkError'));
          }
          
          const result = await response.json();
          const data = result.data[0];
          setBoUserData(data);
        }
        
      } catch (error) {
        setError(error.message);
      }
    };

    const fetchMagazines = async (saleId) => {
      try {
        // Anonymous visitors see the login note — don't attempt the
        // authenticated fetch (it would throw on the missing token).
        if (!config.siteData || !config.siteData.backoffice_url || !config.userData?.bo_access_token) {
          return;
        }

        const response = await fetchData(
          `${config.siteData.backoffice_url_lang}/api/v1.0/catalogue-parts-public?sale_id=${saleId}&sort=weight`,
          {
            mockData: 'api-catalogue-parts',
            headers: { 'access-token': config.userData.bo_access_token },
          }
        );
        
        if (!response.ok) {
          throw new Error(response.title || t('subscriptionMagazine.networkError'));
        }
        
        const result = await response.json();
        
        // Transform API data to our magazine format
        const transformedMagazines = result.data
          .filter(item => item.image && item.image.url)
          .map(item => ({
            id: item.id,
            title: item.label?.[i18n.language] || item.label?.en || item.label || `Magazine ${item.id}`,
            coverImage: item.image?.url || "https://placehold.co/300x400/cccccc/ffffff?text=No+Image",
            flipbookUrl: item.pdf_link?.url || "#"
          }));
        
        setMagazines(transformedMagazines);
        
      } catch (error) {
        setError(error.message);
        console.error('Error fetching magazines:', error);
      }
    };

    const fetchMagazineSaleId = async () => {
      if (!config.siteData || !config.siteData.backoffice_url) {
        throw new Error('No backoffice URL available');
      }

      const response = await fetchData(
        `${config.siteData.backoffice_url_lang}/api/v1.0/invoke-function-public/variable_get?params[0]=backoffice_subscription_magazines_sale_nid`
      );
    
      if (!response.ok) {
        throw new Error('Failed to fetch magazine sale ID');
      }
    
      const result = await response.json();
      if (!result[0]) {
        throw new Error('No magazine sale ID returned');
      }
    
      return result[0];
    };

    const fetchDataAsync = async () => {
      try {
        await fetchBoUserData();
        const saleId = await fetchMagazineSaleId();
        await fetchMagazines(saleId);
      } catch (error) {
        setError(error.message);
      } finally {
        setIsLoading(false);
      }
    };

    fetchDataAsync().catch((error) => {
      setError(error.message);
      setIsLoading(false);
    });
  }, [config, t, i18n.language]);

  // Check if user is logged in
  const isLoggedIn = () => {
    return config.userData && config.userData.bo_access_token;
  };

  // Check if user has subscription access
  const hasSubscriptionAccess = () => {
    if (!boUserData) {
      return false;
    }

    // Get subscription status using same logic as MyAccount
    const getSubscriptionStatus = () => {
      // If subscription_type is falsy (null, undefined, empty string) or 'none'
      if (!boUserData.subscription_type || boUserData.subscription_type === 'none') {
        // If there's a cancellation date, check if it's in the future or past
        if (boUserData.cancellation_date) {
          const expirationDate = new Date(boUserData.cancellation_date);
          const now = new Date();
          // If cancellation date is in the future, this is an error state
          if (expirationDate > now) {
            return 'error';
          }
          // If cancellation date is in the past, subscription expired
          return 'expired';
        }
        // No cancellation date means never had a subscription
        return 'none';
      }
      
      // Has a subscription type (digital/hardcopy), check if still active
      if (boUserData.cancellation_date) {
        const expirationDate = new Date(boUserData.cancellation_date);
        const now = new Date();
        return expirationDate > now ? 'active' : 'expired';
      }
      
      // Has subscription type but no cancellation date - active
      return 'active';
    };

    const status = getSubscriptionStatus();
    // Only allow access if status is 'active'
    return status === 'active';
  };

  // Handle magazine click
  const handleMagazineClick = (magazine) => {

    // Don't do anything if there's no flipbook URL
    if (!magazine.flipbookUrl || magazine.flipbookUrl === "#") {
      return;
    }

    // Check if user is logged in
    if (!isLoggedIn()) {
      // Redirect to login page
      window.location.href = '/login';
      return;
    }

    // Check if user has subscription access
    if (!hasSubscriptionAccess()) {
      // Show subscription required modal
      setSelectedMagazine(magazine);
      onOpen();
      return;
    }

    // User has access, open flipbook
    window.open(magazine.flipbookUrl, '_blank');
  };

  // Handle subscription purchase redirect
  const handleSubscriptionPurchase = () => {
    // Redirect to subscription purchase page
    window.location.href = '/subscription-purchase';
  };

  if (isLoading || !config.siteData) {
    return (
      <div className="subscription-page subscription-page--loading">
        <Spinner color="blue.500" size="xl" thickness="4px" />
      </div>
    );
  }

  if (config.success === false) {
    return (
      <div className="subscription-page">
        <div className="cream-note cream-note--error" role="alert">
          {t('subscriptionMagazine.cannotAccessSiteSettings')}
        </div>
      </div>
    );
  }

  const getSubscriptionStatus = () => {
    if (!boUserData?.subscription_type || boUserData.subscription_type === 'none') {
      if (boUserData?.cancellation_date) {
        const expirationDate = new Date(boUserData.cancellation_date);
        const now = new Date();
        if (expirationDate > now) return 'error';
        return 'expired';
      }
      return 'none';
    }
    if (boUserData.cancellation_date) {
      const expirationDate = new Date(boUserData.cancellation_date);
      const now = new Date();
      return expirationDate > now ? 'active' : 'expired';
    }
    return 'active';
  };

  return (
    <div className="subscription-page">
      <section className="rc-card account-card subscription-magazine">
        <header className="card-head">
          <h2 className="page-title">{t('subscriptionMagazine.title')}</h2>
        </header>

        <div className="card-body">
          {error && (
            <div className="cream-note cream-note--error" role="alert">
              <strong>{t('subscriptionMagazine.error')}</strong>{error}
            </div>
          )}

          {isLoggedIn() && !hasSubscriptionAccess() && boUserData && (() => {
            const status = getSubscriptionStatus();
            const variant = status === 'error' ? 'error' : status === 'expired' ? 'warning' : 'warning';
            const actionHref = status === 'error' ? '/contact' : '/subscription-purchase';
            const actionLabel =
              status === 'error' ? t('subscriptionMagazine.contactOffice')
              : status === 'expired' ? t('subscriptionMagazine.renewSubscription')
              : t('subscriptionMagazine.learnAboutPlans');
            const message =
              status === 'error' ? t('subscriptionMagazine.subscriptionError')
              : status === 'expired' ? t('subscriptionMagazine.subscriptionExpired')
              : t('subscriptionMagazine.subscriptionRequired');

            return (
              <div className={`cream-note cream-note--${variant} subscription-magazine__status`} role="status">
                <span>{message}</span>
                <a href={actionHref} className="bid-limit-submit subscription-magazine__action">
                  {actionLabel}
                </a>
              </div>
            );
          })()}

          {!isLoggedIn() && (
            <div className="cream-note cream-note--warning" role="status">
              {t('subscriptionMagazine.loginToAccess')}
            </div>
          )}

          <div className="magazine-grid">
            {magazines.map((magazine) => {
              const clickable = magazine.flipbookUrl && magazine.flipbookUrl !== '#';
              return (
                <button
                  key={magazine.id}
                  type="button"
                  className={`magazine-card${clickable ? '' : ' is-disabled'}`}
                  onClick={() => handleMagazineClick(magazine)}
                  disabled={!clickable}
                >
                  <span className="magazine-card__cover">
                    <img
                      src={magazine.coverImage}
                      alt={magazine.title}
                      loading="lazy"
                      onError={(e) => {
                        e.currentTarget.src =
                          'https://placehold.co/300x400/cccccc/ffffff?text=Loading...';
                      }}
                    />
                  </span>
                  <span className="magazine-card__title">{magazine.title}</span>
                </button>
              );
            })}
          </div>
        </div>
      </section>

      {/* Subscription Required Modal — TODO(circuit): native popover. */}
      <Modal isOpen={isOpen} onClose={onClose} size="md">
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>{t('subscriptionMagazine.subscriptionRequiredTitle')}</ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            <p style={{ marginBottom: '12px' }}>
              {t('subscriptionMagazine.subscriptionRequiredMessage', {
                magazineTitle: selectedMagazine?.title,
              })}
            </p>
            <p style={{ color: 'var(--text-muted)' }}>
              {t('subscriptionMagazine.subscriptionBenefits')}
            </p>
          </ModalBody>
          <ModalFooter>
            <button type="button" className="btn-secondary-action" onClick={onClose} style={{ marginRight: '12px' }}>
              {t('subscriptionMagazine.cancel')}
            </button>
            <button type="button" className="bid-limit-submit" onClick={handleSubscriptionPurchase}>
              {t('subscriptionMagazine.purchaseSubscription')}
            </button>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </div>
  );
};

export default SubscriptionMagazine;