import React, { useState, useEffect, useContext, useCallback, useRef } from 'react';
import { createPortal } from 'react-dom';
import { useTranslation } from 'react-i18next';
import { ConfigContext, formatCurrencyAmount } from '../config/Config';
import { useDataCache } from '../services/DataCache';
import pusherService from '../services/PusherService';
import { nestedItemFromLotTick } from '@common/domain/liveSale/pusherEvents';
import { handleImageError } from '../utils/imageFallback';

// Bid-server sale statuses that make a sale appear in this block.
const VISIBLE_STATUSES = ['paused_starting_soon', 'open_live', 'paused_back_shortly'];

const SALE_BADGE = {
    paused_starting_soon: { cls: 'paused', key: 'liveSaleLinks.startingSoon', fallback: 'Starting Soon' },
    open_live: { cls: 's-active', key: 'liveSaleLinks.liveNow', fallback: 'Live Now' },
    paused_back_shortly: { cls: 'paused', key: 'liveSaleLinks.backShortly', fallback: 'Back Shortly' },
};

const ITEM_BADGE = {
    active: 's-active',
    open: 's-active',
    going: 'going',
    going_going: 'going',
    gone: 'gone',
    sold: 'gone',
    unsold: 'paused',
    paused: 'paused',
};

const SALES_POLL_INTERVAL_MS = 60000;
const REFRESH_DEBOUNCE_MS = 400;

/**
 * LiveSaleLinks — container id `live-sale-links`.
 *
 * Shows the site's sales that are currently in a live-auction phase
 * (paused_starting_soon / open_live / paused_back_shortly). Status and
 * live pricing come from the bid server; title, image, dates and body
 * come from the back office. Real-time updates arrive over the public
 * Pusher sale channels, with a poll as a safety net. Renders nothing
 * when no sale is in a live phase.
 */
const LiveSaleLinks = () => {
    const { t, i18n } = useTranslation();
    const config = useContext(ConfigContext);
    const { fetchSalesPublic, fetchItemJson } = useDataCache();

    // Bid-server sales for this site, all non-ended (also the ones we
    // only subscribe to, waiting for them to enter a live phase).
    const [bidSales, setBidSales] = useState([]);
    // Back office sales-public records, keyed by sale uuid.
    const [boSales, setBoSales] = useState({});
    // Active (current) item per sale, keyed by sale uuid.
    const [activeItems, setActiveItems] = useState({});
    // Back office items-json records (images, …), keyed by item uuid.
    const [itemJsons, setItemJsons] = useState({});
    const [aboutSaleUuid, setAboutSaleUuid] = useState(null);

    const refreshTimer = useRef(null);

    // ---- Bid server: sales list (always fresh, never cached) ----
    const loadSales = useCallback(async () => {
        if (!config.backendUrl || !config.siteName) return;

        try {
            const params = new URLSearchParams({
                'filter[login_site_name]': config.siteName,
                fields: 'id,uuid,label,status,item,currency,paused_message',
            });
            const response = await fetch(`${config.backendUrl}/api/sales?${params.toString()}`);
            if (!response.ok) {
                throw new Error(`Failed to fetch sales (${response.status})`);
            }
            const data = await response.json();
            setBidSales((data.data || []).filter((sale) => sale.status !== 'closed_ended'));
        } catch (error) {
            console.error('[LiveSaleLinks] Error fetching sales from bid server:', error);
        }
    }, [config.backendUrl, config.siteName]);

    const scheduleRefresh = useCallback(() => {
        if (refreshTimer.current) return;
        refreshTimer.current = setTimeout(() => {
            refreshTimer.current = null;
            loadSales();
        }, REFRESH_DEBOUNCE_MS);
    }, [loadSales]);

    useEffect(() => {
        loadSales();
        const interval = setInterval(loadSales, SALES_POLL_INTERVAL_MS);
        return () => {
            clearInterval(interval);
            if (refreshTimer.current) {
                clearTimeout(refreshTimer.current);
                refreshTimer.current = null;
            }
        };
    }, [loadSales]);

    const visibleSales = bidSales.filter((sale) => VISIBLE_STATUSES.includes(sale.status));

    // ---- Back office: title / image / dates / body per visible sale ----
    useEffect(() => {
        const backofficeUrl = config.siteData?.backoffice_url_lang;
        if (!backofficeUrl) return;

        visibleSales
            .filter((sale) => boSales[sale.uuid] === undefined)
            .forEach(async (sale) => {
                try {
                    const data = await fetchSalesPublic(backofficeUrl, {
                        queryString: `filter[uuid]=${encodeURIComponent(sale.uuid)}`,
                    });
                    setBoSales((prev) => ({ ...prev, [sale.uuid]: data?.data?.[0] || null }));
                } catch (error) {
                    console.error('[LiveSaleLinks] Error fetching back office sale:', error);
                }
            });
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [bidSales, config.siteData, fetchSalesPublic]);

    // ---- Bid server: active item of each open_live sale ----
    const loadActiveItem = useCallback(async (sale) => {
        try {
            const params = new URLSearchParams({
                'filter[id]': sale.item,
                fields: 'id,uuid,label,lot,status,availability_status,current_price,starting_price',
            });
            const response = await fetch(`${config.backendUrl}/api/items?${params.toString()}`);
            if (!response.ok) {
                throw new Error(`Failed to fetch item (${response.status})`);
            }
            const data = await response.json();
            const item = data.data?.[0] || null;
            if (item) {
                setActiveItems((prev) => ({ ...prev, [sale.uuid]: item }));
            }
        } catch (error) {
            console.error('[LiveSaleLinks] Error fetching active item:', error);
        }
    }, [config.backendUrl]);

    useEffect(() => {
        if (!config.backendUrl) return;
        bidSales
            .filter((sale) => sale.status === 'open_live' && sale.item)
            .forEach((sale) => {
                const current = activeItems[sale.uuid];
                // Fetch when the sale moved to a new active item (or first load).
                if (!current || String(current.id) !== String(sale.item)) {
                    loadActiveItem(sale);
                }
            });
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [bidSales, config.backendUrl, loadActiveItem]);

    // ---- Back office: item image gallery for each active item ----
    useEffect(() => {
        const backofficeUrl = config.siteData?.backoffice_url_lang;
        if (!backofficeUrl) return;

        Object.values(activeItems)
            .filter((item) => item?.uuid && itemJsons[item.uuid] === undefined)
            .forEach(async (item) => {
                try {
                    const itemJson = await fetchItemJson(item.uuid, backofficeUrl);
                    setItemJsons((prev) => ({ ...prev, [item.uuid]: itemJson }));
                } catch (error) {
                    console.error('[LiveSaleLinks] Error fetching item images:', error);
                    // Cache the miss so we don't refetch on every render.
                    setItemJsons((prev) => ({ ...prev, [item.uuid]: null }));
                }
            });
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [activeItems, config.siteData, fetchItemJson]);

    // ---- Pusher: live updates on every (non-ended) sale channel ----
    const saleUuidsKey = bidSales.map((sale) => sale.uuid).sort().join(',');
    useEffect(() => {
        if (!config.pusherKey?.key || !config.pusherKey?.cluster || !config.backendUrl || !saleUuidsKey) {
            return undefined;
        }

        pusherService.init({
            key: config.pusherKey.key,
            cluster: config.pusherKey.cluster,
            authEndpoint: `${config.backendUrl}/api/pusher_auth`,
            accessToken: config.accessToken,
        });

        // Public channels only — works for anonymous visitors too.
        saleUuidsKey.split(',').forEach((uuid) => pusherService.subscribe(uuid));

        // Sale changed (status, active item, …) — payload shape varies,
        // so re-pull the authoritative list from the bid server.
        const handleSaleUpdate = () => scheduleRefresh();

        // Item changed: merge into a matching active item (bid placed on
        // the current lot). Updates for an unknown item mean the sale
        // moved on to a new lot — refresh to pick up the new active item.
        const handleItemUpdate = (data) => {
            if (!data) return;
            setActiveItems((prev) => {
                const entry = Object.entries(prev).find(([, item]) =>
                    String(item.id) === String(data.id) || item.uuid === data.uuid
                );
                if (!entry) {
                    scheduleRefresh();
                    return prev;
                }
                const [saleUuid, item] = entry;
                const merged = { ...item };
                Object.keys(data).forEach((key) => {
                    if (data[key] !== null && data[key] !== undefined) {
                        merged[key] = data[key];
                    }
                });
                return { ...prev, [saleUuid]: merged };
            });
        };

        const handleLotTick = (data) => {
            const nested = nestedItemFromLotTick(data);
            if (!nested) return;
            handleItemUpdate(nested);
        };

        pusherService.on('sale__update', handleSaleUpdate);
        pusherService.on('item__update', handleItemUpdate);
        pusherService.on('lot_tick', handleLotTick);

        return () => {
            pusherService.off('sale__update', handleSaleUpdate);
            pusherService.off('item__update', handleItemUpdate);
            pusherService.off('lot_tick', handleLotTick);
        };
    }, [saleUuidsKey, config.pusherKey, config.backendUrl, config.accessToken, scheduleRefresh]);

    // ---- About modal: scroll lock + Esc ----
    useEffect(() => {
        if (!aboutSaleUuid) return undefined;
        const prevOverflow = document.body.style.overflow;
        document.body.style.overflow = 'hidden';
        const onKey = (e) => { if (e.key === 'Escape') setAboutSaleUuid(null); };
        window.addEventListener('keydown', onKey);
        return () => {
            document.body.style.overflow = prevOverflow;
            window.removeEventListener('keydown', onKey);
        };
    }, [aboutSaleUuid]);

    // ---- Helpers ----
    const getBoData = (uuid) => {
        const boSale = boSales[uuid];
        if (!boSale) return null;
        const currentLang = i18n.language === 'zh' ? 'zh-hans' : i18n.language;
        return {
            title: boSale.label?.[currentLang] || boSale.label?.en || '',
            subtitle: boSale.subtitle?.[currentLang] || boSale.subtitle?.en || '',
            description: boSale.description?.[currentLang]?.value || boSale.description?.en?.value
                || boSale.description?.[currentLang] || boSale.description?.en || '',
            dateLocation: boSale.date_and_location_string?.[currentLang] || boSale.date_and_location_string?.en || '',
            imageUrl: boSale.logo?.url_thumb || boSale.logo?.url || null,
            saleNumber: boSale.sale_number || null,
        };
    };

    const formatSaleDates = (uuid) => {
        const boSale = boSales[uuid];
        if (!boSale?.live_sale_date_from) return '';
        const opts = { month: 'long', day: 'numeric', year: 'numeric' };
        const from = new Date(boSale.live_sale_date_from);
        const to = boSale.live_sale_date_to ? new Date(boSale.live_sale_date_to) : null;
        const fromStr = from.toLocaleDateString(i18n.language, opts);
        if (!to || from.toDateString() === to.toDateString()) return fromStr;
        return `${fromStr} – ${to.toLocaleDateString(i18n.language, opts)}`;
    };

    const liveAppUrl = (uuid) => `/live/#/sale/${uuid}`;

    // Collapse to nothing when no sale is in a live phase.
    if (visibleSales.length === 0) return null;

    const aboutSale = aboutSaleUuid ? getBoData(aboutSaleUuid) : null;

    return (
        <div className="live-sale-links">
            {visibleSales.map((sale) => {
                const bo = getBoData(sale.uuid);
                const badge = SALE_BADGE[sale.status];
                const item = sale.status === 'open_live' ? activeItems[sale.uuid] : null;
                const title = bo?.title || sale.label;
                const dates = bo?.dateLocation || formatSaleDates(sale.uuid);
                const isPaused = sale.status !== 'open_live';
                const price = item ? (item.current_price ?? item.starting_price) : null;

                return (
                    <section className="lsl-card" key={sale.uuid}>
                        {bo?.imageUrl && (
                            <a className="lsl-media" href={liveAppUrl(sale.uuid)} target="_blank" rel="noopener noreferrer">
                                <img className="lsl-image" src={bo.imageUrl} alt={title} onError={handleImageError} />
                            </a>
                        )}
                        <div className="lsl-main">
                            <div className="lsl-head-row">
                                <span className={`sbadge ${badge.cls}`}>
                                    <span className="sb-dot" />
                                    {t(badge.key, { defaultValue: badge.fallback })}
                                </span>
                                {bo?.saleNumber && (
                                    <span className="lsl-sale-number">
                                        {t('liveSaleLinks.saleNumber', { defaultValue: 'Sale {{number}}', number: bo.saleNumber })}
                                    </span>
                                )}
                            </div>

                            <h3 className="lsl-title">
                                <a href={liveAppUrl(sale.uuid)} target="_blank" rel="noopener noreferrer" dangerouslySetInnerHTML={{ __html: title }} />
                            </h3>

                            {dates && <p className="lsl-dates" dangerouslySetInnerHTML={{ __html: dates }} />}

                            {isPaused && sale.paused_message && (
                                <p className="lsl-paused-msg">{sale.paused_message}</p>
                            )}

                            {item && (
                                <div className="lsl-live-strip">
                                    <div className="lsl-live-head">
                                        <span className="lsl-now-bidding">
                                            {t('liveSaleLinks.nowBidding', { defaultValue: 'Now Bidding' })}
                                        </span>
                                        <span className="lsl-lot">
                                            {t('liveSaleLinks.lot', { defaultValue: 'Lot' })}{' '}
                                            <span className="lsl-lot-hash">Nº</span> {item.lot}
                                        </span>
                                    </div>
                                    <div className="lsl-live-item">
                                        {itemJsons[item.uuid]?.image_gallery?.images_path?.[0]?.small && (
                                            <img
                                                className="lsl-item-thumb"
                                                src={itemJsons[item.uuid].image_gallery.images_path[0].small}
                                                onError={handleImageError}
                                                alt={item.label}
                                            />
                                        )}
                                        <span className="lsl-item-label">{item.label}</span>
                                        <span className={`sbadge sbadge--sm ${ITEM_BADGE[item.status] || 'paused'}`}>
                                            <span className="sb-dot" />
                                            {t(`liveSaleLinks.itemStatus.${item.status}`, { defaultValue: item.status })}
                                        </span>
                                        {price !== null && price !== undefined && (
                                            <span className="lsl-price">
                                                <span className="lsl-price-lbl">
                                                    {item.current_price !== null && item.current_price !== undefined
                                                        ? t('liveSaleLinks.currentBid', { defaultValue: 'Current Bid' })
                                                        : t('liveSaleLinks.openingPrice', { defaultValue: 'Opening Price' })}
                                                </span>
                                                <span className="lsl-price-val">{formatCurrencyAmount(price, sale.currency)}</span>
                                            </span>
                                        )}
                                    </div>
                                </div>
                            )}

                            <div className="lsl-actions">
                                <a className="lsl-enter" href={liveAppUrl(sale.uuid)} target="_blank" rel="noopener noreferrer">
                                    {sale.status === 'open_live'
                                        ? t('liveSaleLinks.enterLiveAuction', { defaultValue: 'Enter Live Auction' })
                                        : t('liveSaleLinks.viewSale', { defaultValue: 'View Sale' })}
                                </a>
                                {(bo?.subtitle || bo?.description) && (
                                    <button
                                        type="button"
                                        className="btn-secondary-action"
                                        onClick={() => setAboutSaleUuid(sale.uuid)}
                                    >
                                        {t('liveSaleLinks.aboutThisSale', { defaultValue: 'About This Sale' })}
                                    </button>
                                )}
                            </div>
                        </div>
                    </section>
                );
            })}

            {/* About-this-sale modal — body content lives here so cards stay short. */}
            {aboutSale && createPortal(
                <div className="circuit-user-ui">
                    <div
                        className="sale-about-modal__overlay"
                        onClick={() => setAboutSaleUuid(null)}
                        aria-hidden="true"
                    />
                    <div className="sale-about-modal" role="dialog" aria-modal="true" aria-label={t('liveSaleLinks.aboutThisSale', { defaultValue: 'About This Sale' })}>
                        <header className="sale-about-modal__head">
                            <h2 className="sale-about-modal__title">
                                {t('liveSaleLinks.aboutThisSale', { defaultValue: 'About This Sale' })}
                            </h2>
                            <button
                                type="button"
                                className="sale-about-modal__close"
                                onClick={() => setAboutSaleUuid(null)}
                                aria-label={t('liveSaleLinks.close', { defaultValue: 'Close' })}
                            >
                                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                                    <line x1="18" y1="6" x2="6" y2="18" />
                                    <line x1="6" y1="6" x2="18" y2="18" />
                                </svg>
                            </button>
                        </header>
                        <div className="sale-about-modal__body">
                            <p className="sale-about-modal__sale-name" dangerouslySetInnerHTML={{ __html: aboutSale.title }} />
                            {aboutSale.dateLocation && (
                                <div className="sale-about-modal__dates">
                                    <span className="sale-about-modal__dates-label">
                                        {t('liveSaleLinks.dateAndLocation', { defaultValue: 'Date & Location' })}
                                    </span>
                                    <div className="sale-about-modal__dates-value" dangerouslySetInnerHTML={{ __html: aboutSale.dateLocation }} />
                                </div>
                            )}
                            {aboutSale.subtitle && (
                                <p className="sale-about-modal__subtitle" dangerouslySetInnerHTML={{ __html: aboutSale.subtitle }} />
                            )}
                            {aboutSale.description && (
                                <div className="sale-about-modal__description" dangerouslySetInnerHTML={{ __html: aboutSale.description }} />
                            )}
                        </div>
                    </div>
                </div>,
                document.body
            )}
        </div>
    );
};

export default LiveSaleLinks;
